











   L.TileLayer.ArcGISExport = L.TileLayer.extend({
            initialize: function (url, options) {
                this._url = url; // Set the base URL correctly
                L.TileLayer.prototype.initialize.call(this, url, options);
            },
            getTileUrl: function (coords) {
                const tileSize = this.getTileSize();
                const nwPoint = coords.scaleBy(tileSize); // Top-left point of the tile
                const sePoint = nwPoint.add([tileSize.x, tileSize.y]); // Bottom-right point of the tile

                // Convert tile points to projected coordinates (EPSG:102100)
                const nw = this._map.options.crs.project(this._map.unproject(nwPoint, coords.z));
                const se = this._map.options.crs.project(this._map.unproject(sePoint, coords.z));

                // Construct the bounding box (xmin, ymin, xmax, ymax) in meters
                const bbox = [
                    nw.x, // West (xmin)
                    se.y, // South (ymin)
                    se.x, // East (xmax)
                    nw.y, // North (ymax)
                ].join(',');

                // Construct the ArcGIS `export` URL with the necessary parameters
                return `${this._url}/export` +
                    `?dpi=96` +
                    `&transparent=true` +
                    `&format=png8` +
                    `&layers=show:0` +
                    `&bbox=${bbox}` +
                    `&bboxSR=102100` + // Web Mercator spatial reference
                    `&imageSR=102100` +
                    `&size=${tileSize.x},${tileSize.y}` +
                    `&f=image`;
            }
        });
		








