function cmpReadFrontendDebugFlag() {
    var queryHasDebug = /(?:\?|&)(?:cmpdebug|debugjs)=1(?:&|$)/.test(window.location.search);

    try {
        return queryHasDebug || window.localStorage.getItem("cmp_debug_frontend") === "1";
    } catch (error) {
        return queryHasDebug;
    }
}

var cmpFrontendDebugEnabled = cmpReadFrontendDebugFlag();

function cmpDebugLog() {
    if (!cmpFrontendDebugEnabled || !window.console || typeof console.log !== "function") {
        return;
    }

    console.log.apply(console, arguments);
}

function cmpScheduleIdleTask(callback, timeoutMs) {
    if (typeof callback !== "function") {
        return null;
    }

    if (typeof window.requestIdleCallback === "function") {
        return window.requestIdleCallback(callback, {
            timeout: timeoutMs || 1500
        });
    }

    return window.setTimeout(callback, Math.min(timeoutMs || 1500, 1500));
}




