function explodeMulti(jsnMulti) {
    if (jsnMulti.type.substring(0,5)!="Multi") {
        swal("Geometry is not multipart");
    } else {
        var features=[];
        var type = jsnMulti.type.substring(5)
        for (var i=0;i<jsnMulti.coordinates.length;i++) {
            var feature = {type:type, coordinates:jsnMulti.coordinates[i]};
            features.push(feature);
        }
        return features;
    }
}







function mergeLyrEdit(lyrEdit) {
    var jsnEdited=lyrEdit.toGeoJSON();
    var arCoordinates=[];
    var type="Multi"+jsnEdited.features[0].geometry.type;
    for (var i=0;i<jsnEdited.features.length;i++) {
        var coordinates = jsnEdited.features[i].geometry.coordinates;
        arCoordinates.push(coordinates);
    }
    return {type:type, coordinates:arCoordinates};
}





	









// Convert "alice,bob" -> ["alice","bob"]
function listFromCSV(v) {
  return String(v || '')
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
}

// Fire-and-forget mail notify; only needs a few fields.
function notifyShare({ sharedTo, prevSharedTo = [], featureName = '', featureTbl = '', sharedBy = '' }) {
  if (!Array.isArray(sharedTo) || sharedTo.length === 0) return;

  $.post('../php/share_notify.php', {
    // arrays as JSON; backend can also accept CSV
    shared_to: JSON.stringify(sharedTo),
    previous_shared_to: JSON.stringify(prevSharedTo),

    // optional context used only for email content
    feature_name: featureName || '',
    feature_tbl:  featureTbl  || '',
    shared_by:    sharedBy    || ''
  })
  .done(res => cmpDebugLog('Share notify OK:', res))
  .fail(xhr => console.warn('Share notify failed:', xhr.responseText || xhr.statusText));
}





	

		
