// Function to set the inactivity time limit based on device type
function inactivitylimits() {
    let inactivityTimeLimit;

    if (L.Browser.mobile) {
        inactivityTimeLimit = 4 * 60 * 60 * 1000; // 4 hours in milliseconds
    } else {
        inactivityTimeLimit = 2 * 60 * 60 * 1000; // 2 hours in milliseconds
    }

    return inactivityTimeLimit;
}

let inactivityTimeout;
let lastActivityTime = Date.now(); // Track the last activity time in milliseconds
let inactivityTimeLimit = inactivitylimits(); // Store the inactivity time limit


// Function to reset the inactivity timeout
function resetInactivityTimeout() {
    lastActivityTime = Date.now(); // Update the last activity time
    updateTimeoutDisplay()
    // Clear the previous timeout
    clearTimeout(inactivityTimeout);
    // Reset the meta tag
    resetMetaRefresh();
    // Set a new timeout based on the inactivity limit
    inactivityTimeout = setTimeout(checkInactivity, inactivityTimeLimit);
}






// Function to check for inactivity
function checkInactivity() {
    const currentTime = Date.now();

    // Check if the user has been inactive for longer than the allowed limit
    if (currentTime - lastActivityTime >= inactivityTimeLimit) {
        logoutUser();
    } else {
        // If still within the allowed limit, reset the timeout
        resetInactivityTimeout();
    }
}






// Function to log out the user by redirecting to the logout page
function logoutUser() {
	    // Redirect to logout page
    window.location.href = '../../logout.php';
    // Clears all data stored in sessionStorage for the current tab/session
    sessionStorage.clear();

    // Reset user variable if it exists
    if (typeof user !== 'undefined' && user) {
        user = null;
    }

    // Remove localStorage data if it exists
    if (localStorage.usernamestorage) {
        localStorage.removeItem("usernamestorage");
    }


}








