// Single inactivity timeout logic
let inactivityTimeout;
let inactivityDisplayInterval = null;
let inactivityTrackingInitialized = false;
const inactivityTimeLimit = L.Browser.mobile ? 4 * 3600 * 1000 : 3 * 3600 * 1000; // 4h mobile, 3h PC
let lastActivityTime = Date.now();
const inactivityActivityEvents = ['mousemove', 'keydown', 'click', 'scroll', 'touchstart', 'touchmove'];

// Reset inactivity timer
function resetInactivityTimeout() {
    clearTimeout(inactivityTimeout);
    lastActivityTime = Date.now();
    inactivityTimeout = setTimeout(logoutUser, inactivityTimeLimit);
}

// Logout user function
function logoutUser() {
    sessionStorage.clear();
    localStorage.removeItem("usernamestorage");
    user = null;
    window.location.href = '../../logout.php';
}

// Update timeout display
function updateTimeoutDisplay() {
    const currentTime = Date.now();
    const timeElapsed = currentTime - lastActivityTime;
    const timeLeft = inactivityTimeLimit - timeElapsed;

    if (timeLeft <= 0) {
        logoutUser();
    } else {
        const hours = Math.floor(timeLeft / (1000 * 60 * 60));
        const minutes = Math.floor((timeLeft % (1000 * 60 * 60)) / (1000 * 60));
        const seconds = Math.floor((timeLeft % (1000 * 60)) / 1000);

        const display = document.getElementById('timeoutDisplay');
        if (display) {
            display.textContent =
                `Time left: ${hours}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
        }
    }
}

// Single visibility change handler
function handleVisibilityChange(event) {
    if (!document.hidden) {
        resetInactivityTimeout();
        checkcookie();

        const historyTraversal = event.persisted ||
            (typeof window.performance !== "undefined" &&
             window.performance.navigation.type === 2);

        if (historyTraversal && !user) {
            window.location.href = '../../inactive_logout.php';
        }
    }
}

// Single pageshow handler
function handlePageShow(event) {
    checkcookie();

    const historyTraversal = event.persisted ||
        (typeof window.performance !== "undefined" &&
         window.performance.navigation.type === 2);

    if (historyTraversal) {
        if (user) {
            window.location.reload();
        } else {
            window.location.href = '../../inactive_logout.php';
        }
    }
}

function initializeInactivityTracking() {
    if (inactivityTrackingInitialized) {
        return;
    }

    inactivityTrackingInitialized = true;
    resetInactivityTimeout();

    if (inactivityDisplayInterval === null) {
        inactivityDisplayInterval = window.setInterval(updateTimeoutDisplay, 1000);
    }

    inactivityActivityEvents.forEach(function(evt) {
        document.addEventListener(evt, resetInactivityTimeout, true);
    });

    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener("pageshow", handlePageShow);

    const resetBtn = document.getElementById('resetButton');
    if (resetBtn) {
        resetBtn.addEventListener('click', resetInactivityTimeout);
    }
}

window.addEventListener("load", initializeInactivityTracking, { once: true });














