// ======================= IDENTIFY (ESRI) – FULL ROUTINE =======================

// 0) Helpers
function propsTable(props = {}) {
  const keys = Object.keys(props);
  return `<table style="font:13px system-ui; border-collapse:collapse;">
    ${keys.map(k => `<tr><td style="padding:2px 6px;"><b>${k}</b></td><td style="padding:2px 6px;">${props[k]}</td></tr>`).join('')}
  </table>`;
}

function tinyBounds(latlng, meters = 3) {           // small buffer around click
  return L.latLng(latlng).toBounds(meters);
}

function centerOf(layer, fallbackLatLng) {
  if (layer?.getBounds) return layer.getBounds().getCenter();
  if (layer?.getLatLng) return layer.getLatLng();
  return fallbackLatLng;
}

// 1) Display layer (always only latest result). Includes click-to-reopen popup.
const identifyLayer = L.geoJSON(null, {
  style: { color: '#ff3b30', weight: 3, fillOpacity: 0.15 },
  onEachFeature: (feature, layer) => {
    layer.on('click', ev => {
      const at = centerOf(layer, ev.latlng);
      L.popup({ autoPan: true })
        .setLatLng(at)
        .setContent(propsTable(feature.properties || {}))
        .openOn(map);
    });
  }
}).addTo(map);

// keep track of last selected (handy for export buttons, etc.)
let lastIdentifiedFeature = null;
let lastIdentifiedLayer  = null;
let boundsrectanglesss      = null;
let esriAbort            = null;

// 2) The context-menu callback
async function esriIdentifyFromContext(e) {
  const selectEl = document.getElementById('esriquerylayerSelect');
  const url = selectEl ? selectEl.value : null;
  if (!url) {
    console.warn('No ESRI layer URL selected.');
    return;
  }

  // cancel previous in-flight query if user clicks fast
  if (esriAbort) esriAbort.abort();
  esriAbort = new AbortController();

  const { lat, lng } = e.latlng;
  const el = map.getContainer();
  const prevCursor = el.style.cursor;
  el.style.cursor = 'progress';
  if (typeof showSpinner === 'function') showSpinner();

  // clear previous result & selection rectangle
  identifyLayer.clearLayers();
  if (boundsrectanglesss) {
    map.removeLayer(boundsrectanglesss);
    boundsrectanglesss = null;
  }

  // draw a tiny selection rectangle as visual feedback
  const bounds = tinyBounds(e.latlng, 3);
  boundsrectanglesss = L.rectangle(bounds, { color: 'blue', weight: 2, fillOpacity: 0, interactive: false }).addTo(map);

  const pageSize = 500;

  // Esri Leaflet query
  L.esri.query({ url, useCors: true })
    .intersects(bounds)                 // robust “point” pick
    .returnGeometry(true)
    .fields(['*'])                      // all attributes
    .limit(pageSize)
    .run((error, fc) => {
      el.style.cursor = prevCursor;
      if (typeof hideSpinner === 'function') hideSpinner();

      if (error) {
        console.error(error);
        swal && swal('Identify failed (ESRI service).');
        return;
      }
      if (!fc || !fc.features || fc.features.length === 0) {
        L.popup().setLatLng(e.latlng).setContent('No feature here.').openOn(map);
        return;
      }

      // add features (onEachFeature attaches the click handler)
      const group = identifyLayer.addData(fc.features);
      const added = group.getLayers();

      // store first feature/layer as "selected"
      lastIdentifiedFeature = fc.features[0];
      lastIdentifiedLayer   = added[0] || null;

      // zoom to full result
      const b = identifyLayer.getBounds();
      if (b && b.isValid()) {
        map.fitBounds(b, { padding: [20, 20], maxZoom: 18 });
      }

      // initial popup on first feature
      if (lastIdentifiedLayer) {
        const at = centerOf(lastIdentifiedLayer, e.latlng);
        L.popup({ autoPan: true })
          .setLatLng(at)
          .setContent(propsTable(lastIdentifiedFeature.properties || {}))
          .openOn(map);
      }

      // if you still use these elsewhere:
      window.selPts = [fc.features];
    });
}

























