var cmpSpinnerDepth = 0;

function hideSpinner() {
    if (map) {
        if (cmpSpinnerDepth > 0) {
            cmpSpinnerDepth -= 1;
        }

        if (cmpSpinnerDepth > 0) {
            return;
        }

        cmpSpinnerDepth = 0;
        // Hide the spinner
        map.spin(false);
        /*map.touchZoom.enable();
        map.doubleClickZoom.enable();
        map.scrollWheelZoom.enable();
        map.boxZoom.enable();
        map.keyboard.enable();*/
		map.invalidateSize();
    }
}

function showSpinner() {
    if (map) {
        cmpSpinnerDepth += 1;

        if (cmpSpinnerDepth > 1) {
            return;
        }

        map.spin(true, spinopts);
       /* map.touchZoom.disable();
        map.doubleClickZoom.disable();
        map.scrollWheelZoom.disable();
        map.boxZoom.disable();
        map.keyboard.disable();*/
		map.invalidateSize();
    }
}





