$("#btnSync").click(databasesync);

function databasesync() {
    arSyncQue = arSyncQue.filter(function(itm) {
        return itm.result.substring(0, 6) != itm.type;
    });
    localStorage.arSyncQue = JSON.stringify(arSyncQue);

    let requests = arSyncQue.map(function(item, ndx) {
        if (item.type != item.result.substring(0, 6)) {
            let script;
            switch (item.type) {
                case "INSERT":
                    script = "../php/insert_record.php";
                    break;
                case "UPDATE":
                    script = "../php/update_record.php";
                    break;
                case "DELETE":
                    script = "../php/delete_record.php";
                    break;
            }
            return $.ajax({
                url: script,
                data: item.jsn,
                type: "POST",
                success: function(response) {
                    arSyncQue[ndx].result = response;
                },
                error: function(xhr, status, error) {
                    arSyncQue[ndx].result = "ERROR: " + error;
                }
            });
        }
    });

    // After all AJAX requests complete
    $.when(...requests).then(function() {
        localStorage.arSyncQue = JSON.stringify(arSyncQue);

        // Batch refreshes after all requests are done
        refreshGPt();
        refreshGLn();
        refreshpolygon();
        refreshpublicGPt();
        refreshpublicLine();

        // Trigger UI updates
        document.getElementById("gen_point_list").click();
        document.getElementById("gen_line_list").click();
        document.getElementById("gen_polygon_list").click();
    }).always(function() {
        if (hideSpinner) hideSpinner();
    });
}













































