function refreshGPt() {

    if (isOnline()) {


        $.ajax({
            url: '../php/load_data.php',
            data: {
                tbl: 'generic_point',
                where: "createdby='" + user.username + "'"
            },
            type: 'POST',
            success: function(response) {

                if (response.substring(0, 5) == "ERROR") {
                    //cmpDebugLog(response);
                } else {
                    jsnGPt = JSON.parse(response);
                    //cmpDebugLog("jsnGPt  loaded");
                    try {

                        if (localStorage.jsnGPt) {
                            localStorage.removeItem("jsnGPt");
                            //cmpDebugLog("before",localStorage.jsnGPt)
                        }

                        localStorage.jsnGPt = response;
                        //cmpDebugLog("after",localStorage.jsnGPt)
                        //cmpDebugLog("localStorage.jsnGPt  loaded");
                    } catch (error) {
                        cmpDebugLog(error);
                        localStorage.removeItem("jsnGPt");
                    } finally {


                        if (lyrGPt) {
                            //layerControl.removeLayer(lyrGPt);
                            lyrGPt.remove();

                        }

                        $("#hdrFeatures").html(user.username + "'s" + ' ' + "points" + '' + "(" + jsnGPt.features.length + ")");


                        lyrGPt = L.geoJSON(jsnGPt, {
                            onEachFeature: processpoint,
                            pointToLayer: returnGPt
                        });
                        //.addTo(map)

                        if (hash && hash.map._zoom > 13) {
                            map.addLayer(lyrGPt);
                        }

                        //layerControl.addOverlay(lyrGPt, "My points");


                    } //finally

                }


            },
            error: function(xhr, status, error) {
                cmpDebugLog("ERROR: " + error);

                if (hideSpinner) {
                    hideSpinner()
                }
            }
        });


    } //if isOnline
    else {
        swal("No internet available!!using locally stored data.");

        try {
            jsnGPt = JSON.parse(localStorage.jsnGPt);
            $("#hdrFeatures").html(user.username+ "'s" + ' ' + "points" + '' + "(" + jsnGPt.features.length + ")");
        } catch (error)

        {
            cmpDebugLog(error);

            if (hideSpinner) {
                hideSpinner()
            }

        } finally {

            if (lyrGPt) {

                lyrGPt.remove();

            }


            lyrGPt = L.geoJSON(jsnGPt, {
                    onEachFeature: processpoint,
                    pointToLayer: returnGPt
                })
                .addTo(map);

        }

    } //finally


} //refreshGPt() {	




