let _usersByUsername = null; // Map username -> { full, firstname, lastname, username }
function getUsersMap() {
  if (_usersByUsername) return $.Deferred().resolve(_usersByUsername).promise();
  return $.ajax({
    url: '../php/all_users.php',
    type: 'POST'
  }).then(function (resp) {
    let arr = [];
    try {
      arr = JSON.parse(resp);
      if (!Array.isArray(arr)) arr = Object.values(arr);
    } catch (e) { arr = []; }
    const m = new Map();
    arr.forEach(u => {
      if (u && u.username) {
        const full = (`${(u.firstname||'').trim()} ${(u.lastname||'').trim()}`).trim();
        m.set(String(u.username).trim(), { full, username: String(u.username).trim() });
      }
    });
    _usersByUsername = m;
    return m;
  }, function () { return new Map(); });
}

// helper: from "First Last username" → "username"
function extractUsernameFromValue(v) {
  return String(v || "").trim().replace(/\s+/g, " ");  // keep internal spaces
}


