function refreshGLn() {

    if (isOnline()) {

        $.ajax({
            url: '../php/load_data.php',
            data: {
                tbl: 'generic_line',
                where: "createdby='" + user.username + "'"
            },
            type: 'POST',
            success: function(response) {
                if (response.substring(0, 5) == "ERROR") {
                    //cmpDebugLog(response);
                } else {
                    jsnGLn = JSON.parse(response);
                    //cmpDebugLog("jsnGLn  loaded");
                    try {

                        if (localStorage.jsnGLn) {
                            localStorage.removeItem("jsnGLn");

                        }

                        localStorage.jsnGLn = response;
                        //cmpDebugLog("localStorage.jsnGLn  loaded");
                    } catch (error) {

                        cmpDebugLog(error);
                        localStorage.removeItem("jsnGLn");
                    } finally {

                        if (lyrGLn) {
                            //layerControl.removeLayer(lyrGLn);
                            lyrGLn.remove();
                        }


                        $("#hdrFeaturesline").html(user.username + "'s" + ' ' + "lines" + '' + "(" + jsnGLn.features.length + ")");

                        lyrGLn = L.geoJSON(jsnGLn, {
                            onEachFeature: processGLn,
                            style: {
                                color: 'red',
                                weight: 6,
                                dashArray: "4, 6"
                            }
                        })
                        //.addTo(map)
                        ;
                        //layerControl.addOverlay(lyrGLn, "My lines");
                        if (lyrGLn && hash && hash.map._zoom > 13) {
                            map.addLayer(lyrGLn);
                        }

                    } //finally



                }
            },

            error: function(xhr, status, error) {
                cmpDebugLog("ERROR: " + error);

                if (hideSpinner) {
                    hideSpinner()
                }

            }
        });


    } //  if (isOnline()){
    else {
        // swal("No internet available!!using locally stored data."); 

        try {
            jsnGLn = JSON.parse(localStorage.jsnGLn);
            $("#hdrFeaturesline").html(user.username + "'s" + ' ' + "lines" + '' + "(" + jsnGLn.features.length + ")");
        } catch (error) {

            cmpDebugLog(error)

            if (hideSpinner) {
                hideSpinner()
            }

        } finally {
            if (lyrGLn) {

                lyrGLn.remove();
            }
            lyrGLn = L.geoJSON(jsnGLn, {
                onEachFeature: processGLn,
                style: {
                    color: 'darkred',
                    weight: 6,
                    dashArray: "4, 6"
                }
            }).addTo(map);


        }

    } //finally


}










function processGLn(feature, layer) {



    var p = feature.properties;
    layer.options.bubblingMouseEvents = false;

    p.index = '<b>• My Lines: </b>' + feature.properties.name + " Date created: " + '<b>' + feature.properties.created + '</b>';

    //drawnItems.addLayer(layer);

    layer.addTo(cmpdatasearch);




    setTimeout(function() {
        if (layer.feature.properties && layer.feature.properties.id && layer.feature.properties.sharedto) {

            let tablegpt = document.getElementById('featuresline');
            let targetTDsgpt = tablegpt.querySelectorAll('tr > td .btnEditGen');
            for (let i = 0; i < targetTDsgpt.length; i++) {
                let idgpt = $(targetTDsgpt[i]).attr("data-id");
                let idsdsd = layer.feature.properties.id;
                let sdfsdffd = tablegpt.querySelectorAll('#sharedtoth');
                if (idgpt == idsdsd) {
                    sdfsdffd[i].innerHTML += '<img height="20px" width="20px" alt="testImage" title=' + layer.feature.properties.sharedto + ' src="./images/icons8-share-30.png"> </img>';
                    //$(sdfsdffd[i]).prepend("<img height='200' width='200' alt='testImage' src='https://avatars.githubusercontent.com/u/47340995?v=4'> </img>");

                    $(sdfsdffd[i]).click(function() {
                        swal("Shared with: " + layer.feature.properties.sharedto)
                    })


                }
            }

        }

    }, 1000);




    layer.on('click', function(e) {

        layer = e.target;
        var actionLatLng = cmpGetFeatureActionLatLng(layer, e);

        if (e && e.originalEvent) {
            L.DomEvent.stop(e.originalEvent);
        }

        $("#btnGenFormInsert").hide();
        $("#btnGenFormUpdate").show();


        delete layer.feature.properties.number;



        $("#attachmentbase64").hide();
        $("#attachmentbase64").val("");
        $("#attachmentbase64preview").hide();
        $("#attachment").hide();
        $("#attachmentinputdiv").hide();
        //$("#attachmentinputdiv").hide();
        $("#attachmentbase64preview").val("");
        $("#attachment").val("");
        //$("#attachmentinputdiv").val("");
        $("#metadata").val("");



        var sharedfeatures = layer.feature.properties.sharedto;

        if (!sharedfeatures) {
            delete layer.feature.properties.sharedto;
        } else {


        }



        $(".mdl-card--sharewith")[0].MaterialSwitch.off();
        options = [];
        usernames = [];
        $("#userid").remove();
        $("#labeluserid").remove();
        $("#selectid").html('');
        $("#selectuser").hide();
        $("#selectid").hide();

        $("#sharedtoid").val('');
        $("#sharedtoid").val(layer.feature.properties.sharedto);




        $(".mdl-card--sharewith").change(function(event) {
            if ($(this).hasClass("is-checked")) {

                var value1ser;
                var valuessecond;
                value1ser = null;
                valuessecond = null;

                var sharetoidvalue = $("#sharedtoid").val();
                if (sharetoidvalue !== null) {

                    setTimeout(function() {
                        var str_array = $("#sharedtoid").val().split(',');
                        for (var i = 0; i < str_array.length; i++) {
                            str_array[i] = str_array[i].replace(/^\s*/, "").replace(/\s*$/, "");
                            value1ser = $("#sharedtoid").val();
                            valuessecond = str_array[i];

                            if (value1ser.indexOf(valuessecond) > -1) {
                                $("#selectid").find("input[type=checkbox][name='" + str_array[i] + "']").filter(function() {
                                    return this.value == str_array[i];
                                }).prop("checked", true);
                            } //for(var i = 0; i < str_array.length; i++) {

                        }
                    }, 200); //timeout


                }

            } // if ($(this).hasClass("is-checked")) {
            else

            {
                $("#sharedtoid").val('');
                value1ser = null;
                valuessecond = null;
            }
        }); //$(".mdl-card--sharewith").change(function (event) {




        sidebar.hide();



        delete layer.feature.properties.metadata;
        delete layer.feature.properties.attachment;


        var lineinfo = "";
        for (var k in layer.feature.properties) {
            var v = String(layer.feature.properties[k]);
            //delete layer.feature.properties.attachment;
            lineinfo += '<b>' + k + '</b><br>' + v + '<br>' + '<hr style="margin:5px 0px;  border-style: dotted; border-color: forestgreen;">';

        };

        mapinfo.innerHTML = lineinfo + cmpBuildNavigateButtonHtml(actionLatLng);


        sidebar.show();




        try {

            var indexedline = feature.properties.id;
            var parentline = document.getElementById("featuresline");
            var tableline = cmpGetFeatureTableElement(parentline);
            var targetTDs = tableline ? tableline.querySelectorAll('tr > td .btnEditGen') : [];


            for (var i = 0; i < targetTDs.length; i++) {
                var td = targetTDs[i];
                targetTDs[i].style.color = "black";
                var idline = $(targetTDs[i]).attr("data-id");
                if (idline == indexedline) {
                    targetTDs[i].style.color = "yellow";
                    targetTDs[i].click();

                    $(td).find(".btnEditGen").trigger('click');


                } //and of string compare


            } //end of loop

        } catch (error) {

            cmpDebugLog(error)
        }



        $("#accordionphp").accordion({
            active: 1,
        });

        $("#accordionphpshared").accordion({
            collapsible: true,
            active: false
        });

        new LeafletToolbar.EditToolbar.Popup(actionLatLng, {
            actions: savedmarkeredit
        }).addTo(map, layer);

        layer.showMeasurements();

        layer.bindPopup();

        drawnItemsarray.length = 0; //cmpDebugLog("2 from group2: " + e.layer._leaflet_id);
        drawnItemsarray = [];
        var drawnitemtogeojson = layer.toGeoJSON(); //cmpDebugLog(pointeddrawnitem);
        drawnItemsarray.push(drawnitemtogeojson); //cmpDebugLog('drawnItemsarray'+ JSON.stringify(drawnItemsarray));




    }); //end of onclick function




}




