function refreshpolygon() {
    if (isOnline()) {
        $.ajax({
            url: '../php/load_data.php',
            data: {
                tbl: 'polygon',
                where: "createdby='" + user.username + "'"
            },
            type: 'POST',
            success: function(response) {
                if (response.substring(0, 5) == "ERROR") {
                    // Handle error if response is an error
                } else {
                    jsnPolygon = JSON.parse(response);

                    try {
                        if (localStorage.jsnPolygon) {
                            localStorage.removeItem("jsnPolygon");
                        }
                        localStorage.jsnPolygon = response; // Save response to local storage
                    } catch (error) {
                        cmpDebugLog(error);
                        localStorage.removeItem("jsnPolygon");
                    } finally {

                        // Modify the response to replace circle-like polygons with actual circles
                        jsnPolygon = transformPolygonsToCircles(jsnPolygon);

                        if (lyrGPolygon) {
                            lyrGPolygon.remove(); // Remove old layer
                        }

                        $("#hdrFeaturespolygon").html(user.username + "'s polygons (" + jsnPolygon.features.length + ")");

                        lyrGPolygon = L.geoJSON(jsnPolygon, {
                            pointToLayer: function(feature, latlng) {
                               if (feature.properties.shapecolor === "circle") {
                                    // Create a circle with the stored radius
                                    return L.circle(latlng, {
                                        radius: feature.properties.radius,
                                        color: 'yellow'
                                    });
                                } else {
                                    return L.marker(latlng); // For regular points
                                }
                            },
                            onEachFeature: processpolygon, // Process each feature as usual
                            style: {
                                color: 'yellow',
                                dashArray: "4, 6"
                            }
                        });

                        if (hash && hash.map._zoom > 13) {
                            map.addLayer(lyrGPolygon);
                        }
                    }
                }
            },
            error: function(xhr, status, error) {
                cmpDebugLog("ERROR: " + error);
            }
        });

    } else {
        swal("No internet available!! Using locally stored data");

        try {
            jsnPolygon = JSON.parse(localStorage.jsnPolygon);
            $("#hdrFeaturespolygon").html(user.username + "'s polygons (" + jsnPolygon.features.length + ")");
        } catch (error) {
            cmpDebugLog(error);
        } finally {

            // Modify the local data to replace polygons with circles
            jsnPolygon = transformPolygonsToCircles(jsnPolygon);

            if (lyrGPolygon) {
                lyrGPolygon.remove(); // Remove old layer
            }

            lyrGPolygon = L.geoJSON(jsnPolygon, {
                pointToLayer: function(feature, latlng) {
                 
						if (feature.properties.shapecolor === "circle") {
                        return L.circle(latlng, {
                            radius: feature.properties.radius,
                            color: 'darkred'
                        });
                    } else {
                        return L.marker(latlng); // For regular points
                    }
                },
                onEachFeature: processpolygon, // Process each feature as usual
                style: {
                    color: 'darkred',
                    dashArray: "4, 6"
                }
            });

            lyrGPolygon.addTo(map); // Add the layer to the map
        }
    }
}




// Function to convert circle-like polygons into actual circles in the GeoJSON data
function transformPolygonsToCircles(geojson) {
    geojson.features = geojson.features.map(function(feature) {
        // If the feature represents a circle based on its properties
        if (feature.properties.shapecolor === "circle") {
            var layer = L.geoJSON(feature); // Create a temporary Leaflet layer to calculate geometry
            var { center, radius } = calculateCenterAndRadiusFromPolygon(layer);

            // Replace the polygon geometry with a new Point for the center
            feature.geometry = {
                type: "Point",
                coordinates: [center.lng, center.lat] // Use the center of the circle as a point
            };

            // Update properties to indicate it's now a circle with a radius
            feature.properties.radius = radius;
			feature.properties.shapecolor = "circle";
            feature.properties.kolos = { type: "Circle" }; // Mark as circle
        }
        return feature;
    });
    return geojson; // Return the modified GeoJSON
}

// Function to dynamically calculate the center and radius from a polygon
function calculateCenterAndRadiusFromPolygon(layer) {
    var latLngs = layer.getLayers()[0].getLatLngs()[0];  // Assuming it's a simple polygon, not a multi-polygon
    
    var center = calculateCentroid(latLngs); // Get the centroid of the polygon
    var radius = center.distanceTo(latLngs[0]); // Distance from center to first point (radius)

    return { center: center, radius: radius };
}

// Function to calculate the centroid of a polygon
function calculateCentroid(latLngs) {
    var sumLat = 0;
    var sumLng = 0;
    
    latLngs.forEach(function(latlng) {
        sumLat += latlng.lat;
        sumLng += latlng.lng;
    });
    
    var centerLat = sumLat / latLngs.length;
    var centerLng = sumLng / latLngs.length;
    
    return L.latLng(centerLat, centerLng); // Return as a LatLng object
}





