function findFeature(tbl, id) {




    if (isOnline()) {

        $.ajax({
            url: "../php/load_data.php",
            data: {
                tbl: tbl,
                where: "id=" + id
            },
            type: "POST",
            success: function(response) {
                if (response.substring(0, 5) == "ERROR") {
                    $("#features").append(response);

                } else {
                    //stopAutolocate();

                    var jsn = JSON.parse(response).features[0];

                    if (lyrSearch) {
                        lyrSearch.remove();
                    }
                    if (jsn.geometry.type == "Point") {


                        var ll = L.latLng(jsn.geometry.coordinates[1], jsn.geometry.coordinates[0])


                        lyrSearch = L.circleMarker(ll, {
                            color: 'red',
                            stroke: true,
                            weight: 0,
                            radius: 5,
                            boostType: 'circle',
                            boostScale: boostScale,
                            boostExp: boostExp,
                            //bubblingMouseEvents: false
                        }).bindPopup(jsn.properties.name).addTo(map)
                        //.openPopup();
                        map.setView(ll, 19);


                    }

                    if (jsn.geometry.type == "MultiLineString") {

                        //cmpDebugLog(jsn.geometry.type);
                        //lyrSearch= L.geoJSON(jsn, {style:{color:'yellow', weight:2}}).addTo(map);
                        lyrSearch = L.geoJSON(jsn, {
                            style: {
                                color: 'darkred',
                                weight: 2
                            }
                        });
                        map.fitBounds(lyrSearch.getBounds());

                    }



                    if (jsn.geometry.type == "Polygon") {

                        //cmpDebugLog(jsn.geometry.type);
                        //lyrSearch= L.geoJSON(jsn, {style:{color:'yellow', weight:2}}).addTo(map);
                        lyrSearch = L.geoJSON(jsn, {
                            style: {
                                color: 'darkred',
                                weight: 2
                            }
                        });
                        map.fitBounds(lyrSearch.getBounds());

                    } else {}
                    openSubScreen();

                }
            },
            error: function(xhr, status, error) {

                $("#features").append("ERROR: " + error);
                if (hideSpinner) {
                    hideSpinner()
                }
            }
        });




    } else {
        //stopAutolocate();

        var jsn = returnFeatureOffline(tbl, id);

        if (lyrSearch) {
            lyrSearch.remove();
        }
        if (jsn.geometry.type == "Point") {

            var ll = L.latLng(jsn.geometry.coordinates[1], jsn.geometry.coordinates[0]);
            lyrSearch = L.circleMarker(ll, {
                color: 'darkred',
                weight: 2,
                radius: 13
            }).addTo(map);
            map.setView(ll, 19);

        }

        if (jsn.geometry.type == "MultiLineString") {

            lyrSearch = L.geoJSON(jsn, {
                style: {
                    color: 'darkred',
                    weight: 2
                }
            });
            map.fitBounds(lyrSearch.getBounds());

        }

        if (jsn.geometry.type == "Polygon") {

            lyrSearch = L.geoJSON(jsn, {
                style: {
                    color: 'darkred',
                    weight: 2
                }
            });
            map.fitBounds(lyrSearch.getBounds());

        }

        // else{}
        openSubScreen();

    }


    if (L.Browser.mobile) {
        hidemenubars()
    }


}




function returnFeatureOffline(tbl, id) {

    switch (tbl) {
        case "generic_point":
            var jsnFocus = jsnGPt.features;
            break;
        case "generic_line":
            var jsnFocus = jsnGLn.features;
            break;

        case "polygon":
            var jsnFocus = jsnPolygon.features;
            break;

        case "polygon":
            var jsnFocus = jsnPolygon.features;
            break;


    }

    var ftrID = false;
    jsnFocus.forEach(function(ftr, ndx) {

        if (ftr.properties.id == id) {
            ftrID = ftr;
        }


    })
    return ftrID;



}











		
				
				
