function editscenario(tbl, id) {


    $.ajax({
        url: "../php/load_data.php",
        data: {
            tbl: tbl,
            where: "scenariouniqueidentif=" + id
        },
        type: "POST",
        success: function(response) {
            if (response.substring(0, 5) == "ERROR") {
                $("#features").append(response);
            } else {
                var jsn = JSON.parse(response).features;
                cmpDebugLog("jsnjsnjsnjsn", jsn)


            }
        },

        error: function(xhr, status, error) {
            cmpDebugLog("ERROR: " + error);

            if (hideSpinner) {
                hideSpinner()
            }

        }

    })




}




function insertGenForm(tbl) {



    var jsn = returnFormData("inpGenForm");
    //cmpDebugLog(jsn);

    if (jsn.name == "") {

        swal("Please enter a name for this geometry");
        $("#btnGenFormInsert").prop("disabled", false);

    } else {



        jsn.tbl = tbl;


        //cmpDebugLog(" tbl",tbl);	

        delete jsn.id;

        if (tbl == "generic_point") {
            var geojson = {};
            geojson.type = "Point";
            geojson.coordinates = [Number(jsn.lng), Number(jsn.lat)];
            jsn.geojson = JSON.stringify(geojson);

        }



        delete jsn.lng;
        delete jsn.lat;

        if (isOnline()) {


            insertRecord(jsn, function(response) {

                openSubScreen();
                $("#divGenForm").hide();
                switch (tbl) {

                    case "generic_point":
                        $("#btnGenFormInsert").prop("disabled", false);
                        refreshGPt();
                        //$("#divGenForm").hide();
                        populateFeatures("generic_point");
                        $("#myfeaturesModal").hide();

                        break;

                    case "generic_line":
                        $("#btnGenFormInsert").prop("disabled", false);
                        refreshGLn();
                        // lyrVertices.clearLayers();
                        //$("#divGenForm").hide();
                        populateFeatures("generic_line");
                        $("#myfeaturesModal").hide();
                        break;

                    case "polygon":
                        $("#btnGenFormInsert").prop("disabled", false);
                        refreshpolygon();
                        //lyrVertices.clearLayers();
                        //$("#divGenForm").hide();
                        populateFeatures("polygon");
                        $("#myfeaturesModal").hide();
                        break;

                }

                //map.flyTo(map.getBounds().getCenter(), 15);



            });

        } else

        {
            arSyncQue.push({
                type: 'INSERT',
                timestamp: returnCurrentTimestamp(),
                result: "NONE",
                jsn: jsn
            })
            localStorage.arSyncQue = JSON.stringify(arSyncQue);
            updateSyncCount();
            $("#btnGenFormInsert").prop("disabled", false);
            $("#myfeaturesModal").hide();
            swal("Your shape will be saved to the database when you go back online");
        }




    } //end of else statement




} //end of insertGenForm




function updateGenForm(tbl) {

    var attachmentname = $('#attachmentvalue').val();
    var cleanedattachmentname = attachmentname.replace(/.*[\/\\]/, '');
    var attachmentpathtoserver;
    /*
				 if (location.hostname === "localhost" || location.hostname === "127.0.0.1"){
                 //alert("It's a local server!");
				  attachmentpathtoserver = "https://localhost/cmpmap.org/content/php/uploads/";
				 }
				 else
				 {
					 attachmentpathtoserver = "https://cmpmap.com/content/php/uploads/";
				 }
               */
    attachmentpathtoserver = "../php/uploads/";

    var withoutspaces = cleanedattachmentname.replace(/\s/g, '');
    //cmpDebugLog('withoutspaces',withoutspaces);
    $("#attachment").val(attachmentpathtoserver + withoutspaces);
    $('#submitattachment').click();


    var jsn = returnFormData("inpGenForm");
    //cmpDebugLog("jsn"+JSON.stringify(jsn));/*egw to evala*/

    if (jsn.name == "") {
        swal("Please enter a name for this geometry");
        $("#btnGenFormInsert").prop("disabled", false);

    } else {

        jsn.tbl = tbl;

        if (tbl == "generic_point") {

            var geojson = {};
            geojson.type = "Point";
            geojson.coordinates = [Number(jsn.lng), Number(jsn.lat)];
            jsn.geojson = JSON.stringify(geojson);
            //cmpDebugLog('jsn.geojson'+jsn.geojson);


        } else if (tbl == "generic_line") {
            geojson = $("#gen_geojson").val();
            //delete jsn.attachment;
            //cmpDebugLog(geojson);
            //	cmpDebugLog('jsn'+JSON.stringify(geojson));
            // alert('na grapsw expression');

            $("#attachment").val("");


            $("#attachmentbase64preview").val("");

            $("#metadata").val('');


            //$("#attachmentinputdiv").val("");

        } else if (tbl == "polygon") {

            geojson = $("#gen_geojson").val();
			
            // delete jsn.attachment;
            //cmpDebugLog('jsn'+JSON.stringify(geojson));
            //alert('na grapsw expression');

            $("#attachment").val("");

            $("#attachmentbase64preview").val("");

            $("#metadata").val("");


            //$("#attachmentinputdiv").val("");

        }


        delete jsn.lng;
        delete jsn.lat;


        if (isOnline()) {

            updateRecord(jsn, function(response) {
                openSubScreen();
                // map.flyTo(map.getBounds().getCenter(), 18);
                switch (tbl) {

                    case "generic_point":
                        refreshGPt();
                        refreshpublicGPt();
                        $("#gen_point_list").trigger('click');



                        break;

                    case "generic_line":
                        //delete jsn.attachment;
                        refreshGLn();
                        refreshpublicLine();
                        $("#gen_line_list").trigger('click');
                        //lyrVertices.clearLayers();
                        break;

                    case "polygon":
                        //delete jsn.attachment;
                        refreshpolygon();
                        refreshpublicpolygon();
                        //lyrVertices.clearLayers();
                        $("#gen_polygon_list").trigger('click');
                        break;




                }

            });

        } else {
            arSyncQue.push({
                type: 'UPDATE',
                timestamp: returnCurrentTimestamp(),
                result: "NONE",
                jsn: jsn
            })
            localStorage.arSyncQue = JSON.stringify(arSyncQue);
            updateSyncCount();

        }


        ///////////




    }

}





















