var storypathLineGroup = L.layerGroup().addTo(map);
var storypathLine;
function createlines(drawnlinearray) {
    if (map.hasLayer(lyrscenario)) {

storypathLineGroup.clearLayers();
		
        var c = [];
        var cz = [];
        var valuesSoFar = [];

        function onlyUnique(value, index, self) {
            return self.indexOf(value) === index;
        }
        var unique = drawnlinearray.filter(onlyUnique);
        valuesSoFar.push(unique)
        for (var i = 0; i < unique.length; ++i) {
            var value = unique[i];
            lyrscenario.eachLayer(function(layer) {
                var scenariouniqueidentif = layer.feature.properties.scenariouniqueidentif;
                var scenariouniid = layer.feature.properties.scenarioid;

                if (typeof scenariouniqueidentif === "string") {
                    //cmpDebugLog("scenariouniqueidentif is a string");
                    scenariouniqueidentif = parseInt(scenariouniqueidentif);

                } else

                {
                    ///cmpDebugLog("is a number");

                }




                if ((scenariouniqueidentif) && (value === scenariouniqueidentif)) {
                    var x = layer._latlng.lat;
                    var y = layer._latlng.lng;
                    var z = layer.feature.properties.scenarioid;
                    cz.push([x, y, z]);
                    var sortedarray = cz.sort((a, b) => {
                        return a[2] - b[2];
                    });
                    var polylinePoints = sortedarray.map(el => {
                        return [el[0], el[1]];
                    });
                     storypathLine = L.polyline(polylinePoints, {
                        color: "#FFFF00"
                    }).addTo(storypathLineGroup);
                } else {
                    c = [];
                    cz = [];
                }
            });
        }
    } //if(map.hasLayer(lyrscenario)){

    map.invalidateSize()
}




function openscenariostory(templayer, drawnlinearrayfeatures) {

    cmpDebugLog("templayer",templayer);
    cmpDebugLog("templayer drawnlinearrayfeatures",drawnlinearrayfeatures);	
    tempscenarioclickedarray = [];
    storydataaray = [];
    drawnlinearrayfeatures.map(function(p) {
        if (templayer == p.properties.scenariouniqueidentif) {
            //cmpDebugLog(p);

            tempscenarioclickedarray.push(p);
        }
    })
    //cmpDebugLog("tempscenarioclickedarray",tempscenarioclickedarray);
    var storyjsonlayer;
    storyjsonlayer = {
        type: 'FeatureCollection',
        features: tempscenarioclickedarray.map(function(feature) {
            //cmpDebugLog("map",feature);
            return {
                type: 'Feature',
                properties: feature,
                geometry: {
                    type: "Point",
                    coordinates: feature.geometry.coordinates,
                }
            }
        })
    };

    storydataaray.push(storyjsonlayer);
    initscenariostoryMap(storyjsonlayer);
}




