/*
 * L.Control.WMSLegend is used to add a WMS Legend to the map
 */



// Function to create the legend
var createLegend = function(layers) {
    var legend = L.control({
        position: 'bottomright'
    });
    legend.onAdd = function(map) {
        var div = L.DomUtil.create('div', 'leaflet-control-wms-legend');
        var content = '';
        layers.forEach(function(layer) {

            url = "" + layer._url + "" + "format=image/png&request=getlegendgraphic&service=WMS&singletile=false&transparent=true&version=1.1.1&scale=1000000&layer=" + layer.options.layers + ""
            cmpDebugLog("legend", layer);


            var name = layer.options.layers;
            if (name === "high-risk-aggr-wildfire-risk") {
                content += '<b style="background-color:white;">Legend for ' + layer.options.layers + '</b><br><img src="https://gwis-reports.s3-eu-west-1.amazonaws.com/WFRA/legend_var-risk-aggr-l3p122_unit-dimensionless_stat-rank_class3-3.png"></img> ' + layer.options.attribution + '<br>';

            }

            //
            //



            content += '<b style="background-color:white;">Legend for ' + layer.options.layers + '</b><br><img src="' + layer._url + '?format=image/png&request=getlegendgraphic&service=WMS&singletile=false&transparent=true&version=1.1.1&scale=1000000&layer=' + layer.options.layers + '"></img> ' + layer.options.attribution + '<br>';
            cmpDebugLog("content", content);
        });
        div.innerHTML = content;
        return div;
    };
    return legend;
};


// Function to update the legend content
var updateLegend = function(layers) {
    map.removeControl(legend);
    legend = createLegend(layers);
    legend.addTo(map);
};




