function removeMarkerColor(layer) {
    cmpDebugLog("layer for deletion", layer);


    // Set the shapecolor property to null
    if (layer.feature && layer.feature.properties) {
        cmpDebugLog("layer.feature.properties.shapecolor", layer.feature.properties.shapecolor);
        layer.feature.properties.shapecolor = null; // Nullify the shapecolor
		$("#shapecolor").val("");
    }
    
	
	
    // Set the default icon (optional, can be transparent or default)
    var infoSvgIcon = `
        <svg xmlns="http://www.w3.org/2000/svg" width="25" height="25" viewBox="0 0 25 25">
          <circle cx="12.5" cy="12.5" r="10" fill="#ffffff" stroke="#000000" stroke-width="1"/>
          <text x="12.5" y="16" font-family="Arial" font-size="14" fill="#000000" text-anchor="middle" font-weight="900" dominant-baseline="middle">i</text>
        </svg>
    `;




    layer.setIcon(L.icon({
        iconUrl: 'data:image/svg+xml;base64,' + btoa(infoSvgIcon),
        iconSize: [25, 25],
        iconAnchor: [12.5, 12.5],
        popupAnchor: [0, -12.5]
    }));
	

	

    // Trigger the backend to update the shapecolor to null
    swal({
        title: "Do you want to remove the colored marker?",
        text: "This action will remove the color and reset the marker.",
        icon: "warning",
        buttons: ["No", "Yes, remove colored marker!"],
        dangerMode: true
    }).then(function(isConfirm) {
        if (isConfirm) {
            // Trigger backend update to save null in the database
			
            $("#btnGenFormUpdate").trigger("click");
        } else {
            refreshGPt();
            refreshpublicGPt();
            $("#gen_point_list").trigger('click');
        }
    });
	
}




