function showCoordinates(e) {
    const infoHTML = document.getElementsByClassName("info")[0].innerHTML;
    const labelHTML = document.getElementsByClassName("labelFirst")[0].innerHTML;

    const cleanText = infoHTML.replace(/<br>/gi, "\n").replace(/<b>/gi, "").replace(/<\/b>/gi, "");
    const cleanDMS = labelHTML.replace(/<br>/gi, "\n");

    const latMatch = cleanText.match(/Lat:([0-9.\-]+)/);
    const lonMatch = cleanText.match(/Lon:([0-9.\-]+)/);
    const mgrsMatch = cleanText.match(/MGRS:([^\n]+)/);

    const latlon = `${latMatch?.[1]}, ${lonMatch?.[1]}`;
    const mgrs = mgrsMatch?.[1];
    const dms = cleanDMS.replace(/DMS:\s*/, "").trim();

    // Escape single quotes for HTML safety
    const escapeForHTML = (str) => str.replace(/'/g, "\\'");

    const htmlContent = `
        <div style="text-align:left; background: #fff9db; padding: 10px; border-radius: 6px;">
            <p><b>Lat, Lon:</b> ${latlon} <button onclick="copyText('${escapeForHTML(latlon)}')">📋</button></p>
            <p><b>MGRS:</b> ${mgrs} <button onclick="copyText('${escapeForHTML(mgrs)}')">📋</button></p>
            <p><b>DMS:</b> ${dms} <button onclick="copyText('${escapeForHTML(dms)}')">📋</button></p>
        </div>
    `;

    swal({
        title: "You Clicked At:",
        content: {
            element: "div",
            attributes: {
                innerHTML: htmlContent
            }
        },
        button: {
            text: "OK",
            className: "sweet-warning"
        }
    });
}


// 📋 Copy to clipboard
function copyText(text) {
    const temp = document.createElement("textarea");
    temp.value = text;
    document.body.appendChild(temp);
    temp.select();
    document.execCommand("copy");
    document.body.removeChild(temp);

    swal("Copied!", `"${text}" has been copied to clipboard.`, "success");
}





