// ---- Globals ----
var imageContainerMargin = 70; // only used cosmetically now
var currentBox = 0;
var scrollPosition = 0;
var isProgrammaticScroll = false; // ignore scroll->map sync during animated jumps
var storyDataCache = null;        // keep the loaded GeoJSON
var storydataLayer = null;        // optional overlay

// Helper: safe HTML
function esc(s){ return String(s || '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[m])); }

// Get the content top of a slide using its real DOM position (robust)
function getSlideTop(id) {
  var el = document.getElementById('container' + id);
  if (!el) return 0;
  // Scroll so the slide starts ~100px from the top (your original bias)
  return Math.max(0, el.offsetTop - 100);
}

// Strong “focus” setter (never leaves active grey)
function setActiveBox(id) {
  currentBox = id;
  $('.image-container').removeClass('inFocus outFocus');
  $('#container' + id).addClass('inFocus');
  $('.image-container').not('#container' + id).addClass('outFocus');
}

// Lightweight scroll watcher (for map.invalidateSize only)
function attachBasicScrollWatch() {
  $('div#contents')
    .off('scroll.basic')
    .on('scroll.basic', function() {
      scrollPosition = $(this).scrollTop();
      map.invalidateSize();
    });
}

// Decide the active slide by whichever slide's **center** is closest to the
// viewport center of #contents. This is resilient to variable heights/images.
function findActiveSlideByViewport() {
  var $contents = $('div#contents');
  var sTop = $contents.scrollTop();
  var viewportCenter = sTop + ($contents.height() / 2);

  var bestId = null, bestDist = Infinity;

  $('[id^=container]').each(function(){
    var m = this.id.match(/^container(\d+)$/);
    if (!m) return;

    var id = parseInt(m[1], 10);
    var top = this.offsetTop;                 // content-coordinate
    var bottom = top + this.offsetHeight;
    var center = (top + bottom) / 2;
    var dist = Math.abs(center - viewportCenter);

    if (dist < bestDist) { bestDist = dist; bestId = id; }
  });

  return bestId;
}

// Single scroll->map sync (no per-slide listeners)
function attachSlideSyncOnScroll() {
  $('div#contents')
    .off('scroll.sync')
    .on('scroll.sync', function() {
      if (isProgrammaticScroll) return;

      var id = findActiveSlideByViewport();
      if (id && id !== currentBox) {
        setActiveBox(id);

        var $c = $('#container' + id);
        var coord = $c.data('coord');
        var zoom  = $c.data('zoom');
        if (coord && zoom != null && storyDataCache) {
          refreshLayer(storyDataCache, map, coord, zoom);
        }
      }
    });
}

// Move map (safe)
function refreshLayer(data, map, coord, zoom) {
  var narrVisible = window.getComputedStyle(document.getElementById("narration")).display === "block";
  if (!narrVisible) return;

  if (map.stop) map.stop(); // cancel in-flight animation

  // Optional overlay (same as your code path)
  storydataLayer = L.geoJson(data, { pane: 'georeference_pane' });
  // storydataLayer.addTo(map);

  map.flyTo([coord[1], coord[0]], zoom, { animate: true, duration: 1.6 });
  map.invalidateSize();
}

// Close + cleanup
function closestoryfunction() {
  urllink = [];
  storydataaray = [];

  $('#contents').empty();
  document.getElementById("narration").style.display = "none";
  document.getElementById("title").style.display = "none";

  if (map.hasLayer(storygeojson)) {
    storygeojson.clearLayers();
    map.removeLayer(storygeojson);
    storydataLayer = null;
  }
  if (typeof scenariostorygeojson !== 'undefined' && map.hasLayer(scenariostorygeojson)) {
    scenariostorygeojson.clearLayers();
    map.removeLayer(scenariostorygeojson);
  }
}








// ---- GeoJSON layer ----
var storygeojson = L.geoJson(null, {
  pane: 'drawnPane',
  onEachFeature: function (feature, layer) {
    (function (layer, properties) {
      // Numbered marker
      var numericMarker = L.ExtraMarkers.icon({
        icon: 'fa-number',
        number: properties['id'],
        markerColor: 'blue'
      });
      layer.setIcon(numericMarker);

      // Register with OverlappingMarkerSpiderfier
      if (typeof oms !== 'undefined' && oms && typeof oms.addMarker === 'function') {
         oms.addMarker(layer);
      }

      // ---- Build slide DOM ----
      var slideLabel = 'Slide ' + properties['id'];
      var slideIdEl = $('<p></p>', { text: slideLabel, class: 'chapter-id' });

      var chapter = $('<p></p>', { text: properties['chapter'], class: 'chapter-header' });
      var image = $('<img>', { src: properties['image'] });
      var source = $('<a>', {
        text: properties['source-credit'],
        href: properties['source-link'],
        target: '_blank',
        class: 'source'
      });
      var description = $('<p></p>', { text: properties['description'], class: 'description' });
      var year = $('<p></p>', { text: properties['year'], class: 'year' });
      var additionalnotes = $('<p></p>', { text: properties['additionalnotes'], class: 'description' });

      var container = $('<div></div>', { id: 'container' + properties['id'], class: 'image-container' });
      var imgHolder = $('<div></div>', { class: 'img-holder', href: properties['image'] });

      imgHolder.venobox({
        framewidth: '90%',
        frameheight: '90%',
        border: '10px',
        closeBackground: '#2572d2',
        bgcolor: '#b9e3fb',
        titleattr: 'data-title',
        overlayClose: true,
        numeratio: true,
        infinigall: true
      });

      imgHolder.append(image);
      container
        .append(slideIdEl)
        .append(chapter)
        .append(source)
        .append(year)
        .append(description)
        .append(additionalnotes)
        .append(imgHolder);

      // Store coord/zoom on the container for later
      container
        .attr('data-id', properties['id'])
        .data('coord', feature.geometry && feature.geometry['coordinates'])
        .data('zoom', properties['zoom']);

      $('#contents').append(container);

      // ---- Build click-only tooltip HTML (temporary) ----
      var ttHtml =
        '<div class="story-tt">' +
        (properties.chapter ? '<div class="tt-title">' + esc(properties.chapter) + '</div>' : '') +
        (properties.year ? '<div class="tt-year">' + esc(properties.year) + '</div>' : '') +
        (properties.description ? '<div class="tt-desc">' + esc(properties.description) + '</div>' : '') +
        (properties.additionalnotes ? '<div class="tt-notes">' + esc(properties.additionalnotes) + '</div>' : '') +
        (properties['source-credit']
          ? (properties['source-link']
            ? '<div class="tt-source"><a href="' + esc(properties['source-link']) + '" target="_blank" rel="noopener">' + esc(properties['source-credit']) + '</a></div>'
            : '<div class="tt-source">' + esc(properties['source-credit']) + '</div>')
          : '') +
        '</div>';

      // ---- CLICK: show temp tooltip -> scroll to slide -> then move map ----
      layer.on('click', function (e) {
        // temporary tooltip (map-level)
        try {
          if (window._storyClickTT) { map.removeLayer(window._storyClickTT); window._storyClickTT = null; }
          window._storyClickTT = L.tooltip({
            permanent: false,
            direction: 'top',
            offset: [0, -10],
            interactive: true,
            opacity: 0.95,
            className: 'story-tooltip'
          }).setLatLng(e.latlng).setContent(ttHtml)
		 
//		 .addTo(map)
		  ;

          var close = function () {
            //if (window._storyClickTT) { map.removeLayer(window._storyClickTT); window._storyClickTT = null; }
          };
          map.once('click zoomstart movestart', close);
          setTimeout(close, 3500);
        } catch (err) {
          // no-op if tooltip fails (e.g., map not ready)
        }

        var slideId = properties['id'];
        var coord   = feature.geometry && feature.geometry['coordinates'];
        var zoom    = properties['zoom'];
        var targetTop = getSlideTop(slideId);

        // >>> NEW: if we're already on this slide (active & positioned), DON'T scroll/fly — just show properties
        var sTop = $('div#contents').scrollTop();
        if (typeof currentBox !== 'undefined' && currentBox === slideId && Math.abs(sTop - targetTop) < 3) {
          setActiveBox(slideId);              // keep it highlighted
          if (typeof info === 'function') {   // show your properties panel
            info(e);
          }
          return; // stop here (no scroll, no fly)
        }
        // <<< END NEW

        isProgrammaticScroll = true;
        setActiveBox(slideId); // mark active immediately

        $('div#contents').stop(true).animate({ scrollTop: targetTop }, 500, function () {
          // Re-assert focus once we land, then move the map
          setActiveBox(slideId);

          if (coord && zoom != null && storyDataCache) {
            refreshLayer(storyDataCache, map, coord, zoom);
          }

          setTimeout(function () { isProgrammaticScroll = false; }, 50);
          map.invalidateSize();
        });

        if (typeof info === 'function') { info(e); }
      });

      // No per-slide scroll listeners here.

    })(layer, feature.properties);
  }
});







// ---- Init ----
function initstoryMap() {
  $('#narration').empty();

  var storycontents = $('<div></div>', { id: 'contents' });
  $('#narration').append(storycontents);

  document.getElementById("narration").style.display = "block";
  document.getElementById("title").style.display = "block";

  attachBasicScrollWatch(); // lightweight watcher

  // Load the story data once
  $.getJSON(urllink, function(data) {
    storyDataCache = data;

    storygeojson.clearLayers();
    storygeojson.addData(data);
    storygeojson.addTo(map);

    // Ensure an initial active slide based on current viewport
    var initial = findActiveSlideByViewport() || 1;
    setActiveBox(initial);

    // Attach single scroll->map sync (no spam, no per-slide listeners)
    attachSlideSyncOnScroll();

    // "Top" link
    $('#contents').append("<br><div class='space-at-the-bottom'><a href='#space-at-the-top'><i class='fa fa-chevron-up'></i></br><small>Top</small></a><br></div>");
  })
  .fail(function(jqXHR, textStatus) {
    closestoryfunction();
    cmpDebugLog("error " + textStatus);
    swal("The data does not exist");
  });
}

// ---- Minimize panel ----
function minimixestory() {
  $("div#narration").toggle();
}

