/////////////car isochrones//////////////////

function getAccess(e) {
    getIsochronescar([e.latlng.lng, e.latlng.lat]);
}

function getIsochronescar(point) {
    $.ajax({
        type: "GET",
        //rest Type
        dataType: "json",
        url: "https://api.openrouteservice.org/isochrones?locations=" +
            String(point[0]) +
            "," +
            String(point[1]) +
            "&profile=driving-car&range_type=time&interval=300&range=1800&units=&location_type=start&intersections=false&api_key=58d904a497c67e00015b45fc90fa91f0d345426145bb09e67e859771&options={maximum_speed:60}&units=km",
        async: false,
        contentType: "application/json; charset=utf-8",
        success: function success(data) {
            map.eachLayer(function(layer) {
                if (layer.id === "access") {
                    // it's the access layer
                    map.removeLayer(layer);
                }
            });
            var difference = [];

            for (i = 0; i < data.features.length - 1; i++) {
                cmpDebugLog(i);
                difference.push(
                    turf.difference(data.features[i + 1], data.features[i])
                );
            }

            difference.push(data.features[0]);
            data.features = difference;
            access = new L.geoJson(data, {
                onEachFeature: function onEachFeature(feature, layer) {
                    layer.bindPopup(
                        "Isochrone = " +
                        "<b>" +
                        feature.properties.value / 60 +
                        "&ensp;" +
                        "<span>minutes</span></b>" +
                        "<br>(80km max-speed <br>+optimal route conditions)"
                    ); //.addTo(drawnItems)
                },
                style: function style(feature) {
                    ratio = feature.properties.value / 1800;
                    return {
                        color: "rgb(" +
                            String(Math.round(255 * ratio)) +
                            "," +
                            String(Math.round(255 * (1 - ratio))) +
                            ", 230)",
                        opacity: 1
                    };
                }
            }).addTo(map);
            access.id = "access";
        }
    });
} /////////////car isochrones////////////////////
