// --- Bing for Leaflet (quadkey tile layer) ---
const bingApiKey = 'AovHSHXvLU9NLfTrFLZqqEeUkuT0pPMmKCRBQXH7kheMexEUa-nQHVbHwmmMyIAu';

// x/y/z -> quadkey
function tileXYToQuadKey(x, y, z) {
  let q = '';
  for (let i = z; i > 0; i--) {
    let digit = 0;
    const mask = 1 << (i - 1);
    if ((x & mask) !== 0) digit += 1;
    if ((y & mask) !== 0) digit += 2;
    q += digit;
  }
  return q;
}

// imagery: 'Aerial' | 'AerialWithLabels' | 'Road'
function bingPrefix(imagery) {
  if (imagery === 'AerialWithLabels') return 'h'; // hybrid
  if (imagery === 'Road') return 'r';
  return 'a'; // Aerial
}

const BingLayer = L.TileLayer.extend({
  options: {
    minZoom: 1,
    maxZoom: 19,
    subdomains: ['0','1','2','3','4','5','6','7'],
    imagery: 'AerialWithLabels', // change to 'Aerial' or 'Road' if you like
    attribution: '© Microsoft Bing'
  },
  getTileUrl: function (coords) {
    const z = this._getZoomForUrl();
    const q = tileXYToQuadKey(coords.x, coords.y, z);
    const s = this.options.subdomains[(coords.x + coords.y) % this.options.subdomains.length];
    const p = bingPrefix(this.options.imagery);
    // matches your pattern and appends your key
    return `https://ecn.t${s}.tiles.virtualearth.net/tiles/${p}${q}.jpeg?g=1&key=${bingApiKey}`;
  }
});

// create + add (initially hidden like your example)
