// Function to create a Venobox content for each marker
function createVenoboxContent(properties) {
    let content = `<strong>${properties['Τίτλος']}</strong><br><br>`;

    // Add images to the content if they exist
    ['Εικόνα_1', 'Εικόνα_2', 'Εικόνα_3', 'Εικόνα_4'].forEach((key, index) => {
        if (properties[key] && properties[key].trim() !== "") {
            content += `
                <a class="venoboxexifasd" data-gall="gallery" href="${properties[key]}" title="${properties[`Περιγραφή${index + 1}`]}">
                    <img src="${properties[key]}" alt="Image ${index + 1}" style="width: 100px; height: auto; margin: 5px;">
                </a>
            `;
        }
    });

    // Add additional information to the content
    content += `<br><strong>Location:</strong> ${properties['Τοποθεσία']}<br>`;
    content += `<strong>Theme:</strong> ${properties['Θέμα']}<br>`;
    content += `<strong>Description:</strong> ${properties['Περιγραφή3']}<br>`;

    return content;
}

// Bind Venobox popup to each marker
keryneiafeatureLayeraerialphotos.on('click', function (e) {
    var properties = e.layer.feature.properties;

    // Console log the full properties object
    cmpDebugLog('Feature Properties:', properties);

    var content = createVenoboxContent(properties);
    L.popup()
        .setLatLng(e.latlng)
        .setContent(content)
        .openOn(map);

    setTimeout(function() {
        $('.venoboxexifasd').venobox({
            framewidth: '90%',
            frameheight: '90%',
            border: '10px',
            closeBackground: '#2572d2',
            bgcolor: '#b9e3fb',
            titleattr: 'data-title',
            overlayClose: true,
            numeratio: true,
            infinigall: true,
        });
    }, 0);
});


