function updateinfo(feature, layer) {

    feature.properties["_id_"] = L.Util.stamp(layer);

    ///nullify undefined values
    for (var prop in feature.properties) {
        if (typeof feature.properties[prop] === 'undefined') {
            feature.properties[prop] = "null";
        }
    }


    mapinfo.innerHTML = "";
    if (layer.feature.geometry.type == 'Point') {
        oms.addMarker(layer);
    }

    //quadtree.add(layer);

    layer.on({
        click: info
        //load: quadtree.add(layer)
    });
} //////////////////////////////////update info function/////////////////////
///////////////////updateinfo normal markers////////////

