// 0) Shim for old plugins that call L.DomEvent.fakeStop(e)
(function shimFakeStop() {
  if (window.L && L.DomEvent && !L.DomEvent.fakeStop) {
    L.DomEvent.fakeStop = function (e) { if (e) e._leaflet_stop = true; return this; };
  }
})();

// 1) Pane + helpers
const limitsPane = map.createPane('pane-limits');
limitsPane.style.zIndex = 395;           // below overlayPane (400), above tilePane (200)
limitsPane.style.pointerEvents = 'auto';

let excavatedareas = null;      // VectorGrid instance (not added by default)
let _excavatedFC = null;        // merged FeatureCollection for picking
let _excFID = 1;

function stableFeatureId(f){ const p=f.properties||{}; return p._id||p.id||p.index||p.Name||(p.__fid||=`fid_${_excFID++}`); }
function esc(s){ return String(s).replace(/[&<>"']/g, m=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[m])); }

// (A) small helper: map a URL to a source tag
function _srcTagFromUrl(u){
  if (!u) return 'unknown';
  if (u.includes('limits_13_11_20252.geojson')) return 'GNSS_LIMITS';
  if (u.includes('excavatedlimits_19_11_unfiltered_interpreted.geojson?updated=23032026'))   return 'interpreted_limits';
  return 'unknown';
}

// (B) style palettes by source
const STYLE_BY_SRC = {
  // POINTS (geom=1)
  point: {
    interpreted_limits:  { radius: 3, stroke:true, color:'#00000', weight:2, fill:true, fillColor:'#FFD700', fillOpacity:0.95 }, // yellow
    GNSS_LIMITS: { radius: 3, stroke:true, color:'#fd0000', weight:2, fill:true, fillColor:'#fd0000', fillOpacity:0.95 }, // aqua
    unknown:    { radius: 3, stroke:true, color:'#00000', weight:2, fill:true, fillColor:'#FF66CC', fillOpacity:0.95 }
  },
  // LINES (geom=2)
  line: {
    interpreted_limits:  { weight:1.5, color:'#FFFFFF', opacity:0.95 },
    GNSS_LIMITS: { weight:1.5, color:'#fd0000', opacity:0.95 },
    unknown:    { weight:1.5, color:'#FF66CC', opacity:0.95 }
  },
  // POLYGONS (geom=3)
  polygon: {
    interpreted_limits:  { weight:2, color:'#FFFFFF', fill:true, fillColor:'#00FFFF', fillOpacity:0.40 },
    GNSS_LIMITS: { weight:2, color:'#fd0000', fill:true, fillColor:'#fd0000', fillOpacity:0.40 },
    unknown:    { weight:2, color:'#FF66CC', fill:true, fillColor:'#FF66CC', fillOpacity:0.45 }
  }
};

// 2) Build the VectorGrid layer (render only; clicks handled on map)
function buildExcavatedAreasVectorGrid(featureCollection) {
  if (excavatedareas && map.hasLayer(excavatedareas)) map.removeLayer(excavatedareas);

  const grid = L.vectorGrid.slicer(featureCollection, {
    pane: 'pane-limits',
    rendererFactory: L.canvas.tile,
    interactive: true,
    minZoom: 0, maxZoom: 22,
    indexMaxZoom: 18, tolerance: 1.5, indexMaxPoints: 10000,
    getFeatureId: stableFeatureId,

    // style by source + geometry
    vectorTileLayerStyles: {
      sliced: (props) => {
        // geojson-vt sets _geom: 1=Point, 2=Line, 3=Polygon
        const src = props.__src || 'unknown';
        if (props._geom === 1) return STYLE_BY_SRC.point[src] || STYLE_BY_SRC.point.unknown;
        if (props._geom === 2) return STYLE_BY_SRC.line[src]  || STYLE_BY_SRC.line.unknown;
        return STYLE_BY_SRC.polygon[src] || STYLE_BY_SRC.polygon.unknown;
      }
    }
  });

  grid.myTag = 'limits';

  // (optional) hover styling
  grid.on('mouseover', (e)=>{ if(map.getZoom()<13) return; const fid=e.layer?.properties?.__fid||e.layer?.properties?.id; if(fid) grid.setFeatureStyle(fid,{weight:2,color:'cyan',fillOpacity:0.2}); });
  grid.on('mouseout',  (e)=>{ const fid=e.layer?.properties?.__fid||e.layer?.properties?.id; if(fid) grid.resetFeatureStyle(fid); });

  excavatedareas = grid;

  // DO NOT add to the map here — stays hidden until toggle
  // grid.addTo(map);

  return grid;
}

// 3) Load both GeoJSONs, tag features by source, merge, init grid (but don't add it)
(function loadExcavatedGeoJSON() {
  const EXC_SOURCES = [
    './data/reports/excavatedlimits_19_11_unfiltered_interpreted.geojson?updated=23032026',
    './data/reports/limits_13_11_20252.geojson'
  ];

  $.when(...EXC_SOURCES.map(u => $.getJSON(u).then(data => ({ url:u, data }))))
    .done(function () {
      const responses = Array.from(arguments); // [{url,data}, ...]
      const fc = { type:'FeatureCollection', features:[] };

      for (const item of responses) {
        if (!item || !item.data) continue;
		cmpDebugLog("item",item)
        const srcTag = _srcTagFromUrl(item.url);
        const d = item.data;

        if (d.type === 'FeatureCollection' && Array.isArray(d.features)) {
          for (const f of d.features) {
            if (!f) continue;
            // assign source tag (don’t clobber original)
            f.properties = f.properties || {};
            if (!f.properties.__src) f.properties.__src = srcTag;
            fc.features.push(f);
          }
        } else if (d.type === 'Feature') {
          d.properties = d.properties || {};
          if (!d.properties.__src) d.properties.__src = srcTag;
          fc.features.push(d);
        }
      }

      if (!fc.features.length) { console.warn('Excavated areas: no features found.'); return; }

      _excavatedFC = fc;             // for map-level picking
      buildExcavatedAreasVectorGrid(fc); // builds but DOES NOT add
    })
    .fail((xhr, status, err)=> console.error('Failed to load excavated GeoJSON:', status||err, xhr));
})();


// 4) Map-level click picking (only active when layer is visible)
function _ll2pt(ll){ return map.latLngToLayerPoint(ll); }
function _dist2(a,b){ const dx=a.x-b.x, dy=a.y-b.y; return dx*dx+dy*dy; }
function _segDist(p,a,b){ const l2=_dist2(a,b); if(!l2) return Math.sqrt(_dist2(p,a));
  let t=((p.x-a.x)*(b.x-a.x)+(p.y-a.y)*(b.y-a.y))/l2; t=Math.max(0,Math.min(1,t));
  const q={x:a.x+t*(b.x-a.x),y:a.y+t*(b.y-a.y)}; return Math.sqrt(_dist2(p,q)); }
function _ptInPolygon(px,ring){ let inside=false; for(let i=0,j=ring.length-1;i<ring.length;j=i++){
  const xi=ring[i].x, yi=ring[i].y, xj=ring[j].x, yj=ring[j].y;
  const hit=((yi>px.y)!==(yj>px.y)) && (px.x < (xj-xi)*(px.y-yi)/(yj-yi+1e-9)+xi);
  if(hit) inside=!inside; } return inside; }
function _geomHit(latlng,geom,tol){
  const p=_ll2pt(latlng);
  switch(geom.type){
    case 'Point':{
      const q=_ll2pt(L.latLng(geom.coordinates[1],geom.coordinates[0]));
      return Math.sqrt(_dist2(p,q))<=tol;
    }
    case 'MultiPoint':
      return geom.coordinates.some(c=>{
        const q=_ll2pt(L.latLng(c[1],c[0]));
        return Math.sqrt(_dist2(p,q))<=tol;
      });
    case 'LineString':{
      const pts=geom.coordinates.map(c=>_ll2pt(L.latLng(c[1],c[0])));
      for(let i=1;i<pts.length;i++) if(_segDist(p,pts[i-1],pts[i])<=tol) return true;
      return false;
    }
    case 'MultiLineString':
      return geom.coordinates.some(line=>{
        const pts=line.map(c=>_ll2pt(L.latLng(c[1],c[0])));
        for(let i=1;i<pts.length;i++) if(_segDist(p,pts[i-1],pts[i])<=tol) return true;
        return false;
      });
    case 'Polygon':{
      const rings=geom.coordinates.map(r=>r.map(c=>_ll2pt(L.latLng(c[1],c[0]))));
      if(!_ptInPolygon(p,rings[0])) return false;
      for(let h=1;h<rings.length;h++) if(_ptInPolygon(p,rings[h])) return false;
      return true;
    }
    case 'MultiPolygon':
      return geom.coordinates.some(poly=>{
        const rings=poly.map(r=>r.map(c=>_ll2pt(L.latLng(c[1],c[0]))));
        if(_ptInPolygon(p,rings[0])){
          for(let h=1;h<rings.length;h++) if(_ptInPolygon(p,rings[h])) return false;
          return true;
        }
        return false;
      });
    default: return false;
  }
}

// Collect *all* limits features under the cursor
function _pickAllLimitsFeatures(latlng, tolPx = 6) {
  if (!_excavatedFC || !_excavatedFC.features) return [];
  const hits = [];
  for (let i = 0; i < _excavatedFC.features.length; i++) {
    const f = _excavatedFC.features[i];
    if (!f || !f.geometry) continue;
    if (_geomHit(latlng, f.geometry, tolPx)) {
      hits.push(f);
    }
  }
  // sort for nicer UX: points > lines > polygons
  const order = { Point: 1, MultiPoint: 1, LineString: 2, MultiLineString: 2, Polygon: 3, MultiPolygon: 3 };
  hits.sort((a, b) => (order[a.geometry.type] || 9) - (order[b.geometry.type] || 9));
  return hits;
}

// Helper to show the info popup for a single feature (same content as before)
function _showLimitsFeatureInfo(f, latlng) {
  const props = f.properties || {};
  const title = props.Name || props.index || 'Feature';

  const rows = Object.keys(props)
    .filter(k => props[k] != null && props[k] !== '')
    .map(k => `<tr><th>${esc(k)}</th><td>${esc(props[k])}</td></tr>`)
    .join('') || `<tr><td colspan="2"><em>No attributes</em></td></tr>`;

  const html = `
    <div class="limits-popup">
      <div style="font-weight:600;margin-bottom:6px">${esc(title)}</div>
      <table class="table table-sm" style="margin:0">${rows}</table>
    </div>`;

  L.popup({ maxWidth: 360, autoPan: true, className: 'limits-popup' })
    .setLatLng(latlng)
    .setContent(html)
    .openOn(map);
}

// Map click: handle single / multiple overlaps
map.on('click', function(e){
  if (!excavatedareas || !map.hasLayer(excavatedareas)) return;

  const candidates = _pickAllLimitsFeatures(e.latlng, 6);
  if (!candidates.length) return;

  // Only one → behave exactly like your old code
  if (candidates.length === 1) {
    _showLimitsFeatureInfo(candidates[0], e.latlng);
    return;
  }

  // Multiple → show a chooser list
const items = candidates.map((f, i) => {
  const props = f.properties || {};
  const src   = props.__src || 'unknown';
  const name  = props.Name  != null ? props.Name  : '';
  const idx   = props.index != null ? props.index : '';
  const gtype = f.geometry && f.geometry.type || '';

  // Build a “title” line combining Name & index if available
  let titleLine = '';
  if (name && idx) {
    titleLine = `${name} (index: ${idx})`;
  } else if (name) {
    titleLine = name;
  } else if (idx) {
    titleLine = `index: ${idx}`;
  } else {
    titleLine = src || `Feature ${i+1}`;
  }

  // Optional: quick mini-summary of a couple more properties
  const extraKeys = Object.keys(props)
    .filter(k => !['Name', 'index', '__src'].includes(k))
    .slice(0, 3); // show up to 3 extra fields

  const extraLine = extraKeys.length
    ? extraKeys.map(k => `${esc(k)}=${esc(props[k])}`).join(', ')
    : '';

  return `
    <li data-i="${i}" style="cursor:pointer;padding:4px 0;border-bottom:1px solid #eee">
      <div><b>${esc(titleLine)}</b></div>
      <div style="font-size:11px;color:#888;">
        ${esc(src)} • ${esc(gtype)}
        ${extraLine ? ' • ' + extraLine : ''}
      </div>
    </li>`;
}).join('');


  const html = `
    <div class="limits-popup">
      <div style="font-weight:600;margin-bottom:6px">
        Choose feature (${candidates.length} under cursor)
      </div>
      <ul id="limits-chooser" style="list-style:none;margin:0;padding:0;max-height:180px;overflow:auto">
        ${items}
      </ul>
    </div>`;

  const pop = L.popup({ maxWidth: 360, autoPan: true, className: 'limits-popup' })
    .setLatLng(e.latlng)
    .setContent(html)
    .openOn(map);

  // attach click handler inside popup
  setTimeout(() => {
    const list = document.getElementById('limits-chooser');
    if (!list) return;
    list.addEventListener('click', (evt) => {
      const li = evt.target.closest('li[data-i]');
      if (!li) return;
      const idx = +li.getAttribute('data-i');
      const f = candidates[idx];
      map.closePopup(pop);
      _showLimitsFeatureInfo(f, e.latlng);
    });
  }, 0);
});







// 5) Toggle
$('.mdl-card--excavatedpolygons').on('change', function () {
  const on = $(this).hasClass('is-checked');
  if (on) {
    if (excavatedareas && !map.hasLayer(excavatedareas)) map.addLayer(excavatedareas);
	
  
     if (!localStorage.getItem(SWAL_HINT_KEY)) {
      showExcavationLimitsHint();
    }
	
  } else {
    map.eachLayer(l => { if (l.myTag === 'limits') map.removeLayer(l); });
  }
  map.invalidateSize();
});














