const SWAL_HINT_KEY = 'skipExcavatedLimitsHintsecond';


function showExcavationLimitsHint() {
  // If user chose "Don't show again" before, just skip
  if (localStorage.getItem(SWAL_HINT_KEY) === '1') return;


    // SweetAlert 1 uses "content" for HTML, so create a DOM node
    const content = document.createElement('div');
    content.style.textAlign = 'left';
    content.style.lineHeight = '1.5';
    content.innerHTML = `
      <div style="display:flex;align-items:center;gap:.6rem;margin:.25rem 0">
        <span style="display:inline-block;width:16px;height:12px;background:#ff3b30;border:1px solid #a51d15"></span>
        <span><b>Red</b>: Limits surveyed with <b>GNSS</b>.</span>
      </div>
      <div style="display:flex;align-items:center;gap:.6rem;margin:.25rem 0">
        <span style="display:inline-block;width:16px;height:12px;background:#7fd0ff;border:1px solid #2b8ac6"></span>
        <span><b>Light blue</b>: Limits interpreted from <b>site sketches</b>.</span>
      </div>
    `;

    swal({
      title: 'Excavation Limits',
      icon: 'info',
      content: content,
      // Array syntax: [cancelText, confirmText]
      buttons: ["Don't show again", "OK"]
    }).then((value) => {
      // value === true  -> user clicked "OK"
      // value === null  -> user clicked "Don't show again"
      if (value === null) {
        localStorage.setItem(SWAL_HINT_KEY, '1');
      }
    });

}
































// 6) Patch marker booster (xproto) to avoid getZoom crash
(function waitAndPatchXproto() {
  var tries=0, maxTries=200;
  var t=setInterval(function(){
    tries++;
    if(window.xproto && xproto.prototype && typeof xproto.prototype._containsPoint==='function'){
      if(!xproto.prototype._containsPoint.__guarded){
        var orig=xproto.prototype._containsPoint;
        xproto.prototype._containsPoint=function(){
          if(!this||!this._map||typeof this._map.getZoom!=='function') return false;
          try{ return orig.apply(this,arguments); }
          catch(e){ if(e && /getZoom/.test(String(e.message||e))) return false; throw e; }
        };
        xproto.prototype._containsPoint.__guarded=true;
      }
      clearInterval(t);
    } else if (tries>=maxTries){
      clearInterval(t);
    }
  },50);
})();












