function styletheimport(feature) {
    if (layer.feature.properties.hasOwnProperty(color)) {
        //if(layer instanceof L.Polygon)
        return {
            opacity: styletheimport(feature.properties.strokeopacity),
            color: styletheimport(feature.properties.fill),
            fillOpacity: styletheimport(feature.properties.fillopacity),
            fillColor: styletheimport(feature.properties.fill)
        };
    } else {
        return {
            weight: 2,
            opacity: 1,
            color: "white",
            dashArray: "3",
            fillOpacity: 0.3,
            fillColor: "#666666"
        };
    }
}

