function excellayer(selectedFile) {

    //notification.clear()
    //notification.info('Info', 'Loading excell file');

    selectedFile = selectedFile.files[0];
    cmpDebugLog(selectedFile)

    if (selectedFile) {
        // cmpDebugLog("hi");
        var excelfileReader = new FileReader();

        excelfileReader.onload = function(event) {

            var data = event.target.result;
            var workbook = XLSX.read(data, {
                type: "binary"
            });
            workbook.SheetNames.forEach(
                function(sheet) {


                    var csvparse = XLSX.utils.sheet_to_csv(workbook.Sheets[sheet]); // cmpDebugLog(csvparse);
                    cmpDebugLog("csvparse", csvparse);
                    var xlsxomnivore = omnivore.csv.parse(csvparse, null, excelloadedLayer);
                    var rowObject = XLSX.utils.sheet_to_row_object_array(
                        workbook.Sheets[sheet]
                    );

                    cmpDebugLog("xlsxomnivore", xlsxomnivore);

                    cmpDebugLog(excelloadedLayer);
                    var excelfilebounds = excelloadedLayer.getBounds();



                    if (!excelfilebounds.isValid()) {
                        swal("Bounds are not valid");

                    } else {

                        map.fitBounds(excelloadedLayer.getBounds());

                    } //


                    var filenameexcelloader = document.getElementById(
                        "fileloadgenericinput"
                    );
                    var filenameexcelinput =  selectedFile.name;
                    // layerControl.addOverlay(
                    //   excelloadedLayer,
                    //   filenameexcelinput + "<hr>"
                    //  );

                    addLayertolist(excelloadedLayer, filenameexcelinput);

                    //overlayLayers[L.Util.stamp(excelloadedLayer)] = excelloadedLayer;

                    document.getElementById("fileloadgenericinput").value = '';

                }
            );
        };

        excelfileReader.readAsBinaryString(selectedFile); //cmpDebugLog(JSON.parse(selected));

        selectedFile.value = null;
    }
} ////////////end of load xlsx//////////////




function excellayerfrompath(fileOrPath, classtype) {
	
	
    let filePromise;
    hideSpinner();

    try {
        //showSpinner();

        // If it's a string, assume it's a URL and fetch it
        filePromise = fetch(fileOrPath)
            .then((response) => {
                //cmpDebugLog("response",response)


                return response.blob();

            });


        filePromise
            .then((fileBlob) => {

                // Use the fileBlob here for processing
                // Example: Reading the blob as text
                const fileReader = new FileReader();

                fileReader.onload = function(event) {


                    const data = event.target.result;
                    // Parse or process the data as needed
                    //cmpDebugLog(data);



                    var workbook = XLSX.read(data, {
                        type: 'binary'
                    });



  
  
                    //cmpDebugLog("workbook "+classtype,workbook)
                    workbook.SheetNames.forEach(

                        function(sheet) {
                           // showSpinner()

                            var csvparse = XLSX.utils.sheet_to_csv(workbook.Sheets[sheet]); // cmpDebugLog(csvparse);
                            //cmpDebugLog("csvparse", csvparse);

                            if (classtype === "siteprofile") {
                                //notification.clear()
                                //notification.info('Info', 'Loading siteprofiles');
                                omnivore.csv.parse(csvparse, null, site_profiles_custom_layer);
                                if (!L.Browser.mobile) {
                                    overlayLayers[L.Util.stamp(site_profiles_custom_layer)] = site_profiles_custom_layer;
                                }
								


                            } else if (classtype === "sites") {
                                //notification.clear()
                                //notification.info('Info', 'Loading excavated sites');
                                omnivore.csv.parse(csvparse, null, sites);
                                if (!L.Browser.mobile) {
                                    overlayLayers[L.Util.stamp(sites)] = sites;
                                }

                            } else if (classtype === "identified") {
                               // notification.clear()
                               // notification.info('Info', 'Loading identified info');
                                omnivore.csv.parse(csvparse, null, identified);
                                if (!L.Browser.mobile) {
                                    overlayLayers[L.Util.stamp(identified)] = identified;
                                }
                            }

                            hideSpinner();

                        });


                    // Stop the spinner after all processing is done
                    hideSpinner();

                };




                fileReader.readAsBinaryString(fileBlob);

            }).catch((error) => {
                console.error("Error during file processing:", error);
                hideSpinner(); // Ensure that the spinner is hidden in case of an error
				
            });


    } catch (err) {
        cmpDebugLog(err)
        hideSpinner()
    }

map.invalidateSize();
}






