/* ---------------------------
   UTIL: sort select options
---------------------------- */
function sortSelect(select, attr, order) {
  if (attr !== "text") return;
  const $sel = $(select);
  const opts = $sel.children("option").get();
  opts.sort((a, b) => {
    const ax = $(a).text().toUpperCase();
    const bx = $(b).text().toUpperCase();
    return order === "desc" ? (bx < ax ? -1 : 1) : (ax < bx ? -1 : 1);
  });
  $sel.empty().append(opts);
  $sel.get(0).selectedIndex = 0;
}

/* ---------------------------
   AJAX → PostGIS (PLAN)
---------------------------- */
function requestParcelsForPlan(planFeature) {
  if (!planFeature || !planFeature.geometry) return;

  if (map.hasLayer(parcelspostgislayer)) parcelspostgislayer.clearLayers();

  if (typeof showSpinner === "function") showSpinner();
  const requestTimeout = setTimeout(() => {
    if (typeof hideSpinner === "function") hideSpinner();
    swal("Timeout", "The request took too long to complete. Please try again.", "warning");
  }, 15000);

  $.post('../php/check-CADASTRAL-parcels.php', {
    plan_geojson: JSON.stringify(planFeature.geometry)  // << send only geometry
  })
  .done(function (response) {
    clearTimeout(requestTimeout);
    if (typeof hideSpinner === "function") hideSpinner();

    const fc = JSON.parse(response);
    if (map.hasLayer(parcelspostgislayer)) parcelspostgislayer.clearLayers();
    parcelspostgislayer.addData(fc).addTo(map);

    const count = (fc.features || []).length;
    cmpDebugLog(`Parcels in plan: ${count}`);
  })
  .fail(function (xhr, status, error) {
    if (typeof hideSpinner === "function") hideSpinner();
    console.error("Error:", error);
    swal("Error", "There was a problem loading the parcel data: " + error, "error");
  });
}

/* ---------------------------
   AJAX → PostGIS (BOUNDS)
---------------------------- */
function sendParcelRequest() {
  if (map.hasLayer(parcelspostgislayer)) parcelspostgislayer.clearLayers();

  const bounds = map.getBounds();

  if (typeof showSpinner === "function") showSpinner();
  const requestTimeout = setTimeout(() => {
    if (typeof hideSpinner === "function") hideSpinner();
    swal("Timeout", "The request took too long to complete. Please try again.", "warning");
  }, 15000);

  $.post('../php/check-parcels.php', {
    bounds: JSON.stringify(bounds)
  })
  .done(function (response) {
    clearTimeout(requestTimeout);
    if (typeof hideSpinner === "function") hideSpinner();

    const fc = JSON.parse(response);
    if (map.hasLayer(parcelspostgislayer)) parcelspostgislayer.clearLayers();
    parcelspostgislayer.addData(fc).addTo(map);
  })
  .fail(function (xhr, status, error) {
    if (typeof hideSpinner === "function") hideSpinner();
    console.error("Error:", error);
    swal("Error", "There was a problem loading the parcel data: " + error, "error");
  });
}





function dropdownlistfunction() {
  if (L.Browser.mobile) {
    cmpDebugLog('function cassini not included in mobile');
    return;
  }

  // 1) District → Municipality
  L.Util.ajax("data/cassini/cassini_dropdown.geojson").then(function(data) {
    $("#district").off('change').on('change', function () {
      $("#MUNICIPALITY").empty().append(
        $("<option></option>").val("Municipality").html("<b>.Municipality</b>")
      );
      $("#SHEETLPAN").empty().append(
        $("<option></option>").val("Cassini Plan").html(".Cassini Plan")
      );

      const matchVal = $("#district option:selected").text();
      const feats = data.features || [];
      for (let i=0; i<feats.length; i++) {
        if (feats[i].properties.CITY === matchVal) {
          $("#MUNICIPALITY").append(
            $("<option></option>")
              .val(feats[i].properties.MUNICIPALITY)
              .html(feats[i].properties.MUNICIPALITY)
          );
        }
      }
      sortSelect("#MUNICIPALITY", "text", "asc");
    });

    $("#CITYVALUE").on('change', function () {
      $("#CITYVALUE").val($(this).val());
    });
  });

  // 2) Municipality → Plan (and fetch parcels intersecting the plan)
  L.Util.ajax("data/cassini/cassini_dropdown2.geojson").then(function(data) {
    const feats = data.features || [];

    $("#MUNICIPALITY").off('change').on('change', function () {
      $("#SHEETLPAN").empty().append(
        $("<option></option>").val("Cassini Plan").html(".Cassini Plan")
      );
      const matchMunicipality = $("#MUNICIPALITY option:selected").text();

      for (let i=0; i<feats.length; i++) {
        if (feats[i].properties.MUNICIPALITY === matchMunicipality) {
          $("#SHEETLPAN").append(
            $("<option></option>")
              .val(feats[i].properties.PLAN)
              .html(feats[i].properties.PLAN)
          );
        }
      }
      sortSelect("#SHEETLPAN", "text", "asc");
    });

    $("#SHEETLPAN").off('change').on('change', function () {
      // clear previous plan + parcels
      searchedparcels.clearLayers();
      parcelspostgislayer.clearLayers();

      const planName = $("#SHEETLPAN option:selected").text();

      // find the plan feature
      let feat = null;
      for (let i=0; i<feats.length; i++) {
        if (feats[i].properties.PLAN === planName) {
          feat = feats[i];
          break;
        }
      }
      if (!feat) return;

      currentPlanFeature = feat;       // remember selection

      // draw the rectangle
      searchedparcels.addData(feat);
      searchedparcels.eachLayer(function (layer) {
        layer.bindPopup(
          "<b>Plan Name:</b><br>" + layer.feature.properties.PLAN +
          "<br><strong><b>Download</b><br>" + layer.feature.properties.index + "</strong>",
          { permanent: true }
        ).openPopup();
        map.fitBounds(layer.getBounds(), { maxZoom: 19 });
      });

      // If parcels switch is on, fetch parcels inside the plan
      if (parcelspostgisswitch) requestParcelsForPlan(currentPlanFeature);
    });
  });
}



function clearSelectedPlan() {
  currentPlanFeature = null;
  searchedparcels.clearLayers();
  parcelspostgislayer.clearLayers();
  // if switch on, revert to bounds mode fetch
  if (parcelspostgisswitch && map.getZoom() >= 15) sendParcelRequest();
}

  



