function getPdfText(file) {
    $.getScript("./js/pdf/pdf.js").done(function() {
        $.getScript("./js/pdf/pdf.worker.js").done(function() {
            var fileReader = new FileReader();


PDFJS.disableWorker = true;





            fileReader.onload = function() {
                var typedarray = new Uint8Array(this.result);

                PDFJS.getDocument(typedarray).then(function(pdf) {
                    getPage(pdf);

                    function getPage(pdf) {
                        pdf.getPage(currentPage).then(function(page) {
                            var originalWidth = page.view[2];
                            var originalHeight = page.view[3];
                            var rotation = page.rotate;

                            cmpDebugLog('Original Width: ', originalWidth);
                            cmpDebugLog('Original Height: ', originalHeight);
                            cmpDebugLog('Rotation: ', rotation);

                            var scale = 1.0;
                            var viewport = null;

                            try {
                                viewport = page.getViewport(scale);
                                cmpDebugLog('Viewport calculated successfully');
                            } catch (error) {
                                console.error('Error calculating viewport: ', error);
                            }

                            if (!viewport || isNaN(viewport.width) || isNaN(viewport.height)) {
                                console.warn('Viewport is invalid, using fallback dimensions.');
                                viewport = {
                                    width: originalWidth * scale,
                                    height: originalHeight * scale
                                };
                            }

                            cmpDebugLog('Viewport Width: ', viewport.width);
                            cmpDebugLog('Viewport Height: ', viewport.height);

                            if (viewport.width === 0 || viewport.height === 0) {
                                console.error('Viewport dimensions are zero.');
                                return;
                            }

                            var canvas = document.createElement("canvas");
                            canvas.height = viewport.height;
                            canvas.width = viewport.width;
                            var ctx = canvas.getContext("2d", { willReadFrequently: true });

                            cmpDebugLog('Canvas Width: ', canvas.width);
                            cmpDebugLog('Canvas Height: ', canvas.height);

                            if (!ctx) {
                                console.error('Failed to get canvas context.');
                                return;
                            }

                            var renderContext = {
                                canvasContext: ctx,
                                viewport: viewport
                            };

                            page.render(renderContext).then(function() {
                                cmpDebugLog('Page rendered successfully');

                                // Check if the canvas is not blank
                                try {
                                    var imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                                    var hasContent = false;
                                    for (var i = 0; i < imageData.data.length; i += 4) {
                                        if (imageData.data[i + 3] !== 0) { // Check alpha channel
                                            hasContent = true;
                                            break;
                                        }
                                    }
                                    if (!hasContent) {
                                        console.error('Canvas is empty after rendering.');
                                    } else {
                                        cmpDebugLog('Canvas has content.');
                                    }
                                } catch (e) {
                                    console.error('Error accessing canvas image data: ', e);
                                }

                                var imageUrl = canvas.toDataURL("image/jpeg");
                                cmpDebugLog('Image URL: ', imageUrl);

                                if (pdflayer) {
                                    map.removeLayer(pdflayer);
                                    map.removeControl(pdfreferenceslider);
                                }

                                if (globalpdfarrays.length === 0) {
                                    swal("this document contains no coordinates");
                                    hideSpinner();
                                } else {
                                    cmpDebugLog("globalpdfarrays", globalpdfarrays);
                                    var imageBounds = [
                                        [globalpdfarrays[0][0], globalpdfarrays[0][1]],
                                        [globalpdfarrays[0][4], globalpdfarrays[0][5]]
                                    ];

                                    cmpDebugLog('Image Bounds: ', imageBounds);

                                    var fileName = document.getElementById("fileloadgenericinput").files[0].name;
                                    var pdflayer = L.imageOverlay(imageUrl, imageBounds, {
                                        pane: 'georeference_pane'
                                    }).addTo(map);

                                    addLayertolist(pdflayer, fileName);
                                    overlayLayers[L.Util.stamp(pdflayer)] = pdflayer;
                                    fileName.length = 0;
                                    document.getElementById("fileloadgenericinput").value = '';

                                    map.fitBounds(imageBounds);
                                    var pdfreferenceslider = L.control.range({
                                        position: "bottomright",
                                        orient: "vertical",
                                        value: 100
                                    });

                                    pdfreferenceslider.id = pdflayer._leaflet_id;
                                    var elementid = pdfreferenceslider.id;

                                    pdfreferenceslider.on("input change", function(e) {
                                        pdflayer.setOpacity(e.value / 100);
                                    });

                                    map.addControl(pdfreferenceslider);

                                    $(".leaflet-range-icon").click(function(e) {
                                        zoomToLayer($(".leaflet-range-icon").attr('id'));
                                        var layeridzoom = pdflayer._leaflet_id;

                                        $('*[id*="layerid' + layeridzoom + '"]').each(function(i, el) {
                                            // Custom logic if needed
                                        });
                                    });

                                    map.on("overlayremove", function(e) {
                                        if (e.layer._leaflet_id === pdfreferenceslider.id) {
                                            map.removeControl(pdfreferenceslider);
                                        }
                                    });

                                    map.on("overlayadd", function(e) {
                                        if (e.layer._leaflet_id === pdfreferenceslider.id) {
                                            map.addControl(pdfreferenceslider);
                                        }
                                    });

                                    hideSpinner();
                                }
                            }, function(error) {
                                console.error('Error rendering page: ', error);
                            });
                        }, function(error) {
                            console.error('Error getting page: ', error);
                        });
                    }
                });
            };

            fileReader.readAsArrayBuffer(file);
        }).fail(function(jqxhr, settings, exception) {
            console.error('Error loading pdf.worker.js: ', exception);
        });
    }).fail(function(jqxhr, settings, exception) {
        console.error('Error loading pdf.js: ', exception);
    });
}





























