function getkmlfile(input) {

    setTimeout(function() {
        hideSpinner();
        showSpinner();

        var _this6 = this;


        var kmlfile = input;
        var kmlreader = new FileReader();
        var gj = {
            type: "FeatureCollection",
            features: []
        };

        kmlreader.onload = function(res) {
            _newArrowCheck(this, _this6); // cmpDebugLog('dgfghfgh',res.target.result); // Print file contents

            var kml = res.target.result;

            var dom = new DOMParser().parseFromString(kml, "application/xml"); // cmpDebugLog('dom',dom);

            //cmpDebugLog("kml dom", dom);

            gj.features.push(toGeoJSON.kml(dom));
            var kmllayer = L.geoJSON(gj, geoJsonOptions);
            kmllayer.addTo(map);

            var kmlbounds = kmllayer.getBounds();
            if (!kmlbounds.isValid()) {
                swal("Bounds are not valid");
            } else {
                map.fitBounds(kmllayer.getBounds());
            }

            //layerControl.addOverlay(kmllayer, input.files[0].name); //cmpDebugLog('gj',gj.features);
            cmpDebugLog('input.name', input.name);

            addLayertolist(kmllayer, input.name);
            overlayLayers[L.Util.stamp(kmllayer)] = kmllayer;

            document.getElementById("fileloadgenericinput").value = '';

        }.bind(this); // reader.onerror = err => cmpDebugLog(err);

        kmlreader.readAsText(kmlfile);

        hideSpinner();

        map.invalidateSize();
    }, 200);

} /////////////////load kml//////////////
