function convert(topo) {
    cmpDebugLog("topojson:", topo)
    try {
        renderJSON(null, topo, true);
    } catch (error) {
        cmpDebugLog(error)
        var keys = Object.keys(topo.objects);
        var geo = topojson.feature(topo, topo.objects[keys[0]]); //cmpDebugLog("geojson", geo)

        renderJSON(null, geo, true);
    }
}

function renderJSON(err, json, pretty) {
    //cmpDebugLog(JSON.stringify(json, null, pretty ? 2 : 0));
    var parsedtopojson = JSON.parse(JSON.stringify(json, null, pretty ? 2 : 0)); //cmpDebugLog('parsedgeojson',parsedtopojson);

    var topojsonlayer = L.geoJSON(parsedtopojson, geoJsonOptions);
    topojsonlayer.addTo(map);
    map.fitBounds(topojsonlayer.getBounds());
    //layerControl.addOverlay(topojsonlayer, topojsonnamearray);
    addLayertolist(topojsonlayer, topojsonnamearray);
    overlayLayers[L.Util.stamp(topojsonlayer)] = topojsonlayer;

    document.getElementById("fileloadgenericinput").value = '';
    // alert(topojsonnamearray);
} /////////////////load topojson//////////////
