function handleshpFile(file) {
    setTimeout(function() {
        var _this9 = this;
        hideSpinner();
        showSpinner();
        var shpfile = file.files[0];
        var shpreader = new FileReader();

        shpreader.onload = function(res) {
            _newArrowCheck(this, _this9);

            var shpresult = res.target.result; //cmpDebugLog(shpresult);

            var name = shpfile.name;
            loadArrayBuffer(shpresult, name);
        }.bind(this);

        shpreader.readAsArrayBuffer(shpfile);
        hideSpinner();
        map.invalidateSize();
    }, 200);
}

function loadArrayBuffer(buffer, name) {
    shp(buffer).then(function(geojson) {
        var shapefilelayer = L.geoJSON(geojson, geoJsonOptions);
        var layers = shapefilelayer._layers;
        Object.keys(layers).forEach(function(key) {
            var shapefilelayer = layers[key];
        });


        shapefilelayer.addTo(map);
        addLayertolist(shapefilelayer, name);
        overlayLayers[L.Util.stamp(shapefilelayer)] = shapefilelayer;
        //layerControl.addOverlay(shapefilelayer, name);
        map.fitBounds(shapefilelayer.getBounds());
        document.getElementById("fileloadgenericinput").value = '';
    });
} ////////shapefile//////////////////













