// Helper function to project point coordinates
function projectPoint(coord, tileX, tileY, z, extent) {
    var tileSize = 256;
    var worldX = (tileX * tileSize + (coord.x / extent) * tileSize);
    var worldY = (tileY * tileSize + (coord.y / extent) * tileSize);

    // Validate projected coordinates
    if (!isFinite(worldX) || !isFinite(worldY)) {
        throw new Error('Invalid projected coordinates');
    }

    var latLng = L.CRS.EPSG3857.pointToLatLng(L.point(worldX, worldY), z);
    if (!isFinite(latLng.lat) || !isFinite(latLng.lng)) {
        throw new Error('Invalid LatLng object');
    }
    return [latLng.lng, latLng.lat];
}

// Function to check if the geometry type is valid GeoJSON
function isValidGeoJsonGeometry(type) {
    var validTypes = ['Point', 'LineString', 'Polygon', 'MultiPoint', 'MultiLineString', 'MultiPolygon'];
    return validTypes.includes(type);
}

// Function to project vector tile coordinates to LatLng
function projectFeatureToLatLng(geojsonFeature, z, x, y, extent) {
    var tileSize = 256;

    // Helper function to project points
    function projectPoint(coord) {
        var worldX = (x * tileSize + (coord[0] / extent) * tileSize);
        var worldY = (y * tileSize + (coord[1] / extent) * tileSize);

        if (!isFinite(worldX) || !isFinite(worldY)) {
            throw new Error('Invalid projected coordinates');
        }

        var latLng = L.CRS.EPSG3857.pointToLatLng(L.point(worldX, worldY), z);
        if (!isFinite(latLng.lat) || !isFinite(latLng.lng)) {
            throw new Error('Invalid LatLng object');
        }
        return [latLng.lng, latLng.lat];
    }

    // Apply the projection to the coordinates
    if (geojsonFeature.geometry.type === 'Point') {
        geojsonFeature.geometry.coordinates = projectPoint(geojsonFeature.geometry.coordinates);
    } else if (geojsonFeature.geometry.type === 'LineString' || geojsonFeature.geometry.type === 'MultiPoint') {
        geojsonFeature.geometry.coordinates = geojsonFeature.geometry.coordinates.map(projectPoint);
    } else if (geojsonFeature.geometry.type === 'Polygon' || geojsonFeature.geometry.type === 'MultiLineString') {
        geojsonFeature.geometry.coordinates = geojsonFeature.geometry.coordinates.map(ring => ring.map(projectPoint));
    } else if (geojsonFeature.geometry.type === 'MultiPolygon') {
        geojsonFeature.geometry.coordinates = geojsonFeature.geometry.coordinates.map(polygon =>
            polygon.map(ring => ring.map(projectPoint))
        );
    }

    return geojsonFeature;
}

