// Function to identify the coordinate system based on the corner coordinates
function identifyCoordinateSystem(corners) {
    var firstCorner = corners[0];

    // Check if the first corner is within the range of lat/lon (EPSG:4326)
    var isLatLon = (firstCorner[0] >= -180 && firstCorner[0] <= 180) &&
                   (firstCorner[1] >= -90 && firstCorner[1] <= 90);

    if (isLatLon) {
        cmpDebugLog("The coordinates are in EPSG:4326 (latitude/longitude).");
        return "EPSG:4326";
    } else {
        cmpDebugLog("The coordinates are in a projected coordinate system (e.g., EPSG:3857).");
        return "EPSG:3857";
    }
}



// Function to reproject coordinates from EPSG:4326 to EPSG:3857
function reprojectTo3857(bbox) {
    var sourceProjection = 'EPSG:4326';  // Latitude/Longitude
    var targetProjection = 'EPSG:3857';  // Web Mercator

    // Reproject the corners
    return bbox.map(function(corner) {
        return proj4(sourceProjection, targetProjection, corner);
    });
}



