async function loadHistogram(layer) {
    // Assume `georastergeoblaze` and `bboxs` are already defined and passed from your raster data
    try {
		document.getElementById("histogramContainer").style.display="block";
		document.getElementById("histogramChart").style.display="block";
        // Retrieve the histogram data using geoblaze.histogram
        var histograms = await geoblaze.histogram(georastergeoblaze, bboxs, { scaleType: "nominal" });
        cmpDebugLog("histograms",histograms)
        // Extracting histogram keys (bins) and values (counts) dynamically from the result
        const labels = Object.keys(histograms[0]); // Assuming histogram result is in the first index
        const data = Object.values(histograms[0]); // The frequency counts

        // Create a Chart.js bar chart with the dynamically retrieved data
        const ctx = document.getElementById('histogramChart').getContext('2d');
        const histogramChart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [{
                    label: 'Histogram',
                    data: data,
                    backgroundColor: 'rgba(75, 192, 192, 0.2)',
                    borderColor: 'rgba(75, 192, 192, 1)',
                    borderWidth: 1
                }]
            },
            options: {
                scales: {
                    x: {
                        title: {
                            display: true,
                            text: 'Bins'
                        }
                    },
                    y: {
                        title: {
                            display: true,
                            text: 'Frequency'
                        },
                        beginAtZero: true
                    }
                }
            }
        });

    } catch (error) {
		   hideSpinner();
        console.error("Error generating histogram:", error);
			document.getElementById("histogramContainer").style.display="none";
		document.getElementById("histogramChart").style.display="none";
    }
}

