function addLayertolist(layer, name, identifier) {


    layerControl.addOverlay(layer, `
    <span class="layer-name" id="${L.Util.stamp(layer)}">
      ${name}
    </span>
    <span class="layer-buttons">
      <span style="display: ${layer instanceof L.GeoJSON ? 'none' : 'unset'}">
        <a class="layer-btn" href="#" title="Change opacity" onclick="changeOpacity(${L.Util.stamp(layer)}); return false;"><i class="fas fa-adjust"></i></a>
      </span>
	  
	
		  

    <span style="display: ${cmpIsGeoRasterLayer(layer) ? 'none' : 'unset' }">
        <a class="layer-btn" href="#" title="Feature table" onclick="showTable(${L.Util.stamp(layer)}, '${name}'); return false;"><i class="fas fa-table"></i></a>
      </span>


      <a class="layer-btn" href="#" title="Zoom to layer" id= "layerid${L.Util.stamp(layer)}" onclick="zoomToLayer(${L.Util.stamp(layer)}); return false;"><i class="fas fa-expand-arrows-alt"></i></a>
      <a class="layer-btn" href="#" title="Remove layer" onclick="removeLayer(${L.Util.stamp(layer)}, '${name}'); return false;"><i class="fas fa-trash" style="color: red"></i></a>
    </span>
    <div style="clear: both;"></div>
  `);


    // cmpDebugLog(layer);


    if (layer instanceof L.GeoJSON) {
        layersarray.push('pinlayer: ' + name + '[' + L.Util.stamp(layer) + ']');

        layer.addTo(cmpdatasearch);
    } else {

    }


    map.invalidateSize();
}


function zoomToLayer(id) {

    var layer = overlayLayers[id];
    if (!map.hasLayer(layer)) {
        map.addLayer(overlayLayers[id]);
    }
    if (layer.options.bounds) {
        map.fitBounds(layer.options.bounds);
    } else {
        map.fitBounds(layer.getBounds(), {
            padding: [20, 20]
        });
    }
    map.invalidateSize();
}

function removeLayer(id, name) {

if(selectedlayer){
selectedlayer.clearLayers();
}
    var cfm = confirm(`Remove ${name}?`);
    if (cfm == true) {
        var layer = overlayLayers[id];
        if (!map.hasLayer(layer)) {
            map.addLayer(overlayLayers[id]);
        }

        if (cmpIsMbtilesLayer(layer)) {
            layer._db.close();

        }


        //.replace( /(^.*\[|\].*$)/g, '' );
        // cmpDebugLog(id);
        var index = layersarray.indexOf('pinlayer: ' + name + '[' + id + ']');

        if (index > -1) {
            layersarray.splice(index, 1);
            // cmpDebugLog(layersarray);
        }
        map.invalidateSize();
    }
    //cmpDebugLog(layersarray);

    map.removeLayer(layer);
    layerControl.removeLayer(layer);




}

function changeOpacity(id) {
    var layer = overlayLayers[id];
    if (!map.hasLayer(layer)) {
        map.addLayer(overlayLayers[id]);
    }
    var value = layer.options.opacity;
    if (value > 0.2) {
        layer.setOpacity((value - 0.2).toFixed(1));
    } else {
        layer.setOpacity(1);
    }
}




