function pinlayer(layer, name, identifier) {

    layername = name;
    cmpDebugLog("layername before", layername);
    layername = new L.geoJson(layer, {
        style: {
            color: "black",
            fillOpacity: 0,
            weight: 4
        },
        onEachFeature: function(feature, layer) {
            feature.properties["_id_"] = L.Util.stamp(layer);
            if (feature.geometry.type === 'Polygon') {

                layer.on('mouseover', function(e) {
                    layer.bindTooltip("" + feature.properties.index + "", {
                        direction: 'auto',
                        sticky: true,
                    }).openTooltip();
                })
            } else if (feature.geometry.type === "Point") {

                layer.on('mouseover', function(e) {
                    layer.bindTooltip("" + feature.properties.index + "", {
                        direction: 'auto',
                        sticky: true,
                    }).openTooltip();
                })
            } else {
                var lineinfo = "";
                var hiddenProps = ["styleUrl"];
                for (var k in feature.properties) {
                    if (layer.feature.properties.hasOwnProperty(k) && hiddenProps.indexOf(k) == -1) {
                        var v = String(feature.properties[k]);
                        lineinfo +=
                            "<b>" +
                            k +
                            "</b><br>" +
                            layer.feature.properties[k] +
                            "<br>" +
                            '<hr style="margin:5px 0px;  border-style: dotted; border-color: forestgreen;">';

                    }
                }

                layer.on('click', function(e) {
                    layer.bindPopup("" + lineinfo + "", {
                        direction: 'auto',
                        sticky: false,
                    }).openPopup();
                    // cmpDebugLog(layer);
                })

            }

        },
        pointToLayer: function(feature, latlng) {
            return L.circleMarker(latlng, {
                //renderer: myRenderer,
                radius: 6,
                fillColor: "yellow",
                color: "blue",
                weight: 1,
                opacity: 0,
                fillOpacity: 0,
                boostType: boostType,
                boostScale: boostScale,
                boostExp: boostExp


            })
        }


    }).addTo(map);

    //cmpDebugLog("layername after", layername);
    overlayLayers[L.Util.stamp(layername)] = layername;
    //name = name + layername._leaflet_id;
    addLayertolist(layername, name, identifier);
    map.addLayer(layername);
    //layersarray.push(name);
    randomlayer.addLayer(layername);
    closeidentify();
}









