function cmpPrepareDashboardTableContainer() {
    dashboardtableLayer = null;
    $("#map").css("position", "relative");
    $("#table-container").hide();
    $("#table-container").show();
    $("#map").css("height", "45%");
    $("#table-container").css("height", "65%");
}

function cmpOpenDashboardTable(layer, title) {
    cmpPrepareDashboardTableContainer();
    showdashboardTable(L.stamp(layer), title);
}

function cmpOpenDeferredDashboardTable(layer, title, deferredLayerKey) {
    cmpEnsureDeferredGeoJsonLayerLoaded(deferredLayerKey, {
        useSpinner: true
    }).then(function() {
        overlayLayers[L.Util.stamp(layer)] = layer;
        cmpOpenDashboardTable(layer, title);
    }).catch(function(error) {
        console.error("Deferred dashboard layer load failed:", deferredLayerKey, error);
        swal("The requested layer is not available right now.");
    });
}




