var excavationongoing_custom_layer = L.geoJSON(null, {
    onEachFeature: function onEachFeature(feature, layer) {
        var properties = feature.properties;
        var content = [];

        for (var key in properties) {
            content.push(key + ": " + properties[key]);
        }

        layer.on({
            click: function() {
                L.popup().setLatLng(layer.getLatLng()).setContent(content.join("<br>")).openOn(map);
            }
        });
    },
    pointToLayer: function pointToLayer(feature, latlng) {
       // cmpDebugLog("Applying pulsing icon for feature:", feature);
        var p = feature.properties;
        p.index = p.index + " Ongoing excavation: " + feature.properties["Excavation Code"];
        return L.marker(latlng, {
            icon: excavationongoing_pulsingIcon
        });
    }
});





