function getcolorbystatus(feature) {

    if (feature.properties["Case Status (Excavation)"] === 'On-going') {
        return "yellow";
    } else if (feature.properties["Case Status (Excavation)"] === 'Closed') {

        return "orange";

    } else {

        return "yellow";

    }

    return;

}




