function convert(value) {
    var firstlat;
    var firstlon;
    try {
        var parseagain = parseDMS(secondconversion(value));
        //cmpDebugLog("incoming value",secondconversion(value))

        if (parseagain[Object.keys(parseagain)[0]] == undefined) {

            firstlat = 0.0;
        } else {
            firstlat = parseagain[Object.keys(parseagain)[0]];
        }

        if (parseagain[Object.keys(parseagain)[1]] == undefined) {
            firstlon = 0.0;
        } else {
            firstlon = parseagain[Object.keys(parseagain)[1]];

        }
    } catch (error) {
        //cmpDebugLog("catch error",error);
        firstlat = 0.0;
        firstlon = 0.0;

    }
    //console.log ("final value to geojson",[firstlon,firstlat]);
    return [firstlon, firstlat];
}

function secondconversion(value) {
    var firstlat;
    var firstlon;
    var returnvalue = [];
    coordsIn = value.split(/[\r\n]/) // split on carriage return
        .map(coord => coord.trim()) // trim strings
        .filter(Boolean) // remove blanks
    // Clear out the out array
    coordOut = [];
    arrayparsedms = [];
    // loop the input array
    //cmpDebugLog("coordsIncoordsIn",coordsIn);
    try {

        coordsIn.forEach(coord => {
            // split on lat lng
            var [lat, lng] = coord.split(/(?:\s*,\s*|\s{2,}|\t+)/);
            // discern the type of the input
            var type = discernType(lat, lng);

            // Setup a new conversion for this input
            var cc = new CoordinateConversion();
            switch (type) {

                case 'MGRS':
                    cc.setMGRS(coord);
                    break;
                case 'DD':
                    cc.setDD({
                        lat: lat,
                        lng: lng
                    });
                    break;

                default:
                    break;
            }
            if (type === 'INVALID') {
				
		     returnvalue = [];
                returnvalue.push(coordsIn);
                //returnvalue.push(type);
            } else

            {
                //cmpDebugLog("converted",[cc.DD.lat,cc.DD.lng]);
                //firstlon = cc.DD.lng;
                //firstlat = cc.DD.lat;
                returnvalue.push([cc.DD.lat, cc.DD.lng]);
                // cmpDebugLog("success", coordsIn,cc.DD.lat,cc.DD.lng)
            }

        });

    } catch (error) {
        //cmpDebugLog("first",error);
        returnvalue = [];
        returnvalue.push(coordsIn);
        if (hideSpinner) {
            hideSpinner();
        }

    }
    return returnvalue[0].toString();
}



