excesearch = new L.Control.Search({
    textPlaceholder: "Search Data/Coords/Address",
    layer: cmpdatasearch,
    initial: false,
    propertyName: "index",
    minLength: 3,
    circleLocation: true,
    collapsed: false,
    zoom: "18",
	Marker: true,
    textErr: "Location not found" //autoCollapse: true,

});



// TIP (optional, set where you create the control):
// Make sure the search control doesn't add its own center marker:
// const excesearch = new L.Control.Search({ ..., zoom: 18, marker: false });


// Optional (where you create the control): stop the search control from adding its own marker
// const excesearch = new L.Control.Search({ ..., zoom: 18, marker: false });

excesearch.on("search:locationfound", function (e) {
  var hiddenProps = [
    "styleUrl","styleHash","FILLOPACITY","fillopacity","styleMapHash","stroke","strokeopacity","stroke-opacity",
    "stroke-width","opacity","fill","fill-opacity","icon","scale","coordTimes","_id_","areaValue","AREAVALUE_UOM",
    "AREAVALUE_VOID","BEGINLIFESPANVERSION","BEGINLIFESPANVERSION_VOID","ENDLIFESPANVERSION","ENDLIFESPANVERSION_VOID","ID_LOCALID",
    "ID_VERSIONID","ID_VERSIONID_VOID","VALIDFROM","VALIDFROM_VOID","VALIDTO","VALIDTO_VOID","BASPROPUNIT_VOID","ZONING","ZONING_VOID",
    "ADMUNIT_VOID","SHAPE.STAREA()","SHAPE.STLENGTH()","IFCID","OBJECTID","ENDLIFESPANVERSION_VOID","ENDLIFESPANVERSION","BEGINLIFESPANVERSION_VOID",
    "BEGINLIFESPANVERSION","SHAPE.STArea()","SHAPE.STLength()","id_versionId_void","id_versionId","endLifespanVersion_void",
    "endLifespanVersion","beginLifespanVersion_void","beginLifespanVersion","basPropUnit_void","areaValue_uom","zoning_void","zoning",
    "validTo_void","validTo","validFrom_void","validFrom","areaValue_void","admUnit_void","id_namespace","id_localId","admUnit",
    "gis_GIS__2","gis_GIS__1","gis_GIS_dc","img","base64","tblSpGuid","strokewidth","shapecolor"
  ];

  excesearch.collapse();

  var foundLayer = e.layer;
  var feature    = foundLayer.toGeoJSON ? foundLayer.toGeoJSON() : foundLayer.feature;
  var props      = feature && feature.properties ? feature.properties : {};
  var geomType   = feature && feature.geometry ? feature.geometry.type : null;

  // clear previous highlight + marker
  if (typeof multicoordinatesmarker !== "undefined" && multicoordinatesmarker) {
    map.removeLayer(multicoordinatesmarker); multicoordinatesmarker = null;
  }
  if (typeof multicoordinatesshape !== "undefined" && multicoordinatesshape) {
    map.removeLayer(multicoordinatesshape);  multicoordinatesshape  = null;
  }

  // ---------- centroid helpers (no Turf required) ----------
  function ringCentroidAndArea(ring) {
    // ring: [[lng,lat], ... , [lng,lat]] (closed or not)
    var area = 0, cx = 0, cy = 0;
    var len = ring.length;
    if (len < 3) return { c: null, a: 0 };

    for (var i = 0; i < len - 1; i++) {
      var x1 = ring[i][0], y1 = ring[i][1];
      var x2 = ring[i+1][0], y2 = ring[i+1][1];
      var a  = x1*y2 - x2*y1;
      area += a;
      cx   += (x1 + x2) * a;
      cy   += (y1 + y2) * a;
    }
    area *= 0.5;
    if (!area) return { c: null, a: 0 };
    return { c: [cx/(6*area), cy/(6*area)], a: Math.abs(area) };
  }

  function polygonCentroid(coords) {
    // coords: [ [outerRing], [hole1], ... ]
    if (!coords || !coords.length) return null;
    var res = ringCentroidAndArea(coords[0]); // outer ring only
    return res.c;
  }

  function multiPolygonCentroid(coords) {
    // coords: [ [ [outerRing], ... ], [ [outerRing], ... ], ... ]
    if (!coords || !coords.length) return null;
    var A = 0, sx = 0, sy = 0;
    for (var i = 0; i < coords.length; i++) {
      var c = ringCentroidAndArea(coords[i][0]); // outer ring of each polygon
      if (c.c) {
        sx += c.c[0] * c.a;
        sy += c.c[1] * c.a;
        A  += c.a;
      }
    }
    if (!A) return null;
    return [sx/A, sy/A];
  }

  function centerForGeometry(geom) {
    if (!geom) return e.latlng;
    if (geom.type === "Polygon") {
      var c1 = polygonCentroid(geom.coordinates);
      if (c1) return L.latLng(c1[1], c1[0]);
    } else if (geom.type === "MultiPolygon") {
      var c2 = multiPolygonCentroid(geom.coordinates);
      if (c2) return L.latLng(c2[1], c2[0]);
    }
    // fallback: visual center
    if (foundLayer.getBounds) return foundLayer.getBounds().getCenter();
    return e.latlng;
  }
  // ---------------------------------------------------------

  // info HTML
  function buildInfoHTML(p) {
    var lineinfo = "";
    for (var k in p) {
      if (!Object.prototype.hasOwnProperty.call(p, k)) continue;
      if (hiddenProps.indexOf(k) !== -1) continue;
      var valHTML = (typeof formatProperty === "function") ? formatProperty(p[k]) : String(p[k]);
      lineinfo += "<b>" + k.toUpperCase() + "</b><br>" + valHTML +
                  "<br><hr style='margin:5px 0; border-style:dotted; border-color:forestgreen;'>";
    }
    return lineinfo;
  }
  var lineinfo = buildInfoHTML(props);

  // keep your export buffer
  if (typeof individualinfoarray !== "undefined") {
    individualinfoarray = [];
    individualinfoarray.push(feature);
  }

  var popupFooter =
    '<button id="export" style="color:black;" onclick="kmlexportindividualinfo()">Export to kml&nbsp;<i class="fas fa-download" title="KML EXPORT"></i></button>' +
    '<hr style="margin:5px 0; border-style:dotted; border-color:forestgreen;">' +
    '<button id="Navigate"><a href="https://maps.apple.com/?q=' + e.latlng.lat + ',' + e.latlng.lng +
    '" target="_blank" style="text-decoration:none;color:inherit;">Navigate in google maps&nbsp;<i class="fas fa-route"></i></a></button>';

  // ---- render
  if (geomType === "Point" || geomType === "MultiPoint") {
    // POINTS: same as before
    var markerOpts = { color: "red", stroke: true, weight: 0, radius: 5 };
    if (typeof boostScale !== "undefined") {
      markerOpts.boostType  = "circle";
      markerOpts.boostScale = boostScale;
      if (typeof boostExp !== "undefined") markerOpts.boostExp = boostExp;
    }
    multicoordinatesmarker = L.circleMarker(e.latlng, markerOpts)
      .bindPopup(lineinfo + popupFooter)
      .addTo(map)
      .openPopup();

  } else {
    // SHAPES: add highlight + centroid marker with same popup
    function highlightStyle() {
      return { color: "yellow", weight: 4, opacity: 1, fillOpacity: 0, interactive: false };
    }

    if (foundLayer.getBounds) map.fitBounds(foundLayer.getBounds());

    multicoordinatesshape = L.geoJSON(feature, { style: highlightStyle }).addTo(map);
    multicoordinatesshape.eachLayer(function (l) { l.bringToFront(); });

    // centroid marker (Polygon/MultiPolygon or fallback to bounds center)
    var cLL = centerForGeometry(feature.geometry);
    var cOpts = { color: "red", stroke: true, weight: 0, radius: 5 };
    if (typeof boostScale !== "undefined") {
      cOpts.boostType  = "circle";
      cOpts.boostScale = boostScale;
      if (typeof boostExp !== "undefined") cOpts.boostExp = boostExp;
    }
    multicoordinatesmarker = L.circleMarker(cLL, cOpts)
      .bindPopup(lineinfo + popupFooter)
      .addTo(map)
      .openPopup();
  }

  // keep click->info on original found layer (and on centroid marker if you want)
  if (typeof info === "function") {
    if (foundLayer && foundLayer.on) foundLayer.on("click", function (evt) { 
	cmpDebugLog(evt)
	
	//info(evt); 
	
	});
	
	
    if (multicoordinatesmarker)        multicoordinatesmarker.on("click", function (evt) { 
	cmpDebugLog(evt)
	//info(evt); 
	});
  }

  if (map && map.invalidateSize) map.invalidateSize();
});


