 function SelectPoints() {

try{
	
    if (identifyqueryswitch === true) {


        cyprusbound.on("click", function(e) {

            hideSpinner();
            showSpinner();
            setTimeout(function() {


                xy = null;
                lat = null;
                lon = null;
                lat = e.latlng.lat;
                lon = e.latlng.lng;
                cmpDebugLog('cyprusbound clicked ');
                map.flyTo(e.latlng, 15, {
                    animate: true,
                    duration: 0.5
                });

                map.invalidateSize();


                $("#identifeatures").show();

                $("#identifyaccordion").accordion("activate", false);


                //document.getElementById('map').style.cursor = '';
                //document.getElementById('map').style.cursor = 'help';
                //document.getElementById('map').style.cursor = 'url("./images/identify.png"), auto';
                document.getElementById("countfeatures").innerHTML = "";
                $("#toolbar li").remove();
                bridgelayer.clearLayers();
                selPts = []; //cmpDebugLog("You clicked the map at LAT: "+ lat+" and LONG: "+lon );
                //Clear existing marker, circle, and selected points if selecting new points

                if (theidentifyCircle != undefined) {
                    map.removeLayer(theidentifyCircle);
                    map.removeLayer(theidentifymarker);
                    bridgelayer.clearLayers();
                    selPts = [];

                }

                if (theidentifymarker != undefined) {
                    map.removeLayer(theidentifymarker);
                    map.removeLayer(theidentifyCircle);
                    bridgelayer.clearLayers();
                    selPts = [];

                } //Add a marker to show where you clicked.


                theidentifymarker = L.marker([lat, lon]).addTo(map);


                var dist = document.getElementById("miles").value;



                xy = null;
                xy = [lat, lon]; //center point of circle
                var theRadius;
                theRadius = null;
                theRadius = dist * 1000.0; //1609.34 meters in a mile
                // parseInt(dist) * 1000.00 //1609.34 meters in a mile
                //dist is a string so it's convered to an Interger.

                bridgelayer.clearLayers();
                selPts = []; //Reset the array if selecting new points

                identify_pts.eachLayer(function(layer) {
                    layer_lat_long = null;
                    // Lat, long of current point as it loops through.
                    layer_lat_long = layer.getLatLng(); // Distance from our circle marker To current point in meters
                    distance_from_centerPoint = layer_lat_long.distanceTo(xy); // See if meters is within radius, add the to array
                    if (distance_from_centerPoint <= theRadius) {
                        selPts.push(layer.feature);



                    }
                });




                var notifyIcon = L.divIcon({
                    className: "notify-icon",
                    iconSize: [55, 55],
                    html: "<span></span>"
                }); // draw circle to see the selection area


                theidentifyCircle = L.circle(xy, theRadius, {
                        icon: notifyIcon,
                        color: "orange",
                        fillOpacity: 0.1,
                        opacity: 1,
                        interactive: false,
                        bubblingMouseEvents: true
                    })
                    .addTo(map); ////////turf calculate bbox from polygon or circle

 
                bridgelayer.clearLayers();
                bridgelayer.addData(selPts);
                $("#toolbar li").remove();
                document.getElementById("closebuttonidentify").style.display = "block";
                document.getElementById("radius_panel").style.display = "block";
                document.getElementById("countfeatures").style.display = "block";
                document.getElementById("identifyswitches").style.display = "block";
                var headerCell = document.createElement("th");
                headerCell.className = "headerCell";
                var headerCell2 = document.getElementById("countfeatures");
                headerCell2.innerHTML =
                    '<span style="text-transform: uppercase; font-size:14px;">' +
                    selPts.length +
                    " " +
                    "Results" +
                    "</span>";




                if (selPts.length > 0) {
                    $("#countfeatures").append("<span id ='pinlayertopo' > &emsp;<i class='fa fa-map-pin' aria-hidden='true' title='create a new layer from your query'></i></span>");




                    $("#countfeatures").append("<span id ='pinlayertopoexport' > &emsp;<i class='fas fa-download' aria-hidden='true'  title='Download data'></i></span>");


                    $("#pinlayertopoexport").click(function() {


                        kmlexportinview(bridgelayer.toGeoJSON());


                    })



                    $("#pinlayertopo").click(function() {


                        var value = 'pinlayertopo';


                        pinlayer(selPts, value);

                        swal("the layer is pinned")

                    });
                }




                for (var i = 0; i < selPts.length; i++) {
                    document.getElementById("leftpanel").style.display = "block";
                    var $listItem = $("<li>")
                        .html(selPts[i].properties.index)
                        .appendTo("#toolbar ul");
                }




                document.getElementById("toolbar").scrollIntoView({
                        behavior: "smooth"
                    },
                    true
                );

                bridgelayer.on("click", function(e) {

                    var index = e.layer.feature.properties.index;

                    //cmpDebugLog(e.layer.feature.properties.index);
                    $.each($("#toolbar li"), function() {
                        this.style.color = "black";

                        if ($(this).html() === index) {
                            //cmpDebugLog($(this).text());
                            this.style.color = "orange";
                            this.scrollIntoView();
                        }
                    });
                }); //end of find                                          




                $("#toolbar li").click(function() {


                    $.each($("#toolbar li"), function() {
                        this.style.color = "black";
                    });

                    this.style.color = "orange";


                    index = this.innerHTML;

                    bridgelayer.eachLayer(function(layer) {

                        if (layer instanceof L.Polyline) {
                            layer.setStyle({
                                fillColor: "cyan",
                                fillOpacity: 0.1,
                                stroke: 5,
                                color: 'black'
                            });
                        }

                        if (layer.feature.id === index) {

                            //layer.fire("dblclick");	

                            if (layer instanceof L.Polyline) {
                                cmpDebugLog('layer is a polyline');
                                map.fitBounds(layer.getBounds());

                                layer.setStyle({
                                    fillColor: "blue",
                                    fillOpacity: 0.2,
                                    stroke: 8,
                                    color: 'yellow'
                                });

                            } else if (layer instanceof L.Marker) {
                                cmpDebugLog('layer is a marker');
                                var coords = layer._latlng;
                                map.setView(coords, 18);

                            } else

                            {
                                cmpDebugLog('layer is a shape unknown');
                                var coords = layer._latlng;
                                map.setView(coords, 18);
                            }
                        }

                    });


                });


                hideSpinner();
            });


        });




    } // if (identifyqueryswitch == true){ 


	}
	catch(error){
		
		cmpDebugLog(error)
		hideSpinner();
		
	}

} //end of SelectPoints function




