var overpassquerylayer = document.getElementById('overpassquerylayerSelect');


 function overpassquery() {

    $("#overpassquerylayerSelect")
        .fadeOut(150)
        .fadeIn(150)


    identifyqueryswitch = false;
    esriqueryswitch = false;

    if (overpassqueryswitch == true) {


        overpassbound.on("click", function(e) {
            $("#identifeatures").show();
            $("#identifyaccordion").accordion("activate", false);

            xy = null;
            lat = null;
            lon = null;


            lat = e.latlng.lat;
            lon = e.latlng.lng;
            cmpDebugLog('overpassbound clicked ');


            map.invalidateSize();




            bridgelayer.clearLayers();


            map.invalidateSize();
            //if ($osmrequest!== null){
            //$osmrequest= null;
            //map.invalidateSize();
            //}
            $("#identifeatures").show();
            $("#identifyaccordion").accordion("activate", false);


            document.getElementById("countfeatures").innerHTML = "";
            $("#toolbar li").remove();
            //$osmrequest = null;

            hideSpinner();
            showSpinner();
            bridgelayer.clearLayers();


            //setTimeout(function(){


            $("#toolbar li").remove();

            if (boundsrectangle != undefined) {
                map.removeLayer(boundsrectangle);
                map.invalidateSize();
            }

            var overpassApiUrl;




            xy = [lat, lon]; //center point of circle
            selPts = []; //Reset the array if selecting new points
            var bounds = L.latLng(xy).toBounds(getvaluefromslider());
            boundsrectangle = L.rectangle(bounds, {
                color: 'blue',
                weight: 2,
                fillOpacity: 0.0,
                interactive: false
            }).addTo(map);

            map.fitBounds(bounds);



            function buildOverpassApiUrl(map, overpassQuery) {
                var bounds = boundsrectangle.getBounds().getSouth() + ',' + boundsrectangle.getBounds().getWest() + ',' + boundsrectangle.getBounds().getNorth() + ',' + boundsrectangle.getBounds().getEast();
                var nodeQuery = 'node[' + overpassQuery + '](' + bounds + ');';
                var wayQuery = 'way[' + overpassQuery + '](' + bounds + ');';
                var relationQuery = 'relation[' + overpassQuery + '](' + bounds + ');';
                var query = '?data=[out:json][timeout:15];(' + nodeQuery + wayQuery + relationQuery + ');out body geom;';
                //var baseUrl = 'https://lz4.overpass-api.de/api/interpreter';
                var baseUrl = 'https://overpass-api.de/api/interpreter';
                var resultUrl = baseUrl + query;
                cmpDebugLog("resultUrl", resultUrl);
                return resultUrl;

            }




            bridgelayer.addTo(map);
            map.invalidateSize();

            var queryTextfieldValue = overpassquerylayer.value;




            var overpassApiUrl = buildOverpassApiUrl(map, queryTextfieldValue);




            $osmrequest = $.ajax({
                url: overpassApiUrl,
                type: 'GET',
                success: function(osmDataAsJson) {
                    bridgelayer.clearLayers();
                    var resultAsGeojson = osmtogeojson(osmDataAsJson);
                    //cmpDebugLog(resultAsGeojson);
                    //cmpDebugLog("resultAsGeojson.features", JSON.stringify(resultAsGeojson.features));
                    bridgelayer.addData(resultAsGeojson.features);
                    map.invalidateSize();
                    selPts.push(resultAsGeojson.features);
                    //cmpDebugLog(selPts[0]);




                    document.getElementById("closebuttonidentify").style.display = "block";
                    document.getElementById("radius_panel").style.display = "block";
                    document.getElementById("countfeatures").style.display = "block";
                    document.getElementById("identifyswitches").style.display = "block";
                    var headerCell = document.createElement("th");
                    headerCell.className = "headerCell";
                    var headerCell2 = document.getElementById("countfeatures");
                    headerCell2.innerHTML =
                        '<span style="text-transform: uppercase; font-size:14px;">' +
                        selPts[0].length +
                        " " +
                        "Results" +
                        "</span>";

                    //cmpDebugLog(selPts);




                    if (selPts[0].length > 0) {
                        $("#countfeatures").append("<span id ='pinlayerosm' > &emsp;<i class='fa fa-map-pin' aria-hidden='true' title='create a new layer from your query'></i></span>");


                        $("#countfeatures").append("<span id ='pinlayertopoexport' > &emsp;<i class='fas fa-download' aria-hidden='true'  title='Download data'></i></span>");


                        $("#pinlayertopoexport").click(function() {
                            kmlexportinview(bridgelayer.toGeoJSON());
                        })




                        var value = queryTextfieldValue;
                        $("#pinlayerosm").click(function() {
                            pinlayer(resultAsGeojson.features, value);
                            swal("the layer is pinned")
                        });
                    }

                    hideSpinner();

                },
                error: function(data) {
                    hideSpinner();

                    //bridgelayer.clearLayers();
                    // cmpDebugLog(JSON.stringify(data)); //or whatever
                    if (data.statusText === "Bad Request") {
                        if (overpassqueryswitch == true) {
                            swal('You made a bad request.Try a structured query');
                            map.invalidateSize();
                        }
                        if ($osmrequest !== null) {
                            $osmrequest = null;
                        }
                    } else if (data.statusText === "Too Many Requests") {
                        if (overpassqueryswitch == true) {
                            swal('Hey!! You made more requests that the server can handle. Please WAIT a few minutes and try again');
                            map.invalidateSize();
                        }
                        //if ($osmrequest !== null){ 
                        // $osmrequest = null;
                        //}
                    } else if (data.statusText === "Gateway Timeout") {
                        if (overpassqueryswitch == true) {
                            swal('The server is probably too busy to handle your request.! Try again later');
                            map.invalidateSize();
                        }
                        //if ($osmrequest !== null){ 
                        //$osmrequest = null;
                        //}

                    }


                } //error: function(data) {

            });


            map.invalidateSize();


        }); //on click

    }




}













