$locate.on('click', function(e) {
    overpassqueryswitch = false;
    //identifytopodata();
    identifycmpdata();

    if (!navigator.geolocation) {
        alert("<p>Sorry, your browser does not support Geolocation</p>");
        return;
    }

    navigator.geolocation.getCurrentPosition(successasd, errorsss, {
        timeout: 10000
    });


    $locate.fadeOut();
    //$findNearest.fadeIn();
    //$findNearest.fadeIn().trigger('click');
});

function errorsss() {
    alert("Unable to retrieve your location");
    if (hideSpinner) {
        hideSpinner();
    }
};



function successasd(position) {

    var currentPos = [position.coords.latitude, position.coords.longitude];

    map.setView(currentPos, 16);

    var myLocation = L.marker(currentPos)
        .addTo(map)
        .bindTooltip("you are here")
        .openTooltip();


    $findNearest.on('click', function(e) {
        queryFeatures(currentPos, 15);
        // myLocation.unbindTooltip();


    });

};




function queryFeatures(currentPos, numResults) {




    var distances = [];

    identify_pts.eachLayer(function(l) {

        layer_lat_long = l.getLatLng();

        var distance = L.latLng(currentPos).distanceTo(l.getLatLng()) / 1000;

        distances.push(distance);

    });




    distances.sort(function(a, b) {
        return a - b;
    });


    bridgelayer.addData(identify_pts.toGeoJSON());

    var distanceLayer = L.featureGroup();

    identify_pts.eachLayer(function(l) {

        cmpDebugLog(l);

        var distance = L.latLng(currentPos).distanceTo(l.getLatLng()) / 1000;

        cmpDebugLog(distance);

        if (distance < distances[numResults]) {

            cmpDebugLog(numResults);

            l.bindTooltip(distance.toLocaleString() + ' km from current location.');

            L.polyline([currentPos, l.getLatLng()], {
                color: 'yellow',
                weight: 3,
                opacity: 1,
                dashArray: "5, 3"
            }).addTo(bridgelayer);

            bridgelayer.addTo(map);
            //cmpDebugLog('distanceLayer'+distanceLayer);
        }

    });

    map.addLayer(distanceLayer);
    layerControl.addOverlay(distanceLayer, "distanceLayer");

}


