function kmlexportinview(data) {
    cmpDebugLog(data.features);
    //var data= pointsInView;
    //var data= linesInView[0];
    //cmpDebugLog(data);


    //data=data.toGeoJSON();




    var kml = tokml(data, {
        name: "name",
        description: "" + "description" + "",
        simplestyle: true
    });


    var elem = document.createElement("a");
    document.body.appendChild(elem);
    var convertedData =
        "application/vnd.google-earth.kml+xml;charset=utf-8," +
        encodeURIComponent(kml);

    //cmpDebugLog(convertedData);

    elem.setAttribute("href", "data:" + convertedData);
    elem.setAttribute("download", "" + new Date() + ".kml"); //elem.click();
    elem.click();
    document.body.removeChild(elem);
} ////////////////export individual layer//////////////

