const ArcGisDynamicLayer = L.TileLayer.extend({
    getTileUrl: function (coords) {
        const bounds = this._tileCoordsToBounds(coords);

        // Convert bounds to ArcGIS bbox format
        const bbox = [
            bounds.getWest(),
            bounds.getSouth(),
            bounds.getEast(),
            bounds.getNorth(),
        ].join(',');

        return L.Util.template(this._url, {
            bbox: bbox,
            width: this.options.tileSize,
            height: this.options.tileSize,
            format: 'PNG32', // Supported format
        });
    },
});







