// Add method to layer control class
L.Control.Layers.include({
    getActiveOverlays: function() {

        // Create array for holding active layers
        var active = [];

        // Iterate all layers in control
        this._layers.forEach(function(obj) {

            // Check if it's an overlay and added to the map
            if (map.hasLayer(obj.layer)) {

                // Push layer to active array
                active.push(obj.layer);
            }
        });

        // Return array
        return active;
    }
});



map.on('baselayerchange', function(e) {

    layer = e.layer;

    if ($('#snapshot').length) {
        var snapshot = document.getElementById("snapshot");
        snapshot.addEventListener("click", function() {
            var img;

            document.getElementById('thumbnail').src = "";
            img = null;

            var infodiv = document.querySelector(".info");

            if (!infodiv.hasAttribute("data-html2canvas-ignore")) {

                infodiv.setAttribute('data-html2canvas-ignore', true);

                var infohoverdiv = document.querySelector(".infohover");
                infohoverdiv.setAttribute('data-html2canvas-ignore', true);

              //  var controloverlaypane = document.querySelector("#map > div.leaflet-pane.leaflet-map-pane > div.leaflet-pane.leaflet-overlay-pane");
              //  controloverlaypane.setAttribute('data-html2canvas-ignore', true);

                var slidercontrol = document.querySelector("#map > div.leaflet-control-container > div.leaflet-bottom.leaflet-left > div.slider.leaflet-control");
                slidercontrol.setAttribute('data-html2canvas-ignore', true);

               // var markerpanecontrols = map.getPanes().markerPane;
               // markerpanecontrols.setAttribute('data-html2canvas-ignore', true);

                var upperrightcontrols = document.querySelector("#map > div.leaflet-control-container > div.leaflet-top.leaflet-right");
                upperrightcontrols.setAttribute('data-html2canvas-ignore', true);

               var bottomrightcontrols = document.querySelector("#map > div.leaflet-control-container > div.leaflet-bottom.leaflet-right");
                bottomrightcontrols.setAttribute('data-html2canvas-ignore', true);
            }

            var mapContainer = document.getElementById('map');
            html2canvas(mapContainer, {
                useCORS: true,
            }).then(canvas => {
                img = new Image();
                img.setAttribute('crossOrigin', 'anonymous');
                img.src = canvas.toDataURL('image/png');
                
                // Show the snapshot in thumbnail
                document.getElementById('thumbnail').src = canvas.toDataURL('image/png');

                // Create a download link
                var link = document.createElement('a');
                link.href = canvas.toDataURL('image/png'); // base64 image
                link.download = 'snapshot.png'; // File name for download
                link.style.display = 'none'; // Hide the link

                // Append link to body
                document.body.appendChild(link);
                
                // Programmatically click the link to trigger download
                link.click();

                // Remove the link after download
                document.body.removeChild(link);
            });

        });

    } ///if element exists

});



