var img = document.getElementById('attachmentbase64');
var fileattachmentinputs = document.getElementById('fileToUpload');
fileattachmentinputs.onchange = handleInput;
var seconduploadattachmentbase64 = [];



function handleInput(inputEvent) {

    var attachmentinput = document.getElementById('fileToUpload');
    var attachmentname = document.getElementById('fileToUpload').value;

    $('#attachmentvalue').val("");
    $('#attachmentvalue').val(attachmentname);

    var cleanedattachmentname = attachmentname.replace(/.*[\/\\]/, '');

    if (hasUnicode(cleanedattachmentname)) {

        cmpDebugLog('wrong');
        cmpDebugLog('cleanString', cleanString(cleanedattachmentname));
        $('#attachmentvalue').val("");
        $('#fileToUpload').val("");
        swal("Please use latin characters for the file name.! Non latin(utf8) characters are not supported.")
    } else

    {
        cmpDebugLog('right');
        cmpDebugLog(cleanString(cleanedattachmentname));




        var fileSize = attachmentinput.files[0].size / 1024 / 1024; // in MiB

        cmpDebugLog(fileSize, "Mbytes");

        if (fileSize < 9) {




            if (!isImageFile(cleanedattachmentname)) {

                cmpDebugLog('not image');

                $("#attachmentpreview").show();
                $("#attachmentpreview").html('<h5>' + cleanedattachmentname + '</h5>');
                $("#attachmentpreview").attr("href", cleanedattachmentname);

                document.getElementById("attachmentbase64preview").classList.add("hidden");
                document.getElementById("attachmentbase64preview").src = "";
                document.getElementById("attachmentbase64preview").href = "";
                $("#attachmentbase64").attr("src", "");
                $("#attachmentbase64").attr("href", "");
                $("#attachmentbase64").hide();

                cmpDebugLog('image');


            } else

            {
                cmpDebugLog('image');




                var files = inputEvent.target.files;
                if (files && files.length > 0) {
                    var file = window.file = files[0]; // global scope so visible in console
                    //cmpDebugLog('file, files:', file, files);

                    var displayElement = img;
                    displayElement.classList.remove('hidden');
                    var filepath = URL.createObjectURL(file);
                    //cmpDebugLog('filepath',filepath);

                    $("#attachmentbase64").show();
                    $("#attachmentpreview").hide();
                    var image = document.getElementById('attachmentbase64');
                    //image.classList.remove('hidden');
                    image.src = filepath;
                    image.href = filepath;
                    document.getElementById('attachmentbase64preview').classList.remove('hidden');
                    document.getElementById('attachmentbase64preview').src = filepath;
                    document.getElementById('attachmentbase64preview').href = filepath;
                    $('#attachmentbase64preview').html('<h4>Preview Image</h4>');


                    $('#attachmentbase64preview').venobox({
                        framewidth: '90%', // default: ''
                        frameheight: '90%', // default: ''
                        border: '10px', // default: '0'
                        closeBackground: '#2572d2',
                        bgcolor: '#b9e3fb', // default: '#fff'
                        titleattr: 'data-title', // default: 'title'
                        overlayClose: true,
                        numeratio: true, // default: false
                        infinigall: true, // default: false
                        share: ['download']
                    });




                    getBase64FromImageUrl(filepath);

                    function getBase64FromImageUrl(url) {
                        var img = new Image();
                        img.crossOrigin = "Anonymous";
                        img.setAttribute('crossOrigin', 'anonymous');
                        img.onload = function() {
                            var canvas = document.createElement("canvas");
                            canvas.width = 720;
                            canvas.height = 576;
                            //canvas.width = 420;
                            //  canvas.height = 270;
                            var ctx = canvas.getContext("2d", {
                                willReadFrequently: true
                            });
                            //ctx.drawImage(this, 0, 0);
                            ctx.drawImage(img, 0, 0, img.width, img.height, 0, 0, canvas.width, canvas.height);
                            var dataURLasd = canvas.toDataURL("image/jpg");
                            seconduploadattachmentbase64 = [];
                            seconduploadattachmentbase64.push(dataURLasd);
                            //alert(dataURL.replace(/^data:image\/(png|jpg);base64,/, ""));
                            //cmpDebugLog(dataURLasd);
                            //alert(dataURLasd);
                            ctx.clearRect(0, 0, canvas.width, canvas.height); //clear the canvas
                            $("#attachment").val('');
                            $("#attachment").html('');
                            $("#attachment").val(seconduploadattachmentbase64);
                            //alert($("#attachment").val());
                            //var image = document.getElementById('attachmentbase64');
                            // image.classList.remove('hidden');
                            //image.src = seconduploadattachmentbase64;



                        };

                        img.src = url;

                    } //finish of base64 function


                }




            } //if (!isImageFile(cleanedattachmentname)) {


        } else {
            swal('This file you are trying to attach is too large!!');
            cmpDebugLog('do nothing');
            $('#attachmentvalue').val("");
            $('#fileToUpload').val("");

        }


    }



}

