map.on("baselayerchange", onBaseLayerChanged); // Called when the base layer (meaning the floor) is changed

function onBaseLayerChanged(event) {


    layerControl.collapse();

    map.invalidateSize();

    document.getElementById("showhistoricalimageryid").click();
    //var layerControlElement = document.getElementsByClassName('leaflet-control-layers-base')[0];
    //var googleselected = layerControlElement.getElementsByTagName('input')[1];
    //var googleselected = layerControlElement.getElementsByTagName('input')[1].click();
    //alert("LAYER HAS BEEN CHANGED.");
    map.removeLayer(historicalmapgroup);
    map.removeLayer(basemaplayers);
    map.removeLayer(agooglefirstlayer); // Update the current floor

    if (map.hasLayer(agooglefirstlayer)) {
        $("#leaflet-slider").slider("option", "value", 5);
        $("#slider-timestamp").html("" + new Date().getFullYear() + "" + "-google");
    } else if (map.hasLayer(googleSat)) {
        $("#leaflet-slider").slider("option", "value", 5);
        $("#slider-timestamp").html("" + new Date().getFullYear() + "" + "-google");
    } else if (map.hasLayer(bing)) {
        $("#slider-timestamp").html("2016-2023-Bing");
        $("#leaflet-slider").slider("option", "value", 3);
    } else if (map.hasLayer(sat2009a)) {
        $("#leaflet-slider").slider("option", "value", 2);
        $("#slider-timestamp").html("2009-2013-dls");
    } else if (map.hasLayer(google)) {
        $("#leaflet-slider").slider("option", "value", 5);
        $("#slider-timestamp").html("" + new Date().getFullYear() + "" + "-google");
        map.removeLayer(agooglefirstlayer);
    } else if (map.hasLayer(cyprus_topo)) {
        //$('#leaflet-slider').attr('style', 'display: none');
        $("#leaflet-slider").css("display", "none"); //historicalimagerycontrol.state('show-historicalimagery');
    } else if (map.hasLayer(opentopo)) {
        // $('#leaflet-slider').attr('style', 'display: none');
        $("#leaflet-slider").css("display", "none"); // historicalimagerycontrol.state('show-historicalimagery');
	}
   else if (map.hasLayer(sat1963historicalimagery)) {
        $("#leaflet-slider").slider("option", "value", 0);
        $("#slider-timestamp").html("1963-dls");
    } else if (map.hasLayer(kitchener)) {
        $("#leaflet-slider").css("display", "none");
    } else if (map.hasLayer(googleStreets)) {
        $("#leaflet-slider").css("display", "none");
    }

} //end of if statement


