var map_example = {};

var map_examplehover = {};

map_example.init = function() {
    map_example.add_info_box(map);
    map_examplehover.add_info_boxehover(map);

};

map_example.add_info_box = function(map) {
    //Add an Info box in top right to show information on area
    var info = L.control({
        position: "bottomleft"
    });

    info.onAdd = function(map) {
        this._div = L.DomUtil.create("div", "info"); // create a div with a class "info"

        this.update();
        return this._div;
    };

    info.update = function(latlng) {
		
		
		         //var mgrsCoords = mgrs.forward([longitude, latitude], 5);  // Precision: 5

        var location_text = map_example.convert_ll_to_string(latlng, map);
		
        var location_textw = location_text.replace(/ /g, "");
        this._div.innerHTML = "Clicked at:<br>" + (location_textw ? location_textw : "");
    }; ////FUNCTION ON HOVER/////

    function onMapHover(e) {
        info.update(e.latlng);
    }

    map.on("mousedown", onMapHover);
    info.addTo(map); ////FUNCTION ON HOVER/////

    function onMapmove(e) {
        info.update(e.latlng, map.zoom);
    } // map.on('mousedown',onMapmove); info.addTo(map);};

    map.on("click", onMapmove);
    info.addTo(map);




}; //;
//info.addTo(map);









map_examplehover.add_info_boxehover = function(map) {

    var infohover = L.control({
        position: "bottomleft"
    });



    infohover.onAdd = function(map) {
        this._div = L.DomUtil.create("div", "infohover"); // create a div with a class "infohover"

        L.DomEvent.disableClickPropagation(this._div);
        this.update();
        return this._div;
    };



    infohover.update = function(latlng) {
        var location_texthover = map_example.convert_ll_to_string(latlng, map);
        var location_textwhover = location_texthover.replace(/ /g, "");
        this._div.innerHTML = "" + (location_textwhover ? location_textwhover : "");
    }; ////FUNCTION ON HOVER/////




    function onMapmovehover(e) {
        infohover.update(e.latlng);
        //infohover.update(e.latlng, map.zoom);
    }


 
	


    if (!L.Browser.mobile) {
		 map.on("mousemove", onMapmovehover);
        infohover.addTo(map);

    }
	
	else
		
		{
			 map.on("mousedown", onMapmovehover);
        infohover.addTo(map);
			
		}

};





