var polygon;

map_example.convert_ll_to_string = function(latlng, zoom, map) {
    var text, lat, lng;

    if (latlng) {
        lat = latlng.lat;
        lng = latlng.lng || latlng.lon || 0; //If MapTools library is loaded

        if (typeof maptools != "undefined" && maptools.inUSBounds) {
            var grid_zoom = zoom > 12 ? 3 : zoom > 7 ? 4 : 5;
            var point_data = maptools.locationInfoString({
                lat: lat,
                lng: lng,
                zoom: zoom,
                boldTitles: false,
                overPrecision: grid_zoom
            });
            text = point_data.toString();
        } else {
            if (lat && lng) {
                var textArray = [];
                textArray.push("Lat:  " + lat.toFixed(8));
                textArray.push("Lng: " + lng.toFixed(8)); //if (zoom) textArray.push("Zoom: " + zoom);

                text = textArray.join("");
            } else {
                text = "<p>";
            }
        }
    } else {
        text = latlng ? latlng.toString() : "";
    }

    return text;
};




