// ===== Conditional Legend (only when any layer is checked) =====
let legendOpen = false;
let legendControl = null;

function showLegend() {
  const el = document.getElementById('legendModal');
  if (el) { el.classList.add('show'); legendOpen = true; }
}
function hideLegend() {
  const el = document.getElementById('legendModal');
  if (el) { el.classList.remove('show'); legendOpen = false; }
}
function toggleLegend() { legendOpen ? hideLegend() : showLegend(); }

// Build modal HTML only when needed
function createLegendModal() {
  if (document.getElementById('legendModal')) return;
  const el = document.createElement('div');
  el.id = 'legendModal';
  el.className = 'legend-modal';
  el.setAttribute('aria-hidden', 'true');
  el.innerHTML = `
    <div class="legend-card" role="dialog" aria-modal="true" aria-labelledby="legendTitle">
      <div class="legend-header">
        <div id="legendTitle" class="legend-title">UNFICYP — Legend</div>
        <button class="legend-close" title="Close" aria-label="Close">&times;</button>
      </div>

      <div class="legend-body">
        <!-- UN posts -->
        <div class="legend-row">
          <img src="./data/un-posts/un_flag.png" alt="UN Posts" class="legend-un-img">
          <div class="legend-label">UN Posts</div>
        </div>

        <!-- 1974 -->
        <div class="legend-section-title">1974</div>
        <div class="legend-row"><span class="force-icon">B</span><div class="legend-label">BRITISH CONTINGENT 1974</div></div>
        <div class="legend-row"><span class="force-icon">S</span><div class="legend-label">SWEDISH CONTINGENT 1974</div></div>
        <div class="legend-row"><span class="force-icon">C</span><div class="legend-label">CANADIAN CONTINGENT 1974</div></div>
        <div class="legend-row"><span class="force-icon">F</span><div class="legend-label">FINNISH CONTINGENT 1974</div></div>
        <div class="legend-row"><span class="force-icon">AU</span><div class="legend-label">AUSTRIAN CONTINGENT 1974</div></div>
        <div class="legend-row"><span class="force-icon">DA</span><div class="legend-label">DANISH CONTINGENT 1974</div></div>

        <!-- 1964 -->
        <div class="legend-section-title">1964</div>
        <div class="legend-row"><span class="force-icon force-1964">AT</span><div class="legend-label">AUSTRIAN CONTINGENT 1964</div></div>
        <div class="legend-row"><span class="force-icon force-1964">AUS</span><div class="legend-label">AUSTRALIAN CONTINGENT 1964</div></div>
        <div class="legend-row"><span class="force-icon force-1964">C</span><div class="legend-label">CANADIAN CONTINGENT 1964</div></div>
        <div class="legend-row"><span class="force-icon force-1964">DA</span><div class="legend-label">DANISH CONTINGENT 1964</div></div>
        <div class="legend-row"><span class="force-icon force-1964">S</span><div class="legend-label">SWEDISH CONTINGENT 1964</div></div>
      </div>
    </div>`;
  document.body.appendChild(el);

  // close button + map click hide
  el.querySelector('.legend-close').addEventListener('click', hideLegend);
  map.on('click', hideLegend);
}

function removeLegendModal() {
  const el = document.getElementById('legendModal');
  if (el) el.remove();
  map.off('click', hideLegend);
  legendOpen = false;
}

// Leaflet control (button) – create/destroy on demand
const LegendControl = L.Control.extend({
  options: { position: 'bottomright' },
  onAdd: function () {
    const div = L.DomUtil.create('div', 'leaflet-control legend-control');
    const btn = L.DomUtil.create('button', 'legend-toggle-btn', div);
    btn.type = 'button';
    btn.title = 'Legend';
    btn.textContent = 'Legend';
    L.DomEvent.disableClickPropagation(div);
    L.DomEvent.on(btn, 'click', function (e) {
      L.DomEvent.stopPropagation(e);
      toggleLegend();
    });
    return div;
  }
});

function addLegendControl() {
  if (!legendControl) {
    legendControl = new LegendControl();
    map.addControl(legendControl);
  }
}
function removeLegendControl() {
  if (legendControl) {
    map.removeControl(legendControl);
    legendControl = null;
  }
}

