// globals
let gj, unpostslayer;
let unpostsLayerLoadPromise = null;

function bindStableChangeHandler(element, key, handler) {
  if (!element) {
    return;
  }

  var handlerKey = "__cmpChangeHandler_" + key;
  if (element[handlerKey]) {
    element.removeEventListener('change', element[handlerKey]);
  }

  element[handlerKey] = handler;
  element.addEventListener('change', handler);
}

function ensureUnpostsLayerLoaded() {
  if (unpostslayer) {
    return Promise.resolve(unpostslayer);
  }

  if (unpostsLayerLoadPromise) {
    return unpostsLayerLoadPromise;
  }

  unpostsLayerLoadPromise = fetch('./data/un-posts/doc.geojson')
    .then(function(response) {
      if (!response.ok) {
        throw new Error('Failed to load UN posts layer');
      }
      return response.json();
    })
    .then(function(data) {
      gj = data;

      const unIcon = L.icon({
        iconUrl: './data/un-posts/un_flag.png',
        iconSize: [30, 30],
        iconAnchor: [15, 15],
        popupAnchor: [0, -15]
      });

      const propTooltipHTML = (props = {}) =>
        Object.entries(props).map(([k, v]) => `<div><b>${k}</b>: ${v}</div>`).join('') || 'No properties';

      unpostslayer = L.geoJSON(gj, {
        pointToLayer: (feature, latlng) => L.marker(latlng, { icon: unIcon }),
        onEachFeature: (feature, layer) => {
          layer.bindTooltip(propTooltipHTML(feature.properties || {}), {
            direction: 'top',
            offset: [0, -16],
            sticky: true
          });
          layer.on('click', (e) => {
            if (typeof info === 'function') info(e);
            layer.openTooltip();
          });
          if (typeof oms !== 'undefined' && layer instanceof L.Marker) {
            oms.addMarker(layer);
          }
        }
      });

      return unpostslayer;
    })
    .catch(function(error) {
      unpostsLayerLoadPromise = null;
      console.warn('UN posts layer load failed:', error);
      throw error;
    });

  return unpostsLayerLoadPromise;
}

const unpostsBox = document.querySelector('#unpostsid');
if (unpostsBox) {
  unpostsBox.removeEventListener('change', updateLegendUI);
  unpostsBox.addEventListener('change', updateLegendUI);

  bindStableChangeHandler(unpostsBox, 'unpostsLayerToggle', function () {
    var checkbox = this;
    if (!checkbox.checked) {
      if (unpostslayer && map.hasLayer(unpostslayer)) {
        map.removeLayer(unpostslayer);
      }
      return;
    }

    ensureUnpostsLayerLoaded().then(function(layer) {
      if (checkbox.checked) {
        map.addLayer(layer);
      }
    }).catch(function() {});
  });

  if (unpostsBox.checked) {
    unpostsBox.dispatchEvent(new Event('change'));
  }
}

/* ======================================================================
   FORCES (generic loader) — Reused for 1974 and 1964
   ====================================================================== */

let forceLayers = {};
let forceLayerLoadPromises = {};
// NOTE: if OverlappingMarkerSpiderfier is used globally, keep `oms` global elsewhere.

// Icon builder with variant to color-code (1974=blue, 1964=cyan)
function makeInitialIcon(letter, variant = '1974') {
  const cls = variant === '1964' ? 'force-icon force-1964' : 'force-icon';
  return L.divIcon({
    className: '',
    html: `<div class="${cls}">${letter}</div>`,
    iconSize: [28, 28],
    iconAnchor: [14, 14],
    popupAnchor: [0, -14]
  });
}

function ensureForceLayerLoaded(options) {
  const key = options.key;

  if (forceLayers[key]) {
    return Promise.resolve(forceLayers[key]);
  }

  if (forceLayerLoadPromises[key]) {
    return forceLayerLoadPromises[key];
  }

  forceLayerLoadPromises[key] = fetch(options.url)
    .then(function(response) {
      if (!response.ok) {
        throw new Error('GeoJSON not found at ' + options.url);
      }
      return response.json();
    })
    .then(function(data) {
      const icon = makeInitialIcon(options.initial, options.variant);

      const layer = L.geoJSON(data, {
        pointToLayer: (feature, latlng) => {
          const marker = L.marker(latlng, { icon: icon });
          marker.on('click', (e) => { if (typeof info === 'function') info(e); });
          if (typeof oms !== 'undefined' && oms) oms.addMarker(marker);
          return marker;
        }
      });

      forceLayers[key] = layer;
      return layer;
    })
    .catch(function(error) {
      delete forceLayerLoadPromises[key];
      console.warn('Force layer load failed for ' + key + ':', error);
      throw error;
    });

  return forceLayerLoadPromises[key];
}

// Generic loader for a force
function addForceLayer(options) {
  const checkboxId = options.checkboxId;

  if (checkboxId) {
    const box = document.querySelector(checkboxId);
    if (box) {
      box.removeEventListener('change', updateLegendUI);
      box.addEventListener('change', updateLegendUI);

      bindStableChangeHandler(box, options.key + '_toggle', function () {
        var checkbox = this;
        if (!checkbox.checked) {
          if (forceLayers[options.key] && map.hasLayer(forceLayers[options.key])) {
            map.removeLayer(forceLayers[options.key]);
          }
          return;
        }

        ensureForceLayerLoaded(options).then(function(layer) {
          if (checkbox.checked) {
            map.addLayer(layer);
          }
        }).catch(function() {});
      });

      if (box.checked) {
        box.dispatchEvent(new Event('change'));
      }
    }
  } else {
    ensureForceLayerLoaded(options).then(function(layer) {
      map.addLayer(layer);
    }).catch(function() {});
  }
}

