var parcelspostgisswitch = false;
$(".mdl-card--cadastral").change(function() {
    if ($(this).hasClass("is-checked")) {
        map.invalidateSize();
        map.addLayer(parcelspostgislayer);

        if (map.getZoom() < 15) {
            map.flyTo(map.getBounds().getCenter(), 16);
            map.invalidateSize();

            // Wait for the flyTo animation to complete
            map.once('moveend', function() {
                sendParcelRequest(); // Make the request after zooming
            });
        } else {
            // If already at the desired zoom level, make the request immediately
            sendParcelRequest();
        }

        parcelspostgisswitch = true;
        parcelspostgislayer.addTo(map);

    } else {
        map.invalidateSize();
        parcelspostgisswitch = false;
        map.removeLayer(parcelspostgislayer);
    }
});

// Function to send the parcel request
function sendParcelRequest() {
    if (map.hasLayer(parcelspostgislayer)) {
        parcelspostgislayer.clearLayers();
    }

    var bounds = map.getBounds();

    // Show spinner before the AJAX request (optional)
    if (typeof showSpinner === "function") {
        showSpinner();
    }

    // Set a timeout to stop the spinner after a certain time limit (e.g., 15 seconds)
    var requestTimeout = setTimeout(function() {
        if (typeof hideSpinner === "function") {
            hideSpinner();
        }
        swal("Timeout", "The request took too long to complete. Please try again.", "warning");
    }, 15000); // 15 seconds timeout

    // Send a POST request to the PHP script with the bounds
    $.post('../php/check-parcels.php', {
        bounds: JSON.stringify(bounds),
    })
    .done(function(response) {
        clearTimeout(requestTimeout);
        // Hide spinner after successful completion (optional)
        if (typeof hideSpinner === "function") {
            hideSpinner();
        }

        // Parse the response as a GeoJSON feature collection
        var featureCollection = JSON.parse(response);

        if (map.hasLayer(parcelspostgislayer)) {
            parcelspostgislayer.clearLayers();
        }

        parcelspostgislayer.addData(featureCollection);
    })
    .fail(function(xhr, status, error) {
        // Hide spinner in case of error (optional)
        if (typeof hideSpinner === "function") {
            hideSpinner();
        }

        cmpDebugLog("Error: " + error); // Log error for debugging
        swal("Error", "There was a problem loading the parcel data: " + error, "error"); // Show error message
    });

    // Existing function call
    getpacelsfunction();
}

 ///////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////



