function cmpEnsureDeferredGeoJsonLayerLoaded(layerKey, options) {
  const config = cmpDeferredGeoJsonLayers[layerKey];
  const shouldUseSpinner = !options || options.useSpinner !== false;

  if (!config || !config.layer) {
    return Promise.resolve(null);
  }

  if (typeof config.layer.getLayers === "function" && config.layer.getLayers().length > 0) {
    config.loaded = true;
  }

  if (config.loaded) {
    return Promise.resolve(config.layer);
  }

  if (config.promise) {
    return config.promise;
  }

  if (shouldUseSpinner && typeof showSpinner === "function") {
    showSpinner();
  }

  config.promise = new Promise(function(resolve, reject) {
    $.getJSON(config.url)
      .done(function(data) {
        config.layer.addData(data);
        config.loaded = true;
        resolve(config.layer);
      })
      .fail(function(jqxhr, textStatus, errorThrown) {
        const reason = errorThrown || textStatus || "Unknown error";
        console.error("Failed to load " + config.label + " GeoJSON:", reason);
        reject(new Error(reason));
      })
      .always(function() {
        config.promise = null;

        if (shouldUseSpinner && typeof hideSpinner === "function") {
          hideSpinner();
        }
      });
  });

  return config.promise;
}

function cmpPushLayerNameOnce(layerName) {
  if (layersarray.indexOf(layerName) === -1) {
    layersarray.push(layerName);
  }
}

function cmpGetFeatureActionLatLng(layer, event) {
  if (event && event.latlng && typeof event.latlng.lat === "number" && typeof event.latlng.lng === "number") {
    return event.latlng;
  }

  if (layer && typeof layer.getLatLng === "function") {
    return layer.getLatLng();
  }

  if (layer && typeof layer.getBounds === "function") {
    var bounds = layer.getBounds();
    if (bounds && typeof bounds.getCenter === "function") {
      return bounds.getCenter();
    }
  }

  return map && typeof map.getCenter === "function" ? map.getCenter() : null;
}

function cmpBuildNavigateButtonHtml(latlng) {
  if (!latlng || typeof latlng.lat !== "number" || typeof latlng.lng !== "number") {
    return "";
  }

  return '<button id="Navigate"><a href="https://maps.apple.com/?q=' + latlng.lat + ',' + latlng.lng + '" target="_blank" style="text-decoration: none;">Navigate  &nbsp; <i class="fas fa-route"></i></a></button>';
}

function cmpGetFeatureTableElement(container) {
  if (!container) {
    return null;
  }

  if (container.tagName && container.tagName.toLowerCase() === "table") {
    return container;
  }

  return container.querySelector("table");
}

