function cmpFinalizeDeferredCoreGeoJsonLayer(config) {
  overlayLayers[L.Util.stamp(config.layer)] = config.layer;

  if (
    config.cluster &&
    typeof config.cluster.hasLayer === "function" &&
    config.cluster.hasLayer(config.layer) &&
    typeof config.cluster.refreshClusters === "function"
  ) {
    config.cluster.refreshClusters(config.layer);
  }
}

function cmpEnsureDeferredCoreGeoJsonLayerLoaded(layerKey, options) {
  const config = cmpDeferredCoreGeoJsonLayers[layerKey];
  const shouldUseSpinner = !options || options.useSpinner !== false;

  if (!config || !config.layer) {
    return Promise.resolve(null);
  }

  if (typeof config.layer.getLayers === "function" && config.layer.getLayers().length > 0) {
    config.loaded = true;
  }

  if (config.loaded) {
    cmpFinalizeDeferredCoreGeoJsonLayer(config);
    return Promise.resolve(config.layer);
  }

  if (config.promise) {
    return config.promise;
  }

  if (shouldUseSpinner && typeof showSpinner === "function") {
    showSpinner();
  }

  config.promise = new Promise(function(resolve, reject) {
    $.getJSON(config.url)
      .done(function(data) {
        config.layer.addData(data);
        config.loaded = true;
        cmpFinalizeDeferredCoreGeoJsonLayer(config);
        resolve(config.layer);
      })
      .fail(function(jqxhr, textStatus, errorThrown) {
        const reason = errorThrown || textStatus || "Unknown error";
        console.error("Failed to load " + config.label + " GeoJSON:", reason);
        reject(new Error(reason));
      })
      .always(function() {
        config.promise = null;

        if (shouldUseSpinner && typeof hideSpinner === "function") {
          hideSpinner();
        }
      });
  });

  return config.promise;
}

function cmpEnsurePrimarySearchLayersLoaded(options) {
  return Promise.all([
    cmpEnsureDeferredCoreGeoJsonLayerLoaded("sites", options),
    cmpEnsureDeferredCoreGeoJsonLayerLoaded("identified", options)
  ]);
}

function cmpArePrimarySearchLayersLoaded() {
  return Object.keys(cmpDeferredCoreGeoJsonLayers).every(function(layerKey) {
    const config = cmpDeferredCoreGeoJsonLayers[layerKey];

    if (!config || !config.layer) {
      return true;
    }

    if (typeof config.layer.getLayers === "function" && config.layer.getLayers().length > 0) {
      config.loaded = true;
    }

    return config.loaded;
  });
}

function cmpAttachDeferredCoreGeoJsonLayer(layerKey) {
  const config = cmpDeferredCoreGeoJsonLayers[layerKey];

  if (!config || !config.cluster) {
    return;
  }

  if (typeof config.cluster.hasLayer === "function" && !config.cluster.hasLayer(config.layer)) {
    config.cluster.addLayer(config.layer);
  }

  if (!map.hasLayer(config.cluster)) {
    map.addLayer(config.cluster);
  }

  if (typeof config.cluster.refreshClusters === "function") {
    config.cluster.refreshClusters(config.layer);
  }
}

function cmpOpenDeferredCoreDashboardTable(layerKey, title) {
  const config = cmpDeferredCoreGeoJsonLayers[layerKey];

  if (!config || !config.layer) {
    return;
  }

  cmpEnsureDeferredCoreGeoJsonLayerLoaded(layerKey, {
    useSpinner: true
  }).then(function() {
    cmpOpenDashboardTable(config.layer, title);
  }).catch(function(error) {
    console.error("Deferred core GeoJSON layer load failed:", layerKey, error);
    swal("The requested layer is not available right now.");
  });
}

