function cmpSyncIdentifyTopographyGroup(layerKeys) {
  topogrouplayer.clearLayers();

  layerKeys.forEach(function(layerKey) {
    const config = cmpDeferredIdentifyTopographyLayers[layerKey];

    if (!config || !config.layer) {
      return;
    }

    if (typeof config.layer.getLayers === "function" && config.layer.getLayers().length === 0) {
      return;
    }

    topogrouplayer.addLayer(config.layer);
  });
}

function cmpEnsureSelectedIdentifyTopographyLayersLoaded(options) {
  const selectedLayerKeys = cmpGetSelectedIdentifyTopographyLayerKeys();
  const shouldUseSpinner = !options || options.useSpinner !== false;

  if (!selectedLayerKeys.length) {
    topogrouplayer.clearLayers();
    return Promise.resolve([]);
  }

  if (shouldUseSpinner && typeof showSpinner === "function") {
    showSpinner();
  }

  return Promise.all(selectedLayerKeys.map(function(layerKey) {
    return cmpEnsureDeferredTopographyGeoJsonLayerLoaded(layerKey, {
      useSpinner: false
    });
  })).then(function() {
    cmpSyncIdentifyTopographyGroup(selectedLayerKeys);
    return selectedLayerKeys;
  }).finally(function() {
    if (shouldUseSpinner && typeof hideSpinner === "function") {
      hideSpinner();
    }
  });
}

function officesParentOn() {
  // works with MDL: either the hidden input is checked OR label got "is-checked"
  const input = document.getElementById('offices_info_input');
  const label = document.getElementById('officesinfo_label') || document.querySelector('.mdl-card--offices_info');
  return (input && input.checked) || (label && label.classList.contains('is-checked'));
}

function gateLayer(checkboxSel, layer, zoomOK, extraLayers = [], deferredLayerKey = null, options = {}) {
  const box = document.querySelector(checkboxSel);
  const shouldShow = zoomOK && officesParentOn() && box && box.checked;

  const ensureRemove = (lyr) => { if (map.hasLayer(lyr)) map.removeLayer(lyr); };
  const ensureAdd    = (lyr) => { if (!map.hasLayer(lyr)) map.addLayer(lyr); };

  if (shouldShow) {
    ensureAdd(layer);
    extraLayers.forEach(ensureAdd);

    if (deferredLayerKey && options.allowDataLoad !== false) {
      cmpEnsureDeferredGeoJsonLayerLoaded(deferredLayerKey, {
        useSpinner: options.useSpinner !== false
      }).catch(function(error) {
        console.error("Deferred GeoJSON layer load failed:", deferredLayerKey, error);
      });
    }
  } else {
    ensureRemove(layer);
    extraLayers.forEach(ensureRemove);
  }
}

// Call this whenever zoom or any checkbox changes
function updateOfficeLayers(options = {}) {
  const zoomOK = map.getZoom() > 13; // your threshold

  // Offices
  gateLayer('#gkcoffice',        gkcofficesinfo,          zoomOK, [], 'gkcofficesinfo', options);
  gateLayer('#tkcoffice',        tkcofficesinfo,          zoomOK, [], 'tkcofficesinfo', options);

  // Documents / datasets
  gateLayer('#tkcdocumentsid',   tkc_documents,           zoomOK, [], 'tkc_documents', options);
  gateLayer('#gkcdocumentsid',   Gkc_Documents,           zoomOK, [], 'Gkc_Documents', options);
  gateLayer('#analysisbasketid', analysisbasket,          zoomOK, [], 'analysisbasket', options);
  gateLayer('#documents192id',   points192,               zoomOK, [], 'points192', options);

  // Site profile (toggles two layers together)
  gateLayer('#siteprofileid',    site_profiles_custom_layer, zoomOK, [siteprofilesoapbyguidLayer], 'site_profiles_custom_layer', options);
}

// Wire up once
const watched = [
  '#offices_info_input',
  '#gkcoffice', '#tkcoffice',
  '#tkcdocumentsid', '#gkcdocumentsid',
  '#analysisbasketid', '#documents192id',
  '#siteprofileid'
];
document.addEventListener('DOMContentLoaded', () => {
  // listen to all checkboxes (and MDL parent)
  $(watched.join(',')).on('change.offices', function() {
    updateOfficeLayers({ allowDataLoad: true, useSpinner: true });
  });
  // update on zoom changes
  map.on('zoomend', function() {
    updateOfficeLayers({
      allowDataLoad: cmpDeferredOfficeLayerAutoLoadReady,
      useSpinner: false
    });
  });
  // initial
  updateOfficeLayers({ allowDataLoad: false, useSpinner: false });
});








