var metadatatagsarray = [];

function handleFileexif(event) {
    var files = event.target.files;
    var geotagreader = new FileReader();
    window.exifReaderClear();

    geotagreader.onload = function(readerEvent) {
        try {
            var tags = ExifReader.load(readerEvent.target.result); // The MakerNote tag can be really large. Remove it to lower
            // memory usage if you're parsing a lot of files and saving the
            // tags.

            delete tags["MakerNote"]; // If you want to extract the thumbnail you can use it like
            // this:

            if (tags["Thumbnail"] && tags["Thumbnail"].image) {
                //var image = document.getElementById('thumbnail');
                //image.classList.remove('hidden');
                //image.src = 'data:image/jpg;base64,' + tags['Thumbnail'].base64;
                //uploadattachmentbase64=[];
                //uploadattachmentbase64.push(image.src);
                //cmpDebugLog(tags);
                metadatatagsarray = [];
                delete tags["base64"];
                delete tags["Thumbnail"];
                metadatatagsarray.push(tags);

                cmpDebugLog("metadatatags", metadatatagsarray);
                $("#metadata").val(JSON.stringify(metadatatagsarray));
            }

            window.exifReaderListTags(tags);
        } catch (error) {
            window.exifReaderError(error.toString());
        }
    };

    geotagreader.readAsArrayBuffer(files[0]);
}

var uploadattachmentbase64 = []; // default array to store images

var photos = []; // convert gps data to latitude, longitude

function gpsCoordinates(coord) {
    return (
        coord[0].numerator +
        coord[1].numerator / (60 * coord[1].denominator) +
        coord[2].numerator / (3600 * coord[2].denominator)
    );
} // get data from user photos

function handlePhotos(files) {
	
    var _this11 = this; //cmpDebugLog(files);

    _toConsumableArray(files).forEach(
        function(file) {
            _newArrowCheck(this, _this11);

            uploadattachmentbase64 = []; // cmpDebugLog(file );

            EXIF.getData(file, function() {
                if (
                    Object.keys(file.exifdata).length === 0 ||
                    EXIF.getTag(this, "GPSLatitude") === undefined ||
                    EXIF.getTag(this, "GPSLongitude") === undefined
                ) {
                    swal("The uploaded file has no coordinates associated with it");
                    map.removeLayer(exifmarkersGroup);


                    $.getScript("./js/leaflet-distortableimage@0.21.9.js").done(function() {
                        $.getScript("./js/leaflet.distortableimage.js").done(function() {
                            distortimage(file)
                        }).fail(function(jqxhr, settings, exception) {
                            hideSpinner();
                        });
                    }).fail(function(jqxhr, settings, exception) {
                        hideSpinner();
                    });

                    document.getElementById('exif-table-body').innerHTML = '';
                    document.getElementById("fileloadgenericinput").value = '';
                    return false; // no exif data found
                } //////////dika moy
                else {


                }

                var filepath = URL.createObjectURL(file); //cmpDebugLog('filepath',filepath);

                getBase64FromImageUrl(filepath);

                function getBase64FromImageUrl(url) {
                    var img = new Image();
                    img.setAttribute("crossOrigin", "anonymous");

                    img.onload = function() {
                        var canvas = document.createElement("canvas");
                        canvas.width = 720;
                        canvas.height = 576;
                        var ctx = canvas.getContext("2d", {
                            willReadFrequently: true
                        }); //ctx.drawImage(this, 0, 0);

                        ctx.drawImage(
                            img,
                            0,
                            0,
                            img.width,
                            img.height,
                            0,
                            0,
                            canvas.width,
                            canvas.height
                        );
                        var dataURLasd = canvas.toDataURL("image/jpg");
                        uploadattachmentbase64.push(dataURLasd); //alert(dataURL.replace(/^data:image\/(png|jpg);base64,/, ""));
                        //cmpDebugLog(dataURLasd);

                        ctx.clearRect(0, 0, canvas.width, canvas.height); //clear the canvas
                    };

                    img.src = url;
                } //////////dika moy

                var allMetaData = EXIF.getAllTags(this);
                var base64 = uploadattachmentbase64;
                var alt = EXIF.getTag(this, "GPSAltitude");
                var lat = EXIF.getTag(this, "GPSLatitude");

                var _long = EXIF.getTag(this, "GPSLongitude");

                var metadatatags = metadatatagsarray[0];


                //cmpDebugLog(metadatatags);
                var date =
                    EXIF.getTag(this, "DateTimeOriginal") === undefined ?
                    EXIF.getTag(this, "DateTime") :
                    EXIF.getTag(this, "DateTimeOriginal");
                var photo = new Photo(
                    file.name.slice(0, -4),
                    (window.URL || window.webkitURL).createObjectURL(file),
                    gpsCoordinates(lat),
                    gpsCoordinates(_long),
                    date,
                    alt,
                    base64,
                    metadatatags
                );
                photos.push(photo);
                addPhotoToMap(photo); //cmpDebugLog('metadatatagsarraysdfsdffsdf',metadatatags);
                //cmpDebugLog(photo.base64);
                //cmpDebugLog('photo filePath',photo.filePath);

                var image = document.getElementById("thumbnail");
                image.classList.remove("hidden");
                image.src = photo.filePath;




            });
        }.bind(this)
    ); // update drop zone text
    //updateDropzone( 'body', files, false );
}

