async function gdalmanipulate(geotiffarray){

// Create a Blob from the binary data
//const blob = new Blob([geotiffarray], { type: 'image/tiff' });


const file = new File([geotiffarray], 'image.tif', { type: 'image/tif' });

                           // cmpDebugLog('File:', file);	
													
var fileurl =window.URL.createObjectURL(file);




	// Create a download link
	// Create a Blob from the binary data
const blob = new Blob([geotiffarray], { type: 'image.tif' });

const downloadLink = document.createElement('a');
downloadLink.href = window.URL.createObjectURL(blob);
downloadLink.download = 'output.tif'; // Set the desired file name
downloadLink.click(); // Simulate a click to trigger the download
	
							
            var gdal = await cmpCreateGdalProxy();
			
			
			    var result = await gdal.open(file);
                //cmpDebugLog("result", result);
                var tifDataset = result.datasets[0];

                var tifDatasetInfo = await gdal.getInfo(tifDataset); // Raster
                //cmpDebugLog(" Gdal tifDatasetInfo",tifDatasetInfo); 
			
			    /* ======== Raster translate (tif -> png) ======== */
                var gdalwarpoptions = [ // https://gdal.org/programs/gdal_translate.html#description
                    '-of', 'GTiff', //     //'-of', 'PNG',     
                    '-t_srs', 'EPSG:3857'
                ];



                var gdalwarpoutput = await gdal.gdalwarp(tifDataset, gdalwarpoptions)
                //cmpDebugLog("Gdal output",gdalwarpoutput); 

                var bytes = await gdal.getFileBytes(gdalwarpoutput);
                //cmpDebugLog("Gdal bytes",bytes); 

                var newgdalbuffer = URL.createObjectURL(new Blob([bytes], {
                    type: "image/tif"
                }))


                ////////////////////////////////// 
                /* ======== Raster translate (tif -> png) ======== */
                var gdalwarpoptionspng = [ // https://gdal.org/programs/gdal_translate.html#description
                    //'-of', 'PNG',
                    '-t_srs', 'EPSG:4326'
                ];

                var gdalwarpoutputpng = await gdal.gdalwarp(tifDataset, gdalwarpoptionspng)
                var bytespng = await gdal.getFileBytes(gdalwarpoutputpng);
                newgdalbufferpng = URL.createObjectURL(new Blob([bytespng], {
                    type: "image/PNG"
                }))
                ////////////////////////////////////////


               
                var a = document.createElement('a')
                a.href = URL.createObjectURL(new Blob([ bytes ],{ type: "image/tif"   }))//"image/png"
                a.download = "aSDASD"
                a.click()
               

}







function distortimage(file) {

    var kolos = URL.createObjectURL(file);
    img = L.distortableImageOverlay(kolos, {
        actions: [L.GeolocateAction,L.DistortAction, L.OpacityAction, L.DragAction, L.ScaleAction, L.FreeRotateAction, L.DeleteAction, L.ExportAction],
        //fullResolutionSrc: kolos,
        mode: 'drag',
        selected: true,
		pane: "georeference_pane"
    }).addTo(map);


    cmpDebugLog("distortableImageOverlay", img)


}


