var socket;
var notificationcoordinatesarray = [];
var socketnotification;
var cmpSocketIoScriptPromise = null;
var cmpSocketNotificationBound = false;
var cmpSocketShareState = {
    markers: [],
    currentUserLocation: [],
    currentUserName: "",
    currentUserCoordinatesElement: document.getElementById("livefeedcoordinates"),
    currentUserConnectedElement: document.getElementById("onlinefeedusers"),
    watchId: null,
    formBound: false,
    audio: null,
    isStarting: false
};

function cmpEnsureSocketIoLoaded() {
    if (typeof io !== "undefined") {
        return Promise.resolve();
    }

    if (cmpSocketIoScriptPromise) {
        return cmpSocketIoScriptPromise;
    }

    cmpSocketIoScriptPromise = cmpEnsureLazyScriptLoaded("./js/socket.io-2.0.0.js").catch(function(error) {
        cmpSocketIoScriptPromise = null;
        throw error;
    });

    return cmpSocketIoScriptPromise;
}

function cmpCreateSocketClient() {
    if (location.hostname === "localhost" || location.hostname === "127.0.0.1") {
        return io.connect("http://127.0.0.1:3000", {
            transports: ["polling"]
        });
    }

    return io.connect({
        transports: ["websocket", "polling"]
    });
}

function cmpRequestNotificationPermissions() {
    var BrowserNotification = window.Notification || window.mozNotification || window.webkitNotification;

    if (!BrowserNotification) {
        return null;
    }

    if (typeof BrowserNotification.requestPermission === "function" && BrowserNotification.permission !== "denied") {
        BrowserNotification.requestPermission(function() {});
    }

    return BrowserNotification;
}

function showDesktopNotification(message, body, icon, sound, coordinates, pagehash, timeout) {
    var BrowserNotification = cmpRequestNotificationPermissions();

    if (!BrowserNotification) {
        return false;
    }

    if (!timeout) {
        timeout = 990000000000;
    }

    var instance = new BrowserNotification(message, {
        body: body,
        icon: icon,
        sound: sound,
        coordinates: coordinates,
        pagehash: pagehash
    });

    instance.onclick = function() {
        if (notificationcoordinatesarray.length === 0) {
            cmpDebugLog("without coordinates");
            return;
        }

        cmpDebugLog("notification has coordinates");
        cmpDebugLog(notificationcoordinatesarray[0]);
        map.setView(notificationcoordinatesarray[0], 20);
        notificationcoordinatesarray = [];
    };

    setTimeout(instance.close.bind(instance), timeout);
    return false;
}

function cmpBindNotificationSocket() {
    if (!socketnotification || cmpSocketNotificationBound) {
        return;
    }

    socketnotification.on("show_notification", function(data) {
        showDesktopNotification(data.title, data.message, data.icon, data.coordinates, data.pagehash);
    });

    cmpSocketNotificationBound = true;
}

function cmpEnsureNotificationSocketInitialized() {
    return cmpEnsureSocketIoLoaded().then(function() {
        if (!socketnotification) {
            socketnotification = cmpCreateSocketClient();
        }

        cmpBindNotificationSocket();
        return socketnotification;
    });
}

function sendNodeNotification(title, message, icon, coordinates, pagehash) {
    return cmpEnsureNotificationSocketInitialized().then(function(notificationSocket) {
        notificationSocket.emit("new_notification", {
            message: message,
            title: title,
            icon: icon,
            coordinates: coordinates,
            pagehash: pagehash
        });

        return notificationSocket;
    }).catch(function(error) {
        console.error("Realtime notification emit failed:", error);
        throw error;
    });
}

function cmpClearSocketMarkers() {
    if (!cmpSocketShareState.markers.length) {
        return;
    }

    cmpSocketShareState.markers.forEach(function(item) {
        map.removeLayer(item);
    });

    cmpSocketShareState.markers = [];
}

function cmpUpdateMarkersAndCoordinatesAndConnectedUsers(markersFromBackend) {
    cmpDebugLog("function updateMarkersAndCoordinatesAndConnectedUsers");

    cmpClearSocketMarkers();

    var livepulse = L.icon.pulse({
        iconSize: [15, 15],
        color: "yellow",
        fillColor: "blue",
        heartbeat: 1.2,
        fillOpacity: 0.7
    });

    markersFromBackend.forEach(function(item) {
        cmpSocketShareState.markers.push(
            L.marker(item.coordinates, {
                icon: livepulse
            }).addTo(map).bindPopup(item.username)
        );
    });

    if (cmpSocketShareState.currentUserConnectedElement) {
        cmpSocketShareState.currentUserConnectedElement.textContent = markersFromBackend.length;
    }

    if (cmpSocketShareState.currentUserCoordinatesElement && cmpSocketShareState.currentUserLocation.length === 2) {
        cmpSocketShareState.currentUserCoordinatesElement.textContent =
            "User:" + cmpSocketShareState.currentUserName +
            ", Lat:" + cmpSocketShareState.currentUserLocation[0] +
            ", lng:" + cmpSocketShareState.currentUserLocation[1];
    }
}

function cmpHandleSocketShareDisconnect() {
    if (cmpSocketShareState.watchId !== null && navigator.geolocation && typeof navigator.geolocation.clearWatch === "function") {
        navigator.geolocation.clearWatch(cmpSocketShareState.watchId);
        cmpSocketShareState.watchId = null;
    }

    cmpClearSocketMarkers();

    if (cmpSocketShareState.currentUserCoordinatesElement) {
        cmpSocketShareState.currentUserCoordinatesElement.textContent = "";
    }

    if (cmpSocketShareState.currentUserConnectedElement) {
        cmpSocketShareState.currentUserConnectedElement.textContent = "";
    }

    $("#my-form").hide();
    $("#messages").hide();
    $("#sharelocation").show();

    var button = document.getElementById("sharelocation");
    if (button) {
        button.disabled = false;
    }

    cmpSocketShareState.currentUserLocation = [];
    cmpSocketShareState.currentUserName = "";
    cmpSocketShareState.isStarting = false;
    socket = null;
}

function cmpBindSocketShareForm() {
    if (cmpSocketShareState.formBound) {
        return;
    }

    var form = document.getElementById("my-form");
    if (!form) {
        return;
    }

    form.addEventListener("submit", function(e) {
        e.preventDefault();

        if (!socket || !socket.connected) {
            return;
        }

        var input = document.getElementById("message");
        if (!input) {
            return;
        }

        L.DomEvent.disableClickPropagation(input);

        var date = new Date();
        var timestamp = date.getHours() + ":" + date.getMinutes() + ":" + date.getSeconds();

        socket.send("☻-" + cmpSocketShareState.currentUserName + ": " + input.value + "      " + timestamp);
    });

    cmpSocketShareState.formBound = true;
}

function cmpBindSocketShareSocketEvents() {
    if (!socket) {
        return;
    }

    if (!socket.__cmpShareMessageBound) {
        if (!cmpSocketShareState.audio) {
            cmpSocketShareState.audio = document.createElement("audio");
            cmpSocketShareState.audio.setAttribute("src", "./sound/beep-08b.mp3");
        }

        socket.on("message", function(message) {
            var messageNode = document.createTextNode(message);
            var messageElement = document.createElement("p");
            messageElement.appendChild(messageNode);
            document.getElementById("messages").appendChild(messageElement);
            cmpSocketShareState.audio.play();
            document.getElementById("message").value = "";
        });

        socket.__cmpShareMessageBound = true;
    }

    if (!socket.__cmpShareMarkersBound) {
        socket.on("update-markers-on-frontend", function(data) {
            cmpUpdateMarkersAndCoordinatesAndConnectedUsers(data);
        });

        socket.__cmpShareMarkersBound = true;
    }

    if (!socket.__cmpShareDisconnectBound) {
        socket.on("disconnect", function() {
            cmpHandleSocketShareDisconnect();
        });

        socket.__cmpShareDisconnectBound = true;
    }
}

function cmpEmitCurrentSocketLocation() {
    if (!socket || !socket.connected || cmpSocketShareState.currentUserLocation.length !== 2) {
        return;
    }

    socket.emit("update-marker", {
        username: cmpSocketShareState.currentUserName,
        coordinates: cmpSocketShareState.currentUserLocation
    });
}

function cmpStartSocketLocationWatch() {
    if (cmpSocketShareState.watchId !== null || !navigator.geolocation) {
        return;
    }

    cmpSocketShareState.watchId = navigator.geolocation.watchPosition(function(position) {
        cmpSocketShareState.currentUserLocation = [position.coords.latitude, position.coords.longitude];
        notificationcoordinatesarray = [cmpSocketShareState.currentUserLocation];
        cmpDebugLog("currentUserLocation", cmpSocketShareState.currentUserLocation);
        cmpEmitCurrentSocketLocation();
    }, function(error) {
        console.error("Realtime location watch failed:", error);
    }, {
        enableHighAccuracy: true
    });
}

function cmpSetInitialSocketAndCoordinates(position) {
    cmpSocketShareState.currentUserLocation = [position.coords.latitude, position.coords.longitude];
    notificationcoordinatesarray = [cmpSocketShareState.currentUserLocation];

    map.setView(cmpSocketShareState.currentUserLocation, 19);
    cmpDebugLog("currentUserLocation after assignment", cmpSocketShareState.currentUserLocation);

    cmpStartSocketLocationWatch();
    cmpEmitCurrentSocketLocation();

    notification.clear();
    notification.info("Info", "Real time Location! User " + user.username + " has shared their real time location");

    sendNodeNotification(
        "Real time Location!",
        "User " + user.username + " has shared their real time location",
        "./images/swipe.png",
        notificationcoordinatesarray,
        ""
    ).catch(function() {});
}

function cmpStartRealtimeLocationShare() {
    cmpBindSocketShareForm();
    cmpBindSocketShareSocketEvents();

    if (!navigator.geolocation) {
        alert("Geolocation tracking is not available in your browser.");
        cmpHandleSocketShareDisconnect();
        return;
    }

    navigator.geolocation.getCurrentPosition(
        cmpSetInitialSocketAndCoordinates,
        function() {
            alert("Failed to get current position");
            cmpHandleSocketShareDisconnect();
        }, {
            enableHighAccuracy: true
        }
    );

    cmpDebugLog("function getit");
}

function cmpStartSocketShareSession() {
    if (socket && socket.connected) {
        return Promise.resolve(socket);
    }

    return cmpEnsureSocketIoLoaded().then(function() {
        socket = cmpCreateSocketClient();
        cmpBindSocketShareSocketEvents();

        if (!socket.__cmpShareConnectBound) {
            socket.on("connect", function() {
                var button = document.getElementById("sharelocation");
                if (button) {
                    button.disabled = true;
                }

                cmpSocketShareState.isStarting = false;
                cmpDebugLog("socket.connected");
                $("#my-form").show();
                $("#messages").show();
                $("#sharelocation").hide();

                cmpSocketShareState.currentUserName = user.username + " " + Math.floor(Math.random() * 100);
                cmpStartRealtimeLocationShare();
            });

            socket.__cmpShareConnectBound = true;
        }

        return socket;
    });
}

var shareLocationButton = document.getElementById("sharelocation");
if (shareLocationButton) {
    shareLocationButton.addEventListener("click", function(e) {
        e.preventDefault();

        if (cmpSocketShareState.isStarting || (socket && socket.connected)) {
            return;
        }

        cmpSocketShareState.isStarting = true;
        cmpDebugLog("socket.io is pressed");

        cmpStartSocketShareSession().catch(function(error) {
            cmpSocketShareState.isStarting = false;
            console.error("Realtime socket startup failed:", error);
            swal("Error", "There was a problem starting real time sharing.", "error");
        });
    });
}


