var cmpPathScriptPromise = null;
var cmpLazyScriptPromises = {};
function cmpResolveFrontendAssetUrl(relativePath) {
    return new URL(relativePath, window.location.href).href;
}

var cmpOptionalOfflineWarmUrls = [
    "./js/socket.io-2.0.0.js",
    "./js/esri/esri-leaflet-geocoder@2.2.14.js",
    "./js/shpwrite.js",
    "./js/osmtogeojson.js",
    "./data/stories/stories.geojson?updated=23032026",
    "./data/reports/reports11.geojson?updated=23032026",
    "./data/identified/identified2.geojson",
    "./data/site_profile.geojson",
    "./data/analysisbasket/analysisbasket.geojson",
    "./data/documents/points192.geojson",
    "./data/documents/tkc_documents_index2.geojson",
    "./data/documents/gkc_documents_index2.geojson",
    "./data/info/nicosia_27_april.geojson",
    "./data/coverage/tile_index.geojson?updated=23032026",
    "./data/coverage/tile_indexpoints.geojson?updated=23032026"
];
var cmpOptionalOfflineWarmRequested = false;

var cmpGdalConfig = {
    path: cmpResolveFrontendAssetUrl("./js/gdal/"),
    useWorker: false
};

function cmpCanWarmOptionalOfflineAssets() {
    if (!("serviceWorker" in navigator) || !isOnline()) {
        return false;
    }

    if (location.hostname === "localhost" || location.hostname === "127.0.0.1") {
        return false;
    }

    var connection = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
    if (connection && connection.saveData) {
        return false;
    }

    return true;
}

function cmpWarmOptionalOfflineAssets() {
    if (cmpOptionalOfflineWarmRequested || !cmpCanWarmOptionalOfflineAssets()) {
        return Promise.resolve(false);
    }

    cmpOptionalOfflineWarmRequested = true;

    return navigator.serviceWorker.getRegistration("./").then(function(registration) {
        var worker = registration && (registration.active || registration.waiting || registration.installing);

        if (!worker) {
            cmpOptionalOfflineWarmRequested = false;
            return false;
        }

        worker.postMessage({
            type: "cmp:warm-optional-assets",
            urls: cmpOptionalOfflineWarmUrls
        });

        return true;
    }).catch(function(error) {
        cmpOptionalOfflineWarmRequested = false;
        cmpDebugLog("Optional offline warm-up skipped", error);
        return false;
    });
}

function cmpScheduleOptionalOfflineWarmup() {
    cmpScheduleIdleTask(function() {
        cmpWarmOptionalOfflineAssets();
    }, 3500);
}

function cmpShowDesktopAnalysisButtons() {
    if (L.Browser.mobile) {
        return;
    }

    $("#nearestfunction").show();
    $("#voronoifunction").show();
    $("#prepareheatmapdata").show();
    $("#pathnetworkfunction").show();
}

function cmpEnsurePathToolsLoaded() {
    if (typeof rooter !== "undefined" && typeof PathFinder !== "undefined" && typeof L !== "undefined" && typeof L.Routing !== "undefined") {
        return $.Deferred().resolve().promise();
    }

    if (cmpPathScriptPromise) {
        return cmpPathScriptPromise;
    }

    cmpPathScriptPromise = $.getScript("./js/path.js").fail(function() {
        cmpPathScriptPromise = null;
    });

    return cmpPathScriptPromise;
}

function cmpEnsureLazyScriptLoaded(url) {
    if (cmpLazyScriptPromises[url]) {
        return cmpLazyScriptPromises[url];
    }

    cmpLazyScriptPromises[url] = new Promise(function(resolve, reject) {
        $.getScript(url).done(function() {
            resolve();
        }).fail(function() {
            delete cmpLazyScriptPromises[url];
            reject(new Error("Failed to load " + url));
        });
    });

    return cmpLazyScriptPromises[url];
}

function cmpEnsureLazyScriptsLoaded(urls) {
    return Promise.all(urls.map(cmpEnsureLazyScriptLoaded));
}

function cmpAreMbtilesToolsReady() {
    return typeof initSqlJs !== "undefined" &&
        typeof L !== "undefined" &&
        L.tileLayer &&
        typeof L.tileLayer.mbTiles === "function";
}

function cmpIsMbtilesLayer(layer) {
    return typeof L !== "undefined" &&
        L.TileLayer &&
        typeof L.TileLayer.MBTiles !== "undefined" &&
        layer instanceof L.TileLayer.MBTiles;
}

function cmpEnsureMbtilesToolsLoaded() {
    if (cmpAreMbtilesToolsReady()) {
        return Promise.resolve();
    }

    return cmpEnsureLazyScriptsLoaded([
        "./js/sqljs-1.3.0/sql-wasm.js",
        "./js/Leaflet.TileLayer.MBTiles.js"
    ]);
}

function cmpAreRasterToolsReady() {
    return typeof proj4 !== "undefined" &&
        typeof parseGeoraster !== "undefined" &&
        typeof GeoRasterLayer !== "undefined" &&
        typeof initGdalJs !== "undefined" &&
        typeof geoblaze !== "undefined";
}

function cmpIsGeoRasterLayer(layer) {
    return typeof GeoRasterLayer !== "undefined" &&
        layer instanceof GeoRasterLayer;
}

function cmpEnsureRasterToolsLoaded() {
    if (cmpAreRasterToolsReady()) {
        return Promise.resolve();
    }

    return cmpEnsureLazyScriptsLoaded([
        "./js/proj4-src.js",
        "./js/georaster.browser.bundle.min.js",
        "./js/georaster-layer-for-leaflet.min.js",
        "./js/geotiff@2.0.5.js",
        "./js/geoblaze@280.js",
        "./js/gdal/gdal3.js"
    ]);
}

function cmpCreateGdalProxy() {
    return cmpEnsureRasterToolsLoaded().then(function() {
        return initGdalJs(cmpGdalConfig);
    }).then(function(gdalClient) {
        return new Proxy(gdalClient, {
            get: function(target, prop, receiver) {
                if (prop === "next" || prop === "then" || prop === "return") {
                    return;
                }

                return Reflect.get(target, prop, receiver);
            }
        });
    });
}



