function cmpHasExplicitMapHash() {
    var hashValue = window.location.hash || "";
    return /^#\d+(?:\.\d+)?\/-?\d+(?:\.\d+)?\/-?\d+(?:\.\d+)?(?:\/.*)?$/.test(hashValue);
}


