    //			{ 

    if (
        excesearch &&
        excesearch._input &&
        excesearch._input.value.length >= excesearch.options.minLength &&
        !cmpArePrimarySearchLayersLoaded()
    ) {
        var pendingPrimarySearchTerm = excesearch._input.value;

        cmpEnsurePrimarySearchLayersLoaded({
            useSpinner: true
        }).then(function() {
            if (
                excesearch &&
                excesearch._input &&
                excesearch._input.value === pendingPrimarySearchTerm &&
                pendingPrimarySearchTerm.length >= excesearch.options.minLength
            ) {
                excesearch.searchText(pendingPrimarySearchTerm);
            }
        }).catch(function(error) {
            console.error("Primary search GeoJSON load failed:", error);
            swal("Error", "Search data could not be loaded right now.", "error");
        });

        return;
    }

    textarray = [];
