// === Share-with UI (robust with spaced usernames) ===
// expects: #selectuser (wrapper), #selectid (container), #sharedtoid (hidden)

var selectWrapper = document.getElementById("selectuser");
var sharingto = null;

// ---- helpers ----
function normUname(s) {
  const t = String(s || "").trim().replace(/\s+/g, " "); // trims & collapses
  return { raw: t, key: t.toLowerCase() };
}



function domSafeId(s) {
  return "userid-" + String(s).normalize("NFKD").replace(/[^\w-]+/g, "_");
}

function ensureSelectContainer() {
  var c = document.getElementById("selectid");
  if (!c) { c = document.createElement("div"); c.id = "selectid"; selectWrapper.appendChild(c); }
  return c;
}






function buildUserRow(entry) {
  var row = document.createElement("div");
  row.className = "share-row";
  row.style.cssText = "display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid #eee;";

  var el = document.createElement("input");
  el.type = "checkbox";
  el.className = "form-check-input";
  el.name  = "share-user";
  el.id    = "userid-" + entry.usernameRaw.normalize("NFKD").replace(/[^\w-]+/g, "_");

  // ✅ authoritative value lives here (spaces preserved)
  el.setAttribute("data-username", entry.usernameRaw);

  // Optional: leave .value for display/compat, but we will NOT rely on it
  el.value = entry.usernameRaw;

  var label = document.createElement("label");
  label.className = "form-check-label";
  label.setAttribute("for", el.id);
  label.title = entry.usernameRaw;
  label.textContent = entry.full ? (entry.full + " (" + entry.usernameRaw + ")")
                                 : entry.usernameRaw;

  row.appendChild(el);
  row.appendChild(label);
  return row;
}


function renderUserList(entries) {
  var container = ensureSelectContainer();
  container.innerHTML = "";

  var frag = document.createDocumentFragment();
  for (var i = 0; i < entries.length; i++) {
    frag.appendChild(buildUserRow(entries[i]));
  }
  container.appendChild(frag);


// Pre-check if we already have shared usernames (comma-separated)
var pre = (document.getElementById("sharedtoid").value || "")
  .split(",")
  .map(function (s) { return s.trim(); })
  .filter(Boolean);

if (pre.length) {
  pre.forEach(function (unameRaw) {
    var el = container.querySelector('input.form-check-input[data-username="' + unameRaw.replace(/"/g, '\\"') + '"]');
    if (el) el.checked = true;
  });
}



$("#selectid").off("click.storeUsers").on("click.storeUsers", function () {
  try {
    var selectedUsernames = $("#selectid input:checkbox:checked").map(function () {
      var v = (this.value || "").trim();
      var m = v.match(/(\S+)\s*$/);        // ← takes only the last chunk
      return m ? m[1] : v;
    }).get();

    $("#sharedtoid").val(selectedUsernames);
  } catch (error) {
    swal(error);
  }
});


}


function loadAndRenderUsers() {
  if (typeof showSpinner === "function") showSpinner();

  $.ajax({
    url: "../php/all_users.php",
    type: "POST",
    success: function (response) {
      if (typeof hideSpinner === "function") hideSpinner();

      if (response.substring(0, 5) === "ERROR") { swal("error " + response); return; }

      try { sharingto = JSON.parse(response); }
      catch (e) { console.error("Failed to parse all_users.php response", e, response); swal("Failed to parse users."); return; }
      cmpDebugLog("sharingto", sharingto);

      var raw = [];
      if (Array.isArray(sharingto)) raw = sharingto; else {
        (function collect(obj) {
          if (!obj) return;
          if (Array.isArray(obj)) return obj.forEach(collect);
          if (typeof obj === "object") {
            if (obj.username) raw.push(obj);
            Object.keys(obj).forEach(function (k) { collect(obj[k]); });
          }
        })(sharingto);
      }

      var currentUser = (window.user && user.username) ? normUname(user.username).key : "";
      var blacklist = new Set([currentUser, "presentation", "a.avgou", "usergeneric","ahmet.anilir","d.akbayram","g.philippou","seden.uyaroglu"].map(u => normUname(u).key));

      var byKey = new Map();
      for (var i = 0; i < raw.length; i++) {
        var u = raw[i];
        if (!u || !u.username) continue;
        if (Number(u.active) !== 1) continue;

        var uNorm = normUname(u.username);
        if (!uNorm.raw || blacklist.has(uNorm.key)) continue;

        var full = (String(u.firstname || "").trim() + " " + String(u.lastname || "").trim()).trim();

        if (!byKey.has(uNorm.key)) {
          byKey.set(uNorm.key, { usernameRaw: uNorm.raw, usernameKey: uNorm.key, full: full });
        }
      }

      var coll = new Intl.Collator(undefined, { sensitivity: "base", numeric: true });
      var entries = Array.from(byKey.values()).sort(function (a, b) {
        var af = a.full || a.usernameRaw;
        var bf = b.full || b.usernameRaw;
        var cmp = coll.compare(af, bf);
        return cmp !== 0 ? cmp : coll.compare(a.usernameRaw, b.usernameRaw);
      });

      renderUserList(entries);
    },
    error: function (xhr, status, error) {
      if (typeof hideSpinner === "function") hideSpinner();
      cmpDebugLog("ERROR:", error);
      swal("Could not fetch users.");
    }
  });
}

$(".mdl-card--sharewith").off("change.sharewith").on("change.sharewith", function () {
  var isOn = $(this).hasClass("is-checked");

  if (!isOn) {
    try { $(".mdl-card--sharewith")[0].MaterialSwitch.off(); } catch (_) {}
    var c = ensureSelectContainer();
    c.innerHTML = "";
    $("#selectuser").hide();
    $("#selectid").hide();
    $("#sharedtoid").val("");
    return;
  }

  $("#selectuser").show();
  $("#selectid").show();
  loadAndRenderUsers();
});









