function showrangeVal(newVal) {

    if (newVal === "0") {
        document.getElementById('customRange3label').innerHTML = "Ungraded Info";
        $('#numbergrading').val(newVal);
        $('#customRange3').val(newVal);
    } else if (newVal === "1") {
        document.getElementById('customRange3label').innerHTML = "Raw Info";
        $('#numbergrading').val(newVal);
        $('#customRange3').val(newVal);

    } else if (newVal === "2") {
        document.getElementById('customRange3label').innerHTML = "Processed Info";
        $('#numbergrading').val(newVal);
        $('#customRange3').val(newVal);

    } else if (newVal === "3") {
        document.getElementById('customRange3label').innerHTML = "Pending for actions";
        $('#numbergrading').val(newVal);
        $('#customRange3').val(newVal);
    } else if (newVal === "4") {
        document.getElementById('customRange3label').innerHTML = "Ready for excavation";
        $('#numbergrading').val(newVal);
        $('#customRange3').val(newVal);

    } else if (newVal === "5") {
        document.getElementById('customRange3label').innerHTML = "Excavated";
        $('#numbergrading').val(newVal);
        $('#customRange3').val(newVal);
    }



}


