function initscenariostoryMap(data) {

    // Sort the features by scenarioid before adding them to the map
    data.features.sort(function(a, b) {
        return parseInt(a.properties.properties.scenarioid) - parseInt(b.properties.properties.scenarioid);
    });

    $('#narration').empty();
    var storycontents = $('<div></div>', {
        id: 'contents'
    });

    $('#narration').append(storycontents);
    $('#contents').empty();

    document.getElementById("narration").style.display = "block";
    document.getElementById("title").style.display = "block";

    scenariostorygeojson.clearLayers();
    scenariostorygeojson.addData(data); // Now the data is sorted
    scenariostorygeojson.addTo(map);
    $('#contents').append("<div class='space-at-the-bottom'><a href='#space-at-the-top'><i class='fa fa-chevron-up'></i><p><small>Top</small></a></div>");

    cmpDebugLog("data", data);

    $("#editstory").click(function() {
       // alert("edit story clicked");
       // $('#narration').empty();
    });

    $("#deletestory").click(function() {
        cmpDebugLog("scenariostorygeojson", scenariostorygeojson);

        var id = $(".uniqueid").html();
        deletescenario("scenariotable", id, function() {
            if (lyrscenario) {
                map.removeLayer(lyrscenario);
                refreshscenario();
                scenariodrawnItems.clearLayers();
                scenariostorygeojson.clearLayers();
                storypathLineGroup.clearLayers();
                closestoryfunction();
            }
        });    
    });
}


		


function deletescenario(tbl, id, callback) {
	
	
	  if (isOnline()){
		  
    $.ajax({
        url:'../php/delete_scenario.php',
        data:{tbl:tbl, id:id},
        type:'POST',
        success: function(response) {
            if (response.substr(0,5)=="ERROR") {
                swal("error"+response);
            } else {
                //swal("Record "+id+" deleted from "+tbl);
				swal("Record deleted");
				//cmpDebugLog(response);
				


   

                callback();

            }
        }, 
        error: function(xhr, status, error) {
            swal("AJAX Error: "+error);
        }
    });
	  }
	  else{
		  arSyncQue.push({
		  type:'DELETE',
		  timestamp: returnCurrentTimestamp(),
		  result: "NONE",
		  jsn : {tbl:tbl, id:id}
		  })
		  
updateSyncCount();
	  }
	    
}







var scenariostorygeojson = L.geoJson(null, {
    // pane: 'drawnPane',
    pane: 'georeference_pane',
    onEachFeature: function(feature, layer) {

        (function(layer, properties) {
			
			
			
            var numericMarker = L.ExtraMarkers.icon({ //
                icon: 'fa-number', //////
                number: feature.properties.properties.scenarioid, //////////////
                markerColor: 'blue' ///////////
            }); //////////////
            layer.setIcon(numericMarker); ////////

            // This creates the contents of each chapter from the GeoJSON data. Unwanted items can be removed, and new ones can be added
            var chapter = $('<p></p>', {
                text: feature.properties.properties.scenariotitle,
                class: 'chapter-header'
            });


        var slidenumber = $('<p></p>', {
                text: "Slide: "+feature.properties.properties.scenarioid,
                class: 'scenario-slidenumber'
            });

     var uniqueid = $('<p></p>', {
                text: feature.properties.properties.scenariouniqueidentif,
                class: 'uniqueid'
            });
	
			
            var image = $('<img>', {
                //src: feature.properties.properties.scenarioimage,
                src: "data/stories/elladites/images/cmp.jpg"
            });

            var source = $('<a>', {
                // text: feature.properties.properties['source-credit'],
                // href: feature.properties.properties['source-link'],
                target: "_blank",
                class: 'source'
            });

            var description = $('<div></div>', {
                text: feature.properties.properties.scenariodescr,
                class: 'description'
            });

            var additionalnotes = $('<p></p>', {
                text: feature.properties['additionalnotes'],
                class: 'description'
            });

            var container = $('<div></div>', {
                id: 'container' + feature.properties.properties.scenarioid,
                class: 'image-container'
            });

            var imgHolder = $('<div></div', {
                class: 'img-holder',
                // href: feature.properties.properties.scenarioimage,
                href: "data/stories/elladites/images/cmp.jpg"
            });

            imgHolder.venobox({
                framewidth: "90%",
                // default: ''
                frameheight: "90%",
                border: "10px",
                // default: '0'
                closeBackground: "#2572d2",
                bgcolor: "#b9e3fb",
                // default: '#fff'
                titleattr: "data-title",
                // default: 'title'
                overlayClose: true,
                numeratio: true,
                // default: false
                infinigall: true // default: false
                // share      : [ 'download'] // default: []
            });

            imgHolder.append(image);

            container.append(slidenumber).append(chapter).append(uniqueid).append(imgHolder).append(source).append(description).append(additionalnotes);
			
			
			
            $('#contents').append(container);

          

            var i;
            var areaTop = -100;
            var areaBottom = 0;

            // Calculating total height of blocks above active
            for (i = 1; i < feature.properties.properties.scenarioid; i++) {
                areaTop += $('div#container' + i).height() + imageContainerMargin;
            }



            areaBottom = areaTop + $('div#container' + feature.properties.properties.scenarioid).height();




            $('div#contents').scroll(function() {
                if ($(this).scrollTop() >= areaTop && $(this).scrollTop() < areaBottom) {
                    if (feature.properties.properties.scenarioid != currentBox) {
                        currentBox = feature.properties.properties.scenarioid;

                        $('.image-container').removeClass("inFocus").addClass("outFocus");
                        $('div#container' + feature.properties.properties.scenarioid).addClass("inFocus").removeClass("outFocus");

                        map.invalidateSize();

                        // This removes all layers besides the base layer
                        map.eachLayer(function(layer) {
                            /*
                            if (layer != googleSat) {
                                map.removeLayer(layer);
                                drawnItems.addTo(map);
                                sat1963b.addTo(map);
                                googleSat.addTo(map);
                                sat1963b.bringToBack();
                            }
							*/
                        });

                        scenariodata = storydataaray;
                        var scenariostorycoord = null;
                        scenariostorycoord = feature.properties.geometry['coordinates'];
                        // var scenariozoom = feature.properties.properties['zoom'];
                        // var scenariozoom = '17'
                        var scenariozoom;
                        if (feature.properties.properties['zoom']) {
                            scenariozoom = feature.properties.properties['zoom'];
                        } else {
                            //  scenariozoom = '15'
                           scenariozoom = map.getZoom();
                            //cmpDebugLog("map.getzoom()", scenariozoom);

                        }
                        refreshscenarioLayer(scenariodata, map, scenariostorycoord, scenariozoom);



                        // })

                    }
                }
            })


            layer.on('click', function() {
                cmpDebugLog("fuck")
                scenarioflagFornumberedPoints = false;
                
				
				$("div#contents").animate({
                    scrollTop: areaTop + "px"
                }, 1000);
				
				
                map.invalidateSize();
            });


        })(layer, feature.properties);

    }
});






