function tileToLatLngBounds(x, y, z) {
    const tileSize = 256;  // Tile size in pixels

    function tile2lon(x, z) {
        return (x / Math.pow(2, z)) * 360 - 180;
    }

    function tile2lat(y, z) {
        const n = Math.PI - (2 * Math.PI * y) / Math.pow(2, z);
        return (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
    }

    const northWest = {
        lat: tile2lat(y, z),
        lng: tile2lon(x, z)
    };
    const southEast = {
        lat: tile2lat(y + 1, z),
        lng: tile2lon(x + 1, z)
    };

    return { northWest, southEast };
}


// Function to convert a Blob URL to Base64 asynchronously
function getBase64FromBlobUrl(blobUrl) {
    return fetch(blobUrl)
        .then(response => response.blob())
        .then(blob => {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result); // base64 string
                reader.onerror = reject;
                reader.readAsDataURL(blob);
            });
        })
        .catch(error => {
            console.error('Error converting blob URL to base64:', error);
            return null; // Return null on error
        });
}


// Extract image data from L.ImageOverlay directly
function getBase64FromImageOverlay(overlay) {
    if (overlay instanceof L.ImageOverlay) {
        const imgElement = overlay._image;
        if (imgElement && imgElement instanceof HTMLImageElement) {
            const canvas = document.createElement('canvas');
            canvas.width = imgElement.naturalWidth;
            canvas.height = imgElement.naturalHeight;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(imgElement, 0, 0);
            return canvas.toDataURL(); // Return base64
        }
    }
    return null;
}

// Get the bounds of an ImageOverlay
function getImageOverlayBounds(overlay) {
    if (overlay instanceof L.ImageOverlay) {
        return overlay._bounds;
    }
    return null;
}




function getOverlayBoundsAsObject(overlay) {
    const bounds = getImageOverlayBounds(overlay);
    if (bounds) {
        const northWest = bounds.getNorthWest();
        const southEast = bounds.getSouthEast();

        const transformations = extractTransformations(overlay._image);

        const transformedBounds = applyTransformations({
            northWest: {
                lat: northWest.lat,
                lng: northWest.lng
            },
            southEast: {
                lat: southEast.lat,
                lng: southEast.lng
            }
        }, transformations);

        return {
            northWest: transformedBounds.northWest,
            southEast: transformedBounds.southEast
        };
    }
    return null;
}






// Function to handle both tiles and image overlays
function getVisibleLayers() {
    let tiles = [];
    let overlays = [];

    map.eachLayer(function (layer) {
        if (layer instanceof L.TileLayer || layer instanceof L.GridLayer) {
            Object.keys(layer._tiles).forEach(function (key) {
                let tile = layer._tiles[key];
                let tileCoords = tile.coords;
                const bounds = tileToLatLngBounds(tileCoords.x, tileCoords.y, tileCoords.z);

                if (tile.el.nodeName.toLowerCase() === 'canvas') {
                    let canvasImageData = tile.el.toDataURL();
                    tiles.push({
                        url: null,
                        z: tileCoords.z,
                        x: tileCoords.x,
                        y: tileCoords.y,
                        bounds: bounds,
                        canvasData: canvasImageData
                    });
                } else if (tile.el.nodeName.toLowerCase() === 'img') {
                    let tileUrl = tile.el.src;
                    if (tileUrl.startsWith('blob:')) {
                        // Convert blob URL to base64 and push to array
                        tiles.push(getBase64FromBlobUrl(tileUrl).then(base64Data => ({
                            url: null,
                            z: tileCoords.z,
                            x: tileCoords.x,
                            y: tileCoords.y,
                            bounds: bounds,
                            canvasData: base64Data // base64 of blob image
                        })));
                    } else {
                        tiles.push({
                            url: tileUrl,
                            z: tileCoords.z,
                            x: tileCoords.x,
                            y: tileCoords.y,
                            bounds: bounds
                        });
                    }
                }
            });
        } else if (layer instanceof L.ImageOverlay) {
            // Handle L.ImageOverlay layers
            let bounds = layer.getBounds();
            let base64Data = getBase64FromImageOverlay(layer); // Extract base64 directly
            if (base64Data) {
                overlays.push({
                    url: null,
                    z: null,  // Image overlays don’t have z, x, y
                    x: null,
                    y: null,
                    bounds: {
                        northWest: bounds.getNorthWest(),
                        southEast: bounds.getSouthEast()
                    },
                    canvasData: base64Data // base64 of the blob image
                });
            }
        }
    });

    return Promise.all(tiles).then(finalTiles => ({ tiles: finalTiles, overlays }));
}


function sendTilesToServer(tiles) {
    fetch('http://127.0.0.1:5000/upload_tiles', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ tiles: tiles })
    })
    .then(response => response.json())
    .then(data => {
        cmpDebugLog('Tiles uploaded successfully:', data);
    })
    .catch(error => {
        console.error('Error uploading tiles:', error);
    });
}




