    async function loadGeoTiff(filePath) {
    	 cmpDebugLog("filePath",filePath)
        // Load the GeoTIFF from the given file path
        const response = await fetch(filePath);
        const arrayBuffer = await response.arrayBuffer();
        //const tiff = await GeoTIFF.fromArrayBuffer(arrayBuffer, { littleEndian: true });
           var tiff = await GeoTIFF.fromUrl(filePath, {littleEndian: true});
    	   cmpDebugLog(tiff)
        // Perform necessary operations on the GeoTIFF
        const image = await tiff.getImage();
    	 cmpDebugLog("image",image)

    	const width = image.getWidth();
    const height = image.getHeight();
    const tileWidth = image.getTileWidth();
    const tileHeight = image.getTileHeight();
    		 cmpDebugLog("height",height)
    			 cmpDebugLog("width",width)
    			 	 cmpDebugLog("tileWidth",tileWidth)
    				 	 cmpDebugLog("tileHeight",tileHeight)
    			 
    			 
       // const [red, green, blue] =await image.readRasters();
    	
     //cmpDebugLog("[red, green, blue]",[red, green, blue])

        
        sendToPythonScript(new Blob([tiff], { type: "image/tiff" }))
    }

    function sendToPythonScript(arrayBuffer) {
      var blob = new Blob([arrayBuffer], { type: 'image/tiff' });
      cmpDebugLog("arrayBuffer",arrayBuffer);
      cmpDebugLog("blob",blob);
      var formData = new FormData();
      formData.append('tiff', blob, 'viewport.tif');
      $.ajax({
     url: 'http://localhost:5000/upload',
        type: 'POST',
        data: formData,
        processData: false,
        contentType: false,
        success: function(response) {
          cmpDebugLog(response);
        },
        error: function(xhr, status, error) {
          console.error(error);
        },
      });
	}
	





