// Function to fetch GetCapabilities
function getCapabilities(wmsUrl) {

	wmsUrl = document.getElementById('wmsUrl2').value;
  // Choose one of the URL possibilities
  const wmsGetCapabilitiesURL1 = wmsUrl + '&request=GetCapabilities&service=WMS';
  const wmsGetCapabilitiesURL2 = wmsUrl + '?service=WMS&REQUEST=GetCapabilities';
cmpDebugLog("wmsGetCapabilitiesURL1",wmsGetCapabilitiesURL1)
cmpDebugLog("wmsGetCapabilitiesURL2",wmsGetCapabilitiesURL2)

  // Try the first URL option
  fetch(wmsGetCapabilitiesURL1)
    .then((response) => {
      if (!response.ok) {
        throw new Error('Network response was not ok');
      }
      return response.text();
	  
    })
    .then((xmlResponse) => {
      // Parse the XML response and process it
      processGetCapabilities(xmlResponse);
    })
    .catch(() => {
      // If the first URL option fails, try the second URL option
      fetch(wmsGetCapabilitiesURL2)
        .then((response) => {
          if (!response.ok) {
            throw new Error('Network response was not ok');
          }
          return response.text();
        })
        .then((xmlResponse) => {
          // Parse the XML response and process it
          processGetCapabilities(xmlResponse);
        })
        .catch((error) => {
          console.error('Error:', error);
        });
    });
}


// Function to process GetCapabilities response
function processGetCapabilities(xmlResponse) {
  // Parse the XML response using a suitable XML parsing library
  // For this example, we'll use DOMParser
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlResponse, "text/xml");

  // Extract layer names from the parsed XML
  const layerNodes = xmlDoc.querySelectorAll('Layer[queryable="1"] > Name');
  const layertitles = xmlDoc.querySelectorAll('Layer[queryable="1"] > Title');
  const layerNames = Array.from(layerNodes).map((node) => node.textContent);

  // Log the extracted layer names and titles
  cmpDebugLog('Layer Names:', layerNames);
  layertitles.forEach((titleElement) => {
    const cdataContent = titleElement.textContent; // Get the text within the Title element
    cmpDebugLog('Title:', cdataContent);
  });

  // Display the extracted layer names and titles within an HTML element with the ID "wmslayers"
  const wmsLayersElement = document.getElementById('wmslayers');
  wmsLayersElement.innerHTML = '';

  // Append both layer names and titles
  for (let i = 0; i < Math.min(layerNames.length, layertitles.length); i++) {
    const layerElement = document.createElement('div');
    layerElement.textContent = `${layerNames[i]} - ${layertitles[i].textContent}`;
    layerElement.style.cursor = 'pointer';
    wmsLayersElement.appendChild(layerElement);
  }
  
  // Add a single event listener to the parent element "wmslayers"
  wmsLayersElement.addEventListener('click', (event) => {
    if (event.target && event.target.tagName === 'DIV') {
		 document.getElementById('hiddenwmsname').value = event.target.textContent;
      const layerName = event.target.textContent.split(' - ')[0];
      handleLayerNameClick(layerName);
    }
  });
}





