function getFeaturesInLayer(layer, bounds, visibleFeatures, featureLayers, parentLayerName) {
    if (layer instanceof L.LayerGroup) {
        layer.eachLayer(function(subLayer) {
            getFeaturesInLayer(subLayer, bounds, visibleFeatures, featureLayers, parentLayerName);
        });
    } else if (layer.feature && layer.feature.properties) {
        var layerBounds;

        if (layer instanceof L.Marker || layer instanceof L.CircleMarker) {
            layerBounds = layer.getLatLng();
            if (bounds.contains(layerBounds)) {
                var properties = layer.feature.properties;
                var featureName = properties.index || properties.gis_GIS_p_ || properties.name || properties.description || properties.id;
                
                if (properties.gis_GIS_p_) {
                    featureName = ' <span><b>Topographic features:</b> ' + properties.gis_GIS_p_ + '</span>';
                }

                if (!visibleFeatures.some(f => f.layer._leaflet_id === layer._leaflet_id)) {
                    visibleFeatures.push({ name: featureName, layer: layer });
                    featureLayers.push(layer);
                }
            }
        } else if (layer instanceof L.Polygon || layer instanceof L.Polyline) {
            layerBounds = layer.getBounds();
            if (layerBounds.isValid() && bounds.intersects(layerBounds)) {  // Check if bounds are valid
                var properties = layer.feature.properties;
                var featureName = properties.index || properties.gis_GIS_p1 || properties.gis_GIS_a1 || properties.gis_GIS_p_ || properties.gis_GIS_a_ || properties.name || properties.Name || properties.description || properties.id || properties.gis_GIS_l1 || properties.PARCEL_NBR;
                
                if (properties.PARCEL_NBR) {
                    featureName = ` <span><b>Parcel:</b> ${properties.PARCEL_NBR}</span>`;
                }
                
                if (properties.gis_GIS_p1 || properties.gis_GIS_a1 || properties.gis_GIS_p_ || properties.gis_GIS_a_ || properties.gis_GIS_l1) {
                    featureName = ' <span><b>Topographic features:</b> ' + (properties.gis_GIS_p1 || properties.gis_GIS_a1 || properties.gis_GIS_p_ || properties.gis_GIS_a_ || properties.gis_GIS_l1) + '</span>';
                }

                if (!visibleFeatures.some(f => f.layer._leaflet_id === layer._leaflet_id)) {
                    visibleFeatures.push({ name: featureName, layer: layer });
                    featureLayers.push(layer);
                }
            }
        }
    }
}



