// Function to get features in the current viewport
function getFeaturesInView() {
    var bounds = map.getBounds();
    var visibleFeatures = [];
    var featureLayers = [];

    // Iterate through all layers including clusters
    map.eachLayer(function(layer) {
        if (layer instanceof L.MarkerClusterGroup) {
            layer.eachLayer(function(clusteredLayer) {
                getFeaturesInLayer(clusteredLayer, bounds, visibleFeatures, featureLayers, "Clustered Feature");
            });
        } 
		
		else if (!(layer instanceof L.LayerGroup)) {
            getFeaturesInLayer(layer, bounds, visibleFeatures, featureLayers, "Unnamed Layer");
        }
		
		
		
		
		
    });

    updateFeatureList(visibleFeatures, featureLayers);
}



map.on("moveend", getFeaturesInView);




// Function to update the list of features
function updateFeatureList(features, layers) {
    var featureListDiv = document.getElementById('featureList');
    featureListDiv.innerHTML = "<ul>" + features.map((f, index) => 
        `<li data-index="${index}">${f.name}</li>`
    ).join('') + "</ul>";

    // Click event to navigate to features and log their properties
    var listItems = featureListDiv.querySelectorAll('li');
    listItems.forEach(function(item) {
        item.onclick = function() {
            var index = item.getAttribute('data-index');
            var layer = features[index].layer; // Retrieve the full layer object

            // Log all layer properties to the console
            cmpDebugLog("Layer Properties:", layer);
            if (layer.feature && layer.feature.properties) {
                cmpDebugLog("Feature Properties:", layer.feature.properties);
            }

            // Navigate to the feature's location on the map
            if (layer instanceof L.Marker || layer instanceof L.CircleMarker) {
                map.setView(layer.getLatLng(), 18);
            } else if (layer instanceof L.Polygon || layer instanceof L.Polyline) {
                map.fitBounds(layer.getBounds());
            }
        };
    });
}



// Function to check if an element is visible
function isElementVisible(elementId) {
    var element = document.getElementById(elementId);
    if (!element) return false;  // If the element doesn't exist, return false
    
    // Check if element is visible
    var style = window.getComputedStyle(element);
    return style.display !== 'none' && style.visibility !== 'hidden' && element.offsetHeight > 0 && element.offsetWidth > 0;
}




