// Make sure to pass `features` in `loadLayerProperties`
function loadLayerProperties(layer) {
	
	
	
    if (layer.includes('pinlayer')) {
        //let layerid= data.replace( /^\D+/g, '');
        let layerid = layer.replace(/(^.*\[|\].*$)/g, '');

        cmpDebugLog(layerid);
        //data = randomlayer.getLayer(layerid);
        layer = overlayLayers[layerid];
        layer = layer;
        

    } else {

         layer = window[layer];
       

    }
	
	
	
   // layer = window[layer];
    cmpDebugLog("Layer chosen:", layer);

    if (!layer) {
        console.warn("Layer not found:", layer);
        return;
    }

    activeLayer = layer;
    queryConditions = [];

    let features = [];
    Object.values(layer._layers).forEach(subLayer => {
        if (subLayer.feature) {
            features.push(subLayer.feature);
        }
    });

    if (features.length === 0) {
        console.warn("Selected layer has no features:", layer);
        alert("The selected layer has no data available for analysis.");
        return;
    }

    const uniqueValues = {};
    features.forEach(feature => {
        Object.keys(feature.properties).forEach(key => {
            if (!uniqueValues[key]) uniqueValues[key] = new Set();
            uniqueValues[key].add(feature.properties[key]);
        });
    });

    let queryBuilder = document.getElementById("queryBuilder");
    queryBuilder.innerHTML = "";

    addConditionRow(queryBuilder, uniqueValues, features);

    showQueryBuilderModal();
}





function addConditionRow(container, uniqueValues, features) {
    // Generate condition elements
    let properties = Object.keys(uniqueValues);
    let propSelect = createDropdown(properties, "Property");
    let operatorSelect = createDropdown(["=", ">", "<", ">=", "<="], "Operator");

    // Generate a unique ID for manual input
    let uniqueId = `manualInput_${container.childElementCount}`;
    let valueSelect = createDropdown(["No Value"], "Select value", true);
    let manualInput = document.createElement("input");
    manualInput.type = "text";
    manualInput.placeholder = "Enter value";
    manualInput.style.display = "block";
    manualInput.id = uniqueId;

    valueSelect.addEventListener("change", function () {
        manualInput.style.display = valueSelect.value === "Manual Entry" ? "block" : "none";
    });

    propSelect.addEventListener("change", function () {
        let selectedProp = propSelect.value;
        let valuesArray = selectedProp ? Array.from(uniqueValues[selectedProp]) : ["No Value"];
        valuesArray.unshift("Manual Entry");

        valueSelect.innerHTML = "";
        valuesArray.forEach(value => {
            let opt = document.createElement("option");
            opt.value = value;
            opt.text = value;
            valueSelect.appendChild(opt);
        });
    });

    // Add "+" button
    let addButton = document.createElement("button");
    addButton.textContent = "+";
    addButton.onclick = () => {
        addConditionRow(container, uniqueValues, features);
        updateConditionsArray(container); // Update queryConditions
        ensureExecuteButtonAtBottom(container, features);
    };

/*
    // Add "-" button
    let removeButton = document.createElement("button");
    removeButton.textContent = "-";
    removeButton.onclick = () => {
        container.removeChild(conditionContainer);
        updateConditionsArray(container); // Update queryConditions
        ensureExecuteButtonAtBottom(container, features);
    };
*/

let removeButton = document.createElement("button");
removeButton.textContent = "-";
removeButton.onclick = () => {
    // Only allow removal if there is more than one condition
    if (container.querySelectorAll(".condition").length > 1) {
        container.removeChild(conditionContainer);
        updateConditionsArray(container); // Update queryConditions
        ensureExecuteButtonAtBottom(container, features);
        updateRemoveButtons(container); // Refresh minus button visibility based on condition count
    }
};


    // Create condition container
    let conditionContainer = document.createElement("div");
    conditionContainer.classList.add("condition");
    conditionContainer.append(propSelect, operatorSelect, valueSelect, manualInput, addButton, removeButton);
    container.appendChild(conditionContainer);

    // Update queryConditions to reflect the current DOM state
    updateConditionsArray(container);

    ensureExecuteButtonAtBottom(container, features);
}



// Function to update `queryConditions` array based on current DOM elements
function updateConditionsArray(container) {
    queryConditions = []; // Clear and re-populate
    container.querySelectorAll(".condition").forEach((conditionElem) => {
        let cond = {
            propSelect: conditionElem.querySelector("select:first-child"),
            operatorSelect: conditionElem.querySelector("select:nth-child(2)"),
            valueSelect: conditionElem.querySelector("select:nth-child(3)"),
            manualInput: conditionElem.querySelector("input"),
        };
        queryConditions.push(cond);
    });
}

function updateRemoveButtons(container) {
    const conditions = container.querySelectorAll(".condition");
    conditions.forEach((condition, index) => {
        const removeButton = condition.querySelector("button:last-child"); // Assuming last button is the remove button
        removeButton.style.display = conditions.length > 1 ? "inline" : "none"; // Show only if more than one condition
    });
}



function ensureExecuteButtonAtBottom(container, features) {
    let executeButton = document.getElementById("executeQueryButton");

    if (executeButton) {
        executeButton.remove();
    }

    executeButton = document.createElement("button");
    executeButton.textContent = "Execute Query";
    executeButton.id = "executeQueryButton";
    executeButton.style.marginTop = "30px";
    executeButton.onclick = () => executeQuery(features);

    container.appendChild(executeButton);
}




// Helper function to populate dropdown options
function populateDropdown(dropdown, options, placeholder) {
    dropdown.innerHTML = "";
    let defaultOption = document.createElement("option");
    defaultOption.text = placeholder;
    defaultOption.disabled = true;
    defaultOption.selected = true;
    dropdown.appendChild(defaultOption);

    options.forEach(option => {
        let opt = document.createElement("option");
        opt.value = option;
        opt.text = option;
        dropdown.appendChild(opt);
    });
}



