// Modified createDropdown function to add "Manual Entry" as the first option
function createDropdown(options, placeholder, isValueDropdown = false) {
    let select = document.createElement("select");

    let defaultOption = document.createElement("option");
    defaultOption.text = placeholder;
    defaultOption.disabled = true;
    defaultOption.selected = true;
    select.appendChild(defaultOption);

    // Add "Manual Entry" option at the top if it's a value dropdown
    if (isValueDropdown) {
        let manualEntryOption = document.createElement("option");
        manualEntryOption.value = "Manual Entry";
        manualEntryOption.text = "Manual Entry";
        select.appendChild(manualEntryOption);
    }

    options.forEach(option => {
        let opt = document.createElement("option");
        opt.value = option;
        opt.text = option;
        select.appendChild(opt);
    });

    return select;
}



function executeQuery(features) {
    if (!activeLayer) return;

    cmpDebugLog("Executing query with conditions:", queryConditions);

    for (let cond of queryConditions) {
        let operator = cond.operatorSelect.value;
        if (operator === "Operator") {
            swal("Operator is not defined");
            return;
        }
    }

    let filteredFeatures = features.filter(feature => {
        return queryConditions.every(cond => {
            let property = cond.propSelect.value;
            let operator = cond.operatorSelect.value;
            let value;

            if (cond.valueSelect.value === "Manual Entry") {
                value = cond.manualInput.value.trim();
                if (!value) {
                    console.warn("Manual entry value is empty");
                    return false;
                }
            } else {
                value = cond.valueSelect.value.trim();
            }

            let featureValue = feature.properties[property];
            if (featureValue === undefined) return false;

            const featureValueToCompare = String(featureValue).trim();
            const valueToCompare = String(value).trim();

            return applyCondition(featureValueToCompare, operator, valueToCompare);
        });
    });

    displayFilteredResults(filteredFeatures);
}



function applyCondition(featureValue, operator, value) {
    // Convert both featureValue and value to strings to ensure consistent comparison
    featureValue = String(featureValue).trim();
    value = String(value).trim();

    //cmpDebugLog(`Applying condition: "${featureValue}" ${operator} "${value}"`);

    switch (operator) {
        case "=":
            // Partial match: checks if featureValue contains the specified value
           // cmpDebugLog(`Checking if "${featureValue}" includes "${value}"`);
            return featureValue.includes(value); // This should enable partial matching
        case ">":
           // cmpDebugLog(`Comparing numerically: ${parseFloat(featureValue)} > ${parseFloat(value)}`);
            return !isNaN(parseFloat(featureValue)) && !isNaN(parseFloat(value)) && parseFloat(featureValue) > parseFloat(value);
        case "<":
          //  cmpDebugLog(`Comparing numerically: ${parseFloat(featureValue)} < ${parseFloat(value)}`);
            return !isNaN(parseFloat(featureValue)) && !isNaN(parseFloat(value)) && parseFloat(featureValue) < parseFloat(value);
        case ">=":
           // cmpDebugLog(`Comparing numerically: ${parseFloat(featureValue)} >= ${parseFloat(value)}`);
            return !isNaN(parseFloat(featureValue)) && !isNaN(parseFloat(value)) && parseFloat(featureValue) >= parseFloat(value);
        case "<=":
           // cmpDebugLog(`Comparing numerically: ${parseFloat(featureValue)} <= ${parseFloat(value)}`);
            return !isNaN(parseFloat(featureValue)) && !isNaN(parseFloat(value)) && parseFloat(featureValue) <= parseFloat(value);
        default:
           // console.warn(`Unexpected operator: ${operator}`);
            return false;
    }
}








