// Global variable to track the update status
let isUpdating = false;


function fetchAvailableDates() {
	
    if (isPlaying) {
        isPlaying = false;
        clearInterval(playInterval);
    }
	
    cmpDebugLog("Executing fetchAvailableDates");
    const bounds = map.getBounds();
    const zoomLevel = map.getZoom();

    if (zoomLevel < 18) {
        console.warn("Zoom level too low for fetching dates.");
        sliderContainer.style.display = "none";
        historicalLayerGroup.clearLayers();
        return;
    }

    showSpinnerforprocess();

    const data = {
        bounds: {
            north: bounds.getNorth(),
            south: bounds.getSouth(),
            east: bounds.getEast(),
            west: bounds.getWest(),
        },
        zoom: zoomLevel,
    };

    fetch("https://cmpmap.com/available-dates", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
    })
        .then((response) => {
            hideSpinnerforprocess();
            if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
            return response.json();
        })
        .then(({ availableDates }) => {
            if (!availableDates || availableDates.length === 0) {
                console.warn("No available dates for the current bounds.");
                sliderContainer.style.display = "none";
                historicalLayerGroup.clearLayers();
                return;
            }

            sliderContainer.style.display = "block";

            // Convert dates to timestamps for the slider
            dateValues = availableDates.map((date) => new Date(date).getTime());
            cmpDebugLog("Updating slider with dates:", dateValues);

            // Calculate step size dynamically based on the smallest interval between dates
            let step = Math.min(...dateValues.slice(1).map((val, i) => val - dateValues[i]));
            if (!isFinite(step)) step = 1; // Ensure step is a valid numeric value

            // Temporarily disable "update" event during slider updates
            timeSlider.noUiSlider.off("update");

            if (!timeSlider.noUiSlider) {
                noUiSlider.create(timeSlider, {
                    start: [dateValues[0]],
                    range: {
                        min: dateValues[0],
                        max: dateValues[dateValues.length - 1],
                    },
                    step: step,
                    pips: {
                        mode: "values",
                        values: dateValues,
                        density: Math.max(1, Math.floor(100 / dateValues.length)),
                        format: {
                            to: (value) => new Date(value).toISOString().split("T")[0],
                        },
                    },
                    tooltips: true,
                });
            } else {
                timeSlider.noUiSlider.updateOptions({
                    start: [dateValues[0]],
                    range: {
                        min: dateValues[0],
                        max: dateValues[dateValues.length - 1],
                    },
                    step: step,
                    pips: {
                        mode: "values",
                        values: dateValues,
                        density: Math.max(1, Math.floor(100 / dateValues.length)),
                        format: {
                            to: (value) => new Date(value).toISOString().split("T")[0],
                        },
                    },
                });
            }

            // Rebind "update" event after slider is fully updated
            timeSlider.noUiSlider.on("update", handleSliderUpdate);
        })
        .catch((error) => {
            console.error("Error fetching available dates:", error);
            hideSpinnerforprocess();
        });
}




// Slider update handler function
function handleSliderUpdate(values, handle) {
    if (isUpdating) return; // Skip if already updating

    isUpdating = true;

    const sliderValue = +values[handle];
    const closestValue = dateValues.reduce((closest, current) =>
        Math.abs(current - sliderValue) < Math.abs(closest - sliderValue)
            ? current
            : closest
    );

    if (sliderValue !== closestValue) {
        timeSlider.noUiSlider.set(closestValue);
    }

    selectedDate = new Date(closestValue).toISOString().split("T")[0];
    cmpDebugLog("Snapped to Date:", selectedDate);

    fetchHistoricalTiles(); // Fetch tiles for the selected date
    isUpdating = false;
}





// Function to move the slider to a specific date index
function setSliderToDateIndex(index) {
    if (index >= 0 && index < dateValues.length) {
        const timestamp = dateValues[index];
        document.getElementById("slider-timewms").noUiSlider.set(timestamp);
        selectedDate = new Date(timestamp).toISOString().split("T")[0]; // Update selected date
        cmpDebugLog("Slider moved to Date:", selectedDate);
        fetchHistoricalTiles(); // Trigger tile fetching after navigation
    }
}

// Function to handle forward and backward navigation
document.getElementById("forward-buttonwms").addEventListener("click", () => {
    const currentIndex = dateValues.indexOf(
        dateValues.find(date => date === new Date(selectedDate).getTime())
    );
    if (currentIndex !== -1 && currentIndex < dateValues.length - 1) {
        setSliderToDateIndex(currentIndex + 1);
    } else {
        console.warn("No more dates available to move forward.");
    }
});

document.getElementById("backward-buttonwms").addEventListener("click", () => {
    const currentIndex = dateValues.indexOf(
        dateValues.find(date => date === new Date(selectedDate).getTime())
    );
    if (currentIndex > 0) {
        setSliderToDateIndex(currentIndex - 1);
    } else {
        console.warn("No more dates available to move backward.");
    }
});





		
		
		
		
		
	let isPlaying = false;
let playInterval;






document.getElementById("play-buttonwms").addEventListener("click", () => {
    if (!isPlaying) {
        isPlaying = true;
        document.getElementById("play-buttonwms").style.display = "none";
        document.getElementById("pause-buttonwms").style.display = "block";

        let currentIndex = dateValues.indexOf(
            dateValues.find((date) => date === new Date(selectedDate).getTime())
        );

        playInterval = setInterval(() => {
            if (currentIndex < dateValues.length - 1) {
                currentIndex++;
            } else {
                currentIndex = 0; // Restart from the beginning
            }

            selectedDate = new Date(dateValues[currentIndex]).toISOString().split("T")[0];

            // Update the slider's position to match the current date
            const timestamp = dateValues[currentIndex];
            document.getElementById("slider-timewms").noUiSlider.set(timestamp);

            // Preload next tile in the cache if not already present
            if (!tileCache.has(selectedDate)) {
                fetchHistoricalTiles();
            }

            // Display current tiles with fade-in/fade-out effect only during playback
            displayCachedTilesWithFade(tileCache.get(selectedDate) || []);
        }, 1000); // Adjust interval (in milliseconds) as needed
    }
});






document.getElementById("pause-buttonwms").addEventListener("click", () => {
    isPlaying = false;
    clearInterval(playInterval);
    document.getElementById("play-buttonwms").style.display = "block";
    document.getElementById("pause-buttonwms").style.display = "none";
});

		
		
function displayCachedTilesWithFade(tiles) {
    if (!tiles || tiles.length === 0) return;

    // Fade out existing tiles
    historicalLayerGroup.eachLayer((layer) => {
        layer.setOpacity(0);
        setTimeout(() => historicalLayerGroup.removeLayer(layer), 500); // Remove after fade-out
    });

    // Fade in new tiles
    tiles.forEach((tile) => {
        const newLayer = L.imageOverlay(tile.url, tile.bounds, { opacity: 0 });
        historicalLayerGroup.addLayer(newLayer);

        setTimeout(() => {
            newLayer.setOpacity(1); // Fade in
        }, 500); // Match fade-out duration
    });
}
		
		
	




function cleanupSlider() {
    const sliderDiv = document.getElementById("timeslidermasterdiv");
    if (sliderDiv) sliderDiv.style.display = "none";

    historicalLayerGroup.clearLayers();
    map.off("moveend", fetchAvailableDates);
    map.off("zoomend", fetchAvailableDates);

    if (isPlaying) {
        isPlaying = false;
        clearInterval(playInterval);
    }

    document.getElementById("play-buttonwms").style.display = "block";
    document.getElementById("pause-buttonwms").style.display = "none";
}	












// Pick the push server base
const isLocalDevelopmentHost = location.hostname === 'localhost' || location.hostname === '127.0.0.1';
const API = isLocalDevelopmentHost
  ? 'http://localhost:3000'
  : 'https://cmpmap.com:3000';

// Call once on load (or after you know window.user)
(async function enablePush() {
  try {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
      console.warn('Push not supported in this browser');
      return;
    }

    if (isLocalDevelopmentHost) {
      console.info('Push setup skipped on localhost');
      return;
    }

    if (!window.isSecureContext) {
      console.warn('Push setup requires a secure context');
      return;
    }

const swUrl = 'serviceWorker.js?updated=13032026f';
    let reg = await navigator.serviceWorker.getRegistration('./');
    if (!reg) {
      reg = await navigator.serviceWorker.register(swUrl);
    }

    // Permission
    const perm = await Notification.requestPermission();
    if (perm !== 'granted') return;

    // PUBLIC key (ok to hardcode) – or fetch from /api/push/vapid-public-key
    const VAPID_PUBLIC_KEY = 'BGELScv4f-pUrw5Lbgdr10K-X5FfGBXdXC6ILyvf_Ew0jfXtGWnNbqfhMVf9wdg30l3zDHM4sUbAnjkv9NescOs';

    const toU8 = (b64) => {
      const padding = '='.repeat((4 - (b64.length % 4)) % 4);
      const base64 = (b64 + padding).replace(/-/g, '+').replace(/_/g, '/');
      const raw = atob(base64);
      const out = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; ++i) out[i] = raw.charCodeAt(i);
      return out;
    };

    // Subscribe
    const sub = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: toU8(VAPID_PUBLIC_KEY)
    });

    // Your logged-in username (you already have this)
    const username = (window.user && String(window.user.username).trim()) || '';
    if (!username) { console.warn('No username available'); return; }

    // Save subscription for THIS user
    await fetch(`${API}/api/push/save`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, subscription: sub })
    });

    cmpDebugLog('Push subscribed for', username);

    // Dev helper: run testPush() in console to ping yourself
    window.testPush = async function () {
      const r = await fetch(`${API}/api/push/send`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          usernames: [username],
          payload: {
            title: 'Hello from CMP GIS',
            body:  'Personal test notification',
            url:   location.origin + '/content/www/'
          }
        })
      });
      cmpDebugLog('send result', await r.json());
      alert('Sent test push (check your device)');
    };
  } catch (e) {
    console.error('Push setup failed:', e);
  }
})();










